//clean up and bail helper used for SHT-derived size calculation
#define CLEANUP_FAIL() do { \
    if (sect_header_entries) { \
        for (int k = 0; k < adjusted_numEntries; ++k) free(sect_header_entries[k]); \
        free(sect_header_entries); \
    } \
    *filtered_numEntries = 0; \
    return NULL; \
} while(0)


/* Allow debug output */
// #define ELF_REASSEMBLY_DEBUG 1

// Keep reconstruction traces optional without suppressing setup or errors.
#define ELF_VERBOSE_LOG(...) do { \
    if (scalpel_state.mode_verbose) { \
        scalpel_log(__VA_ARGS__); \
    } \
} while (0)

// Used for debug / identifying reassembly candidates
#define CARVE_HASH_FINGERPRINT_BYTES 16

/* Heuristics used to reduce false positives for PHT / SHT detection */
#define MIN_CONSECUTIVE_VALID_PHT_ENTRIES 8
#define MIN_CONSECUTIVE_VALID_SHT_ENTRIES 8


