// Small helpers for packing / unpacking r_info
// (extract / pack symbol index / type)

//64-bit
#ifndef ELF32_R_SYM
#define ELF32_R_SYM(i)   ((uint32_t)(((uint32_t)(i)) >> 8))
#endif
#ifndef ELF32_R_TYPE
#define ELF32_R_TYPE(i)  ((uint8_t) ((uint32_t)(i) & 0xffu))
#endif
#ifndef ELF32_R_INFO
static inline uint32_t ELF32_R_INFO(uint32_t sym, uint32_t type) {
    return (sym << 8) | (type & 0xffu);
}
#endif

//32-bit
#ifndef ELF64_R_SYM
#define ELF64_R_SYM(i)   ((uint32_t)((uint64_t)(i) >> 32))
#endif
#ifndef ELF64_R_TYPE
#define ELF64_R_TYPE(i)  ((uint32_t)((uint64_t)(i) & 0xffffffffu))
#endif
#ifndef ELF64_R_INFO
static inline uint64_t ELF64_R_INFO(uint32_t sym, uint32_t type) {
    return ((uint64_t)sym << 32) | (uint64_t)type;
}
#endif

