/*************************************************************/
/* Structs for block-level section validation                */
/*************************************************************/

// Note: everything in this section is currently unused. 
// Since cross-validation logic can drive up memory while offering limited benefits

// Instead, coverage stats are currently the main driver


/************************************************************
 * ValidateResult
 * - Role: tri-state validation outcome for cross-validation checks:
 *     FAIL = definite invalid, INCONCLUSIVE = can't decide, PASS = validated.
 *     Used as return value for the main cross-validation functions. 
 * 
 * - Why: lets scoring penalize real contradictions without penalizing
 *   missing-metadata cases.
 * 
 * - Persistence: return-by-value / local; not stored per-block long-term.
 * - Memory: LOW (typically 4 bytes).
 ************************************************************/
typedef enum {
    VR_FAIL = 0,         /* definitively invalid (structural or anchor-backed failure) */
    VR_INCONCLUSIVE = 1, /* could not validate or invalidate (missing anchors) */
    VR_PASS = 2          /* validated with required anchors (e.g., PHT) */
} ValidateResult;


/************************************************************
 * Summarizes the best contiguous run of valid symbol
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    ValidateResult result; /* PASS / INCONCLUSIVE / FAIL */
    bool           is_rela; /* chosen flavor when a run is found */
    uint64_t       start;   /* byte offset (within component slice) of first entry */
    uint64_t       count;   /* number of consecutive validated entries */
    uint64_t       entry_size; /* size of each entry for chosen flavor */
    bool           used_segments; /* true iff PT_LOAD containment was enforced */
    bool           used_machine;  /* true iff psABI type allowlist was applied */
    uint64_t span_bytes; /* how big the validated span is */
} RelocScanResult;


/************************************************************
 * Summarizes the best contiguous run of valid relocation
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    ValidateResult result;  /* VR_FAIL / VR_INCONCLUSIVE / VR_PASS */
    uint64_t start;           /* byte-alignment offset within slice */
    uint64_t count;           /* number of consecutive entries */
    uint64_t entry_size;      /* sizeof(Elf{32,64}_Sym) */
    bool     used_segments;   /* true if PT_LOAD containment enforced */
    uint64_t span_bytes; /* how big the validated span is */
} SymbolScanResult;


/************************************************************
 * Summarizes the best contiguous run of valid Elf{32,64}_Dyn
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    uint64_t start;       /* offset (within component slice) where the run starts */
    uint64_t count;       /* number of consecutive entries */
    uint64_t entry_size;  /* sizeof(ElfXX_Dyn) actually used */
    bool     saw_dt_null; /* whether a DT_NULL was encountered inside the run */
    ValidateResult result; /* VR_PASS / VR_INCONCLUSIVE / VR_FAIL */
    uint64_t span_bytes; /* how big the validated span is */
} DynamicScanResult;


/* 
    DynamicView is a cheap extracted summary of DT_ metadata* from a candidate’s .dynamic region. 
    It allows for powerful cross-valiation with components such as relocations, symbols, and strings.
    
    These structures do not persist in memory. 
*/
typedef struct {
    /* Relocations (main) */
    bool     has_rela;
    uint64_t rela_va;
    uint64_t rela_sz;
    uint64_t rela_ent;

    bool     has_rel;
    uint64_t rel_va;
    uint64_t rel_sz;
    uint64_t rel_ent;

    /* PLT relocations */
    bool     has_jmprel;
    uint64_t jmprel_va;
    uint64_t jmprel_sz;
    bool     jmprel_is_rela;

    /* Dynamic symbols / strings */
    bool     has_symtab;
    uint64_t symtab_va;
    uint64_t syment;

    bool     has_strtab;
    uint64_t strtab_va;
    uint64_t strsz;

    /* Hash tables  */
    bool     has_sysv_hash;
    uint64_t sysv_hash_va;
    uint32_t dynsym_count_sysv;

    bool     has_gnu_hash;
    uint64_t gnu_hash_va;
    uint32_t gnu_symoffset;

    /* Policy bits */
    bool     textrel_present;
} DynamicView;


