/*          FILE, BLOCK, HEADER, AND METADATA VALIDATION       */
/***************************************************************/


/**
 * @brief Scalpel needle-discovery callback for ELF file headers.
 *
 * Scans the region [@p base + @p offset, @p base + @p offset + @p remaining)
 * for the next valid ELF magic number (0x7f 'E' 'L' 'F') and validates the
 * surrounding header fields before accepting it as a genuine candidate. On
 * success, sets @p *matchpos to the start of the matching header, sets
 * @p *matchlen to 4 (the magic length), and returns NULL. If no valid header
 * is found, sets @p *matchpos to NULL and returns NULL.
 *
 * Candidate filtering applies the following checks in order:
 *
 *   1. Magic — the four-byte ELF magic must be present (found via Boyer-Moore).
 *   2. e_ident — EI_CLASS must be 1 (32-bit) or 2 (64-bit); EI_DATA must be
 *      1 (little-endian) or 2 (big-endian); EI_VERSION must be 1.
 *   3. Core header fields — e_version must be 1; e_type and e_machine must
 *      both be non-zero; e_type must be one of ET_REL (1), ET_EXEC (2),
 *      ET_DYN (3), ET_CORE (4), or an OS/processor-specific value in the
 *      ranges [0xFE00, 0xFEFF] or [0xFF00, 0xFFFF].
 *   4. Layout consistency — checked separately for 32-bit and 64-bit:
 *        - e_ehsize must meet the canonical minimum (≥52 for ELF32, ≥64 for
 *          ELF64); larger values are accepted.
 *        - If e_phnum > 0: e_phoff and e_phentsize must both be non-zero.
 *        - If e_shnum > 0: e_shoff and e_shentsize must both be non-zero, and
 *          e_shstrndx must be less than e_shnum (unless it is 0xFFFF, the
 *          sentinel for an extended index).
 *
 * Hits that fail any check are skipped and the search resumes one byte past
 * the rejected magic. All multi-byte fields are read with endianness derived
 * from EI_DATA, so both little- and big-endian ELF files are handled.
 *
 * @param base       Pointer to the start of the search buffer.
 * @param offset     Byte offset within @p base at which to begin searching.
 * @param remaining  Number of bytes available from @p base + @p offset.
 * @param matchpos   Out-parameter: set to the start of the accepted header,
 *                   or NULL if no valid header was found.
 * @param matchlen   Out-parameter: set to 4 (the ELF magic length) on any
 *                   return from this function.
 * @param blocksize  Unused; present to satisfy the scalpel discovery callback
 *                   signature.
 * @return           Always NULL (footer search is not used for ELF).
 */
static inline char *elf_header_discovery(char *base,
                                        uint64_t offset,
                                        uint64_t remaining,
                                        char **matchpos,
                                        uint32_t *matchlen,
                                        uint32_t blocksize){
  (void)blocksize; // not used here

  static char ELF_MAGIC[4] = { '\x7f', 'E', 'L', 'F' };
  size_t table[UCHAR_MAX + 1];

  *matchlen = 4;
  init_bm_table(ELF_MAGIC, table, *matchlen, true);

  base += offset;
  char *p = find_binary_string(ELF_MAGIC, *matchlen, base, remaining, table, true);

  // Offsets in ELF header (relative to p)
  const uint32_t EI_CLASS      = 4;  // 1=ELF32, 2=ELF64
  const uint32_t EI_DATA       = 5;  // 1=little, 2=big
  const uint32_t EI_VERSION    = 6;  // must be 1

  const uint32_t E_TYPE_OFF    = 0x10; // u16
  const uint32_t E_MACHINE_OFF = 0x12; // u16
  const uint32_t E_VERSION_OFF = 0x14; // u32

  while (p) {
    // Need at least an ELF32 header to continue
    if ((uint64_t)(p - base) + 52 > remaining) goto NEXT_HIT;

    // e_ident checks
    const unsigned char *pi = (const unsigned char*)p;
    uint8_t cls      = pi[EI_CLASS];      // 1 or 2
    uint8_t data_enc = pi[EI_DATA];       // 1 or 2
    uint8_t identver = pi[EI_VERSION];    // must be 1
    if (!((cls == 1 || cls == 2) && (data_enc == 1 || data_enc == 2) && identver == 1))
      goto NEXT_HIT;

    int le = (data_enc == 1); // 1=little, 0=big

    // Core fields shared by 32/64
    uint16_t e_type, e_machine;
    uint32_t e_version;
    if (!read16_at(base, remaining, p, E_TYPE_OFF,    le, &e_type))    goto NEXT_HIT;
    if (!read16_at(base, remaining, p, E_MACHINE_OFF, le, &e_machine)) goto NEXT_HIT;
    if (!read32_at(base, remaining, p, E_VERSION_OFF, le, &e_version)) goto NEXT_HIT;

    if (e_version != 1) goto NEXT_HIT;
    if (e_type == 0)     goto NEXT_HIT;
    if (e_machine == 0)  goto NEXT_HIT;

    // Accept common types + OS/proc-specific ranges
    if (!(e_type == 1 || e_type == 2 || e_type == 3 || e_type == 4 ||
          (e_type >= 0xFE00 && e_type <= 0xFEFF) ||
          (e_type >= 0xFF00 && e_type <= 0xFFFF)))
      goto NEXT_HIT;

    if (cls == 1) {
        // ---------------- ELF32 ----------------
        if ((uint64_t)(p - base) + 52 > remaining) goto NEXT_HIT;

        uint16_t e_ehsize, e_phentsize, e_phnum, e_shentsize, e_shnum, e_shstrndx;
        uint32_t e_phoff, e_shoff;

        if (!read16_at(base, remaining, p, 0x28, le, &e_ehsize))    goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x2A, le, &e_phentsize)) goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x2C, le, &e_phnum))     goto NEXT_HIT;
        if (!read32_at(base, remaining, p, 0x1C, le, &e_phoff))     goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x2E, le, &e_shentsize)) goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x30, le, &e_shnum))     goto NEXT_HIT;
        if (!read32_at(base, remaining, p, 0x20, le, &e_shoff))     goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x32, le, &e_shstrndx))  goto NEXT_HIT;

        // Relaxed: require at least the canonical size, but allow larger
        if (e_ehsize < 52) goto NEXT_HIT;

        // PHT: relaxed
        if (e_phnum > 0) {
            if (e_phoff == 0) goto NEXT_HIT;        // need some offset
            if (e_phentsize == 0) goto NEXT_HIT;    // can't have entries of size 0
        }
        // If e_phnum == 0, don't care about e_phoff/e_phentsize here.

        // SHT: relaxed
        if (e_shnum > 0) {
            if (e_shoff == 0) goto NEXT_HIT;
            if (e_shentsize == 0) goto NEXT_HIT;
            if (e_shstrndx >= e_shnum && e_shstrndx != 0xFFFF) goto NEXT_HIT;
        }
        // If e_shnum == 0, don't care about e_shoff/e_shentsize/e_shstrndx.

        *matchpos = p;
        return NULL;

    } else {
        // ---------------- ELF64 ----------------
        if ((uint64_t)(p - base) + 64 > remaining) goto NEXT_HIT;

        uint16_t e_ehsize, e_phentsize, e_phnum, e_shentsize, e_shnum, e_shstrndx;
        uint64_t e_phoff, e_shoff;

        if (!read16_at(base, remaining, p, 0x34, le, &e_ehsize))    goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x36, le, &e_phentsize)) goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x38, le, &e_phnum))     goto NEXT_HIT;
        if (!read64_at(base, remaining, p, 0x20, le, &e_phoff))     goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x3A, le, &e_shentsize)) goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x3C, le, &e_shnum))     goto NEXT_HIT;
        if (!read64_at(base, remaining, p, 0x28, le, &e_shoff))     goto NEXT_HIT;
        if (!read16_at(base, remaining, p, 0x3E, le, &e_shstrndx))  goto NEXT_HIT;

        // Relaxed: require at least canonical size
        if (e_ehsize < 64) goto NEXT_HIT;

        // PHT
        if (e_phnum > 0) {
            if (e_phoff == 0) goto NEXT_HIT;
            if (e_phentsize == 0) goto NEXT_HIT;
        }

        // SHT
        if (e_shnum > 0) {
            if (e_shoff == 0) goto NEXT_HIT;
            if (e_shentsize == 0) goto NEXT_HIT;
            if (e_shstrndx >= e_shnum && e_shstrndx != 0xFFFF) goto NEXT_HIT;
        }

        *matchpos = p;
        return NULL;
    }

        NEXT_HIT: {
            uint64_t consumed = (uint64_t)(p + 1 - base);
            if (consumed >= remaining) break;
            char *next = find_binary_string(ELF_MAGIC, *matchlen,
                                            base + consumed, remaining - consumed, table, true);
            p = next;
            }
        }

        *matchpos = NULL;
        return NULL;
}



/*-------------------------------------------------------------*/
/*           BLOCK VALIDATOR HELPER FUNCTIONS                  */
/*-------------------------------------------------------------*/


static inline SectionDataType cls_to_section_type(int cls) {
    switch (cls) {
        case 4:  return SECTION_TEXT;
        case 5:  return SECTION_PLT;
        case 6:  return SECTION_SYMBOL;
        case 7:  return SECTION_STRING;
        case 8:  return SECTION_DYNAMIC;
        case 9:  return SECTION_RELOCATION;
        case 10: return SECTION_COMPRESSED_REL;
        case 11: return SECTION_EH_FRAME;
        case 12: return SECTION_NOTES;
        case 13: return SECTION_HASH;
        default: return SECTION_UNKNOWN;
    }
}



static inline bool contains_shstrtab_markers(const char *buf, size_t n) {
    static const char *known_section_names[] = {
        ".text", ".data", ".plt", ".got", ".bss", ".rodata",
        ".symtab", ".strtab", ".shstrtab", ".rel", ".rela", ".init", ".fini"
    };
    const size_t k = sizeof(known_section_names) / sizeof(known_section_names[0]);

    for (size_t i = 0; i < k; ++i) {
        const char *needle = known_section_names[i];
        if (portable_memmem(buf, n, needle, strlen(needle)) != NULL) return true;
    }
    return false;
}



static inline void ensure_component_capacity(BlockComponent **arr,
                                             size_t *cap,
                                             size_t need_count)
{
    if (*cap >= need_count) {
        return;
    }
    if (need_count > SIZE_MAX / sizeof(**arr)) {
        check_memory_allocation(NULL, __LINE__, __FILE__,
                                "BlockComponents size");
    }

    size_t new_cap = (*cap == 0) ? 16 : *cap;
    while (new_cap < need_count) {
        if (new_cap > SIZE_MAX / 2) {
            new_cap = need_count;
            break;
        }
        new_cap *= 2;
    }

    BlockComponent *tmp =
        (BlockComponent *)realloc(*arr, new_cap * sizeof(**arr));
    check_memory_allocation(tmp, __LINE__, __FILE__, "BlockComponents grow");
    *arr = tmp;
    *cap = new_cap;
}




// helpers to read bytes and assemble integers based on the requested endianness
static inline int read16_at(const char *base, uint64_t length,
                            const char *p, uint32_t off, int little_endian,
                            uint16_t *out)
{
  uint64_t pos = (uint64_t)(p - base) + off;
  if (pos + 2 > length) return 0;
  const unsigned char *q = (const unsigned char *)(base + pos);
  if (little_endian)
    *out = (uint16_t)(q[0] | (uint16_t)q[1] << 8);
  else
    *out = (uint16_t)((uint16_t)q[0] << 8 | q[1]);
  return 1;
}



static inline int read32_at(const char *base, uint64_t length,
                            const char *p, uint32_t off, int little_endian,
                            uint32_t *out)
{
  uint64_t pos = (uint64_t)(p - base) + off;
  if (pos + 4 > length) return 0;
  const unsigned char *q = (const unsigned char *)(base + pos);
  if (little_endian)
    *out = (uint32_t)(  (uint32_t)q[0]
                      | ((uint32_t)q[1] << 8)
                      | ((uint32_t)q[2] << 16)
                      | ((uint32_t)q[3] << 24));
  else
    *out = (uint32_t)( ((uint32_t)q[0] << 24)
                     | ((uint32_t)q[1] << 16)
                     | ((uint32_t)q[2] << 8)
                     |  (uint32_t)q[3]);
  return 1;
}



static inline int read64_at(const char *base, uint64_t length,
                            const char *p, uint32_t off, int little_endian,
                            uint64_t *out)
{
  uint64_t pos = (uint64_t)(p - base) + off;
  if (pos + 8 > length) return 0;
  const unsigned char *q = (const unsigned char *)(base + pos);
  if (little_endian) {
    *out =  (uint64_t)q[0]
          | ((uint64_t)q[1] << 8)
          | ((uint64_t)q[2] << 16)
          | ((uint64_t)q[3] << 24)
          | ((uint64_t)q[4] << 32)
          | ((uint64_t)q[5] << 40)
          | ((uint64_t)q[6] << 48)
          | ((uint64_t)q[7] << 56);
  } else {
    *out =  ((uint64_t)q[0] << 56)
          | ((uint64_t)q[1] << 48)
          | ((uint64_t)q[2] << 40)
          | ((uint64_t)q[3] << 32)
          | ((uint64_t)q[4] << 24)
          | ((uint64_t)q[5] << 16)
          | ((uint64_t)q[6] << 8)
          |  (uint64_t)q[7];
  }
  return 1;
}



// returns true if number is power of two (excluding zero)
static inline bool is_pow2_nonzero(uint64_t x) {
    return x != 0 && ((x & (x - 1)) == 0);
}



static inline bool shdr64_is_full_zero_null(const Section_Header_Entry_64 *sh) {
    return (sh->section_type  == SECTION_TYPE_NULL) &&
           (sh->sect_name_off == 0U) &&
           (sh->flags         == 0ULL) &&
           (sh->sect_mem_addr == 0ULL) &&
           (sh->sect_file_off == 0ULL) &&
           (sh->sect_size     == 0ULL) &&
           (sh->sect_idx      == 0U) &&
           (sh->sect_info     == 0U) &&
           (sh->sect_align    == 0ULL) &&
           (sh->entry_size    == 0ULL);
}



static inline bool shdr32_is_full_zero_null(const Section_Header_Entry_32 *sh) {
    return (sh->section_type  == SECTION_TYPE_NULL) &&
           (sh->sect_name_off == 0U) &&
           (sh->flags         == 0U) &&
           (sh->sect_mem_addr == 0U) &&
           (sh->sect_file_off == 0U) &&
           (sh->sect_size     == 0U) &&
           (sh->sect_idx      == 0U) &&
           (sh->sect_info     == 0U) &&
           (sh->sect_align    == 0U) &&
           (sh->entry_size    == 0U);
}


// returns true if *p contains all zeros
static inline bool is_all_zero_bytes(const void *p, size_t n) {
    const uint8_t *b = (const uint8_t*)p;
    for (size_t i = 0; i < n; i++) if (b[i] != 0) return false;
    return true;
}

/* Functions to determine if PHT / SHT entries are degenerate (all 0's)*/
static inline bool phdr64_is_degenerate(const Program_Header_Entry_64 *ph) {
    /* Common padding pattern: everything zero. */
    if (ph->seg_type == 0 && ph->flags_64 == 0 &&
        ph->seg_offset == 0 && ph->seg_file_size == 0 &&
        ph->seg_mem_size == 0 && ph->alignment == 0) {
        return true;
    }
    return false;
}

static inline bool shdr64_is_degenerate(const Section_Header_Entry_64 *sh) {
    /* Classic padding/null entry shape. */
    if (sh->section_type == 0 &&
        sh->sect_align == 0 &&
        sh->sect_file_off == 0 &&
        sh->sect_size == 0) {
        return true;
    }
    return false;
}

static inline bool phdr32_is_degenerate(const Program_Header_Entry_32 *ph) {
    /* Common padding pattern: everything zero. */
    if (ph->seg_type == 0 &&
        ph->flags_32 == 0 &&
        ph->seg_offset == 0 &&
        ph->seg_file_size == 0 &&
        ph->seg_mem_size == 0 &&
        ph->alignment == 0) {
        return true;
    }
    return false;
}

static inline bool shdr32_is_degenerate(const Section_Header_Entry_32 *sh) {
    /* Classic padding/null entry shape. */
    if (sh->section_type == 0 &&
        sh->sect_align == 0 &&
        sh->sect_file_off == 0 &&
        sh->sect_size == 0) {
        return true;
    }
    return false;
}



/**
 * @brief Check whether a byte range overlaps any already-claimed (non-unknown) component.
 *
 * Iterates over @p bs->components and returns true if the interval
 * [offset, offset + length) overlaps the interval of any component whose type is not
 * COMPONENT_UNKNOWN. Unknown components are ignored.
 *
 * @param bs      BlockState containing the list of components for this block.
 * @param offset  Start of the queried range (byte offset within the block/state space).
 * @param length  Length of the queried range in bytes.
 *
 * @return true if the queried range overlaps any claimed component; false otherwise.
 */
static inline bool is_range_claimed_by_component_for_pht(BlockState *bs, size_t offset, size_t length) {
    size_t end = offset + length;

    for (size_t i = 0; i < bs->num_components; i++) {
        BlockComponent *comp = &bs->components[i];

        // Skip unknowns
        if (comp->type == COMPONENT_UNKNOWN) continue;

        size_t comp_start = comp->blockOffset;
        size_t comp_end   = comp->blockOffset + comp->size;

        // Check if ranges overlap
        if (!(end <= comp_start || offset >= comp_end)) {
            return true;
        }
    }

    return false;
}


static inline bool is_range_claimed_by_component_for_sht(BlockState *bs, size_t offset, size_t length) {
    if (!bs || length == 0) return false;
    size_t end = offset + length;

    for (size_t i = 0; i < bs->num_components; i++) {
        BlockComponent *comp = &bs->components[i];

        if (comp->type == COMPONENT_UNKNOWN) continue;

        /* Ignore “soft” overlaps for SHT detection. */
        if (comp->type == COMPONENT_SECTION) {
            if (comp->section == SECTION_STRING || comp->section == SECTION_SHSTRTAB) {
                continue;
            }
        }

        size_t comp_start = (size_t)comp->blockOffset;
        size_t comp_end   = (size_t)comp->blockOffset + (size_t)comp->size;

        if (!(end <= comp_start || offset >= comp_end)) {
            return true;
        }
    }
    return false;
}


// checks if section is of type NULL or NOBITS. If so, zero offset is allowed
static inline bool allow_zero_off_sht(uint32_t sh_type, uint64_t sh_size) {
    switch (sh_type) {
        case SECTION_TYPE_NULL:
            return true;
        default:
            return (sh_size == 0);
    }
}


/**
 * @brief Scan a block for a 32-bit ELF Section Header Table (SHT) sequence.
 *
 * Slides a window across @p data in 4-byte steps looking for a run of at
 * least MIN_CONSECUTIVE_VALID_SHT_ENTRIES (8) consecutive valid 32-bit
 * Section_Header_Entry_32 records. Each candidate entry is accepted only if
 * it passes all of the following field checks:
 *
 *   - section_type is a recognised ELF section type (is_valid_section_type).
 *   - sect_align is a non-zero power of two and does not exceed 4096.
 *   - sect_file_off is non-zero, unless the type is SHT_NULL or the entry
 *     has zero size (allow_zero_off_sht).
 *   - sect_size is non-zero for all entries after the first.
 *
 * Multi-byte fields are byte-swapped before inspection when @p target_endianness
 * and @p elf_endianness differ.
 *
 * If a qualifying run is found and its byte range does not overlap an already-
 * classified component in the block's persisted BlockState
 * (is_range_claimed_by_component_for_sht), @p out_component is populated with
 * COMPONENT_SHT at the run's block-local offset and byte length, and the
 * function returns true. If the range overlaps an existing component the run
 * is skipped and the search continues. The first non-overlapping qualifying
 * run wins; no scoring is performed.
 *
 * @param data              Pointer to the block's raw bytes.
 * @param blocksize         Number of bytes in @p data.
 * @param target_endianness Endianness of the host running this code.
 * @param elf_endianness    Endianness declared in the ELF file (ELF_LITTLE_ENDIAN
 *                          or ELF_BIG_ENDIAN).
 * @param entry_size        Size of one SHT entry in bytes; must be at least
 *                          SHT_ENTRY_SIZE_32 (40) or the function returns false
 *                          immediately.
 * @param out_component     Populated on success with the detected component's
 *                          type, blockOffset, and size.
 * @param blockhashkey      Opaque key used to retrieve the block's persisted
 *                          BlockState for overlap checking.
 * @param sp              ElfTunables controlling minimum run length, quality gate
 *                        fractions, and empty-entry tolerance. Must not be NULL.
 * @return                  true if a valid SHT run was found and written to
 *                          @p out_component; false otherwise.
 */
static inline bool detect_sht_component_32(char *data,
                                            size_t blocksize,
                                            enum Endianness target_endianness,
                                            char elf_endianness,
                                            size_t entry_size,
                                            BlockComponent *out_component,
                                            void *blockhashkey,
                                            const ElfTunables *sp)
{
    if (!data || !out_component) return false;
    if (entry_size < SHT_ENTRY_SIZE_32 || entry_size > blocksize) return false;

    bool   found       = false;
    size_t best_offset = 0;
    size_t best_count  = 0;
    bool   best_partial = false;

    for (size_t offset = 0; offset + entry_size <= blocksize; offset += 4) {

        size_t valid_count       = 0;
        size_t local_offset      = offset;
        size_t null_count        = 0;
        size_t nonnull_count     = 0;
        size_t degenerate_count  = 0;
        size_t interesting_types = 0;

        while (local_offset + entry_size <= blocksize) {

            Section_Header_Entry_32 sh;
            memcpy(&sh, data + local_offset, sizeof(sh));

            if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
                (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
                sh.section_type  = __builtin_bswap32(sh.section_type);
                sh.sect_align    = __builtin_bswap32(sh.sect_align);
                sh.sect_file_off = __builtin_bswap32(sh.sect_file_off);
                sh.sect_size     = __builtin_bswap32(sh.sect_size);
                sh.sect_name_off = __builtin_bswap32(sh.sect_name_off);
                sh.sect_idx      = __builtin_bswap32(sh.sect_idx);
                sh.sect_info     = __builtin_bswap32(sh.sect_info);
            }

            /* Prevent slack zeros (EOF padding) from extending a run. */
            if (valid_count > 0 && shdr32_is_full_zero_null(&sh) && shdr32_is_degenerate(&sh))
                break;

            if (!is_valid_section_type(sh.section_type)) break;

            /* ELF permits zero to mean that no alignment constraint applies. */
            if (sh.section_type != SECTION_TYPE_NULL) {
                if (sh.sect_align != 0 && !is_pow2_nonzero(sh.sect_align)) break;
            }

            /* Unified alignment cap (matches 64-bit detector). */
            if (sh.sect_align > (1U << 20)) break;

            if (sh.sect_file_off == 0 && !allow_zero_off_sht(sh.section_type, sh.sect_size)) break;

            /* Field sanity bounds. */
            if (sh.sect_name_off > (1U << 20)) break;
            if (sh.sect_idx > 0x10000U || sh.sect_info > 0x10000U) break;

            /* Stat tracking — exclude a legitimate leading all-zero NULL entry. */
            {
                bool is_first_null = (valid_count == 0) && shdr32_is_full_zero_null(&sh);

                if (sh.section_type == SECTION_TYPE_NULL) {
                    if (!is_first_null) null_count++;
                } else {
                    nonnull_count++;
                }

                if (!is_first_null) {
                    if (shdr32_is_degenerate(&sh)) degenerate_count++;
                }
            }

            /* Count interesting types; skip whitelisted empty non-NULL entries. */
            if (!(sh.section_type != SECTION_TYPE_NULL && sh.sect_size == 0)) {
                switch (sh.section_type) {
                    case SECTION_TYPE_PROGBITS:
                    case SECTION_TYPE_STRTAB:
                    case SECTION_TYPE_SYMTAB:
                    case SECTION_TYPE_DYNSYM:
                    case SHT_RELA:
                    case SHT_REL:
                    case SECTION_TYPE_NOBITS:
                        interesting_types++;
                        break;
                    default:
                        break;
                }
            }

            valid_count++;
            local_offset += entry_size;
        }

        if (valid_count < sp->min_consecutive_valid_sht_entries) continue;

        if (nonnull_count == 0) continue;
        if (null_count > (size_t)(valid_count * sp->sht_max_null_fraction)) continue;
        if (degenerate_count > (size_t)(valid_count * sp->sht_max_degenerate_fraction)) continue;
        if (interesting_types == 0) continue;

        BlockState *bs = (BlockState *)block_get_state(blockhashkey);
        if (bs != NULL && is_range_claimed_by_component_for_sht(bs, offset, valid_count * entry_size)) {
#ifdef ELF_REASSEMBLY_DEBUG
            lock_fprintf(stdout,
                "[sht_32_detect] Skipping candidate SHT at offset %zu (length %zu) due to overlap\n",
                offset, valid_count * entry_size);
#endif
            elf_free_block_state((void **)&bs);
            continue;
        }
        elf_free_block_state((void **)&bs);

        if (valid_count > best_count) {
            best_count   = valid_count;
            best_offset  = offset;
            best_partial = (offset + valid_count * entry_size > blocksize);
            found        = true;
        }
    }

    if (!found) return false;

    out_component->type        = COMPONENT_SHT;
    out_component->section     = SECTION_UNKNOWN;
    out_component->blockOffset = best_offset;
    out_component->size        = best_count * entry_size;

#ifdef ELF_REASSEMBLY_DEBUG
    lock_fprintf(stdout,
        "[sht_32_detect] SHT found at offset %zu with %zu entries (size = %" PRIu64 " bytes)%s\n",
        best_offset, best_count, out_component->size,
        best_partial ? " [PARTIAL]" : "");
#endif

    return true;
}



/**
 * @brief Scan a block for a 64-bit ELF Section Header Table (SHT) sequence.
 *
 * Slides a window across @p data in 8-byte steps (with an additional 4-byte
 * start offset tried to handle misaligned tables) looking for runs of at least
 * MIN_CONSECUTIVE_VALID_SHT_ENTRIES (8) consecutive valid 64-bit
 * Section_Header_Entry_64 records. Unlike the 32-bit version, all qualifying
 * runs are scored and the highest-scoring one wins rather than the first.
 *
 * Each candidate entry must pass the following checks to extend the current run:
 *
 *   - A trailing all-zero entry after at least one valid entry terminates the
 *     run early to avoid counting EOF padding as SHT content.
 *   - section_type is a recognised ELF section type (is_valid_section_type).
 *   - sect_align is a non-zero power of two for non-NULL entries, and does
 *     not exceed 2^20.
 *   - sect_file_off is non-zero unless allowed by type/size (allow_zero_off_sht).
 *   - sect_size is non-zero for non-NULL entries after the first, with a
 *     narrow whitelist of types (SHT_NULL, SHT_PROGBITS, SHT_NOBITS) permitted
 *     to have zero size — but only after at least 8 entries have already been
 *     seen and at most one such empty entry is tolerated per run
 *     (allow_zero_size_sht64).
 *   - sect_name_off does not exceed 2^20.
 *   - sect_idx and sect_info do not exceed 0x10000.
 *
 * Multi-byte fields are byte-swapped before inspection when @p target_endianness
 * and @p elf_endianness differ.
 *
 * Runs that pass the minimum length are then filtered by quality:
 *   - At least one non-NULL entry must be present.
 *   - NULL entries must not outnumber non-NULL entries.
 *   - Degenerate entries (all key fields zero) must not exceed one third of
 *     the run.
 *   - At least one entry must be of an "interesting" type (PROGBITS, STRTAB,
 *     SYMTAB, DYNSYM, RELA, REL, NOBITS).
 *   - The run's byte range must not overlap an already-classified component
 *     in the block's persisted BlockState
 *     (is_range_claimed_by_component_for_sht).
 *
 * Qualifying runs are scored as:
 *   (valid_count × 10) + (nonnull_count × 8) + (interesting_types × 10)
 *   − (degenerate_count × 25) − (null_count × 5)
 *
 * The highest-scoring run is written to @p out_component.
 *
 * @param data              Pointer to the block's raw bytes.
 * @param blocksize         Number of bytes in @p data; entry_size must not
 *                          exceed this value or the function returns false
 *                          immediately.
 * @param target_endianness Endianness of the host running this code.
 * @param elf_endianness    Endianness declared in the ELF file (ELF_LITTLE_ENDIAN
 *                          or ELF_BIG_ENDIAN).
 * @param entry_size        Size of one SHT entry in bytes; must be at least
 *                          SHT_ENTRY_SIZE_64 (64) or the function returns false
 *                          immediately.
 * @param out_component     Populated on success with the detected component's
 *                          type, blockOffset, and size.
 * @param blockhashkey      Opaque key used to retrieve the block's persisted
 *                          BlockState for overlap checking.
 * @param sp                ElfTunables controlling minimum run length, quality gate
 *                          fractions, and empty-entry tolerance. Must not be NULL.
 * @return                  true if a valid SHT run was found and written to
 *                          @p out_component; false otherwise.
 */
static inline bool detect_sht_component_64(char *data,
                                            size_t blocksize,
                                            enum Endianness target_endianness,
                                            char elf_endianness,
                                            size_t entry_size,
                                            BlockComponent *out_component,
                                            void *blockhashkey,
                                            const ElfTunables *sp)
{
    if (!data || !out_component) return false;
    if (entry_size < SHT_ENTRY_SIZE_64 || entry_size > blocksize) return false;

    bool   found       = false;
    size_t best_offset = 0;
    size_t best_count  = 0;
    bool   best_partial = false;

    for (size_t start = 0; start <= 4; start += 4) {
        for (size_t offset = start; offset + entry_size <= blocksize; offset += 8) {

            size_t valid_count       = 0;
            size_t local_offset      = offset;
            size_t null_count        = 0;
            size_t nonnull_count     = 0;
            size_t degenerate_count  = 0;
            size_t interesting_types = 0;

            while (local_offset + entry_size <= blocksize) {

                Section_Header_Entry_64 sh;
                memcpy(&sh, data + local_offset, sizeof(sh));

                if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
                    (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
                    sh.section_type  = __builtin_bswap32(sh.section_type);
                    sh.sect_align    = __builtin_bswap64(sh.sect_align);
                    sh.sect_file_off = __builtin_bswap64(sh.sect_file_off);
                    sh.sect_size     = __builtin_bswap64(sh.sect_size);
                    sh.sect_name_off = __builtin_bswap32(sh.sect_name_off);
                    sh.entry_size    = __builtin_bswap64(sh.entry_size);
                    sh.sect_idx      = __builtin_bswap32(sh.sect_idx);
                    sh.sect_info     = __builtin_bswap32(sh.sect_info);
                }

                /* Prevent slack zeros (EOF padding) from extending a run. */
                if (valid_count > 0 && shdr64_is_full_zero_null(&sh) && shdr64_is_degenerate(&sh))
                    break;

                if (!is_valid_section_type(sh.section_type)) break;

                /* ELF permits zero to mean that no alignment constraint applies. */
                if (sh.section_type != SECTION_TYPE_NULL) {
                    if (sh.sect_align != 0 && !is_pow2_nonzero(sh.sect_align)) break;
                }

                if (sh.sect_align > (1ULL << 20)) break;

                if (sh.sect_file_off == 0 && !allow_zero_off_sht(sh.section_type, sh.sect_size)) break;

                if (sh.sect_name_off > (1U << 20)) break;
                if (sh.sect_idx > 0x10000U || sh.sect_info > 0x10000U) break;

                {
                    bool is_first_null = (valid_count == 0) && shdr64_is_full_zero_null(&sh);

                    if (sh.section_type == SECTION_TYPE_NULL) {
                        if (!is_first_null) null_count++;
                    } else {
                        nonnull_count++;
                    }

                    if (!is_first_null) {
                        if (shdr64_is_degenerate(&sh)) degenerate_count++;
                    }
                }

                if (!(sh.section_type != SECTION_TYPE_NULL && sh.sect_size == 0)) {
                    switch (sh.section_type) {
                        case SECTION_TYPE_PROGBITS:
                        case SECTION_TYPE_STRTAB:
                        case SECTION_TYPE_SYMTAB:
                        case SECTION_TYPE_DYNSYM:
                        case SHT_RELA:
                        case SHT_REL:
                        case SECTION_TYPE_NOBITS:
                            interesting_types++;
                            break;
                        default:
                            break;
                    }
                }

                valid_count++;
                local_offset += entry_size;
            }

            if (valid_count < sp->min_consecutive_valid_sht_entries) continue;

            if (nonnull_count == 0) continue;
            if (null_count > (size_t)(valid_count * sp->sht_max_null_fraction)) continue;
            if (degenerate_count > (size_t)(valid_count * sp->sht_max_degenerate_fraction)) continue;
            if (interesting_types == 0) continue;

            BlockState *bs = (BlockState *)block_get_state(blockhashkey);
            if (bs != NULL && is_range_claimed_by_component_for_sht(bs, offset, valid_count * entry_size)) {
#ifdef ELF_REASSEMBLY_DEBUG
                lock_fprintf(stdout,
                    "[sht_64_detect] Skipping candidate SHT at offset %zu (length %zu) due to overlap\n",
                    offset, valid_count * entry_size);
#endif
                elf_free_block_state((void **)&bs);
                continue;
            }
            elf_free_block_state((void **)&bs);

            if (valid_count > best_count) {
                best_count   = valid_count;
                best_offset  = offset;
                best_partial = (offset + valid_count * entry_size > blocksize);
                found        = true;
            }
        }
    }

    if (!found) return false;

    out_component->type        = COMPONENT_SHT;
    out_component->section     = SECTION_UNKNOWN;
    out_component->blockOffset = best_offset;
    out_component->size        = best_count * entry_size;

#ifdef ELF_REASSEMBLY_DEBUG
    lock_fprintf(stdout,
        "[sht_64_detect] SHT found at offset %zu with %zu entries (size = %" PRIu64 " bytes)%s\n",
        best_offset, best_count, out_component->size,
        best_partial ? " [PARTIAL]" : "");
#endif

    return true;
}


// check if zero offset is allowed (NULL or LOAD segment)
static inline bool allow_zero_off_pht(uint32_t seg_type, uint64_t seg_file_size) {
    // For PHT entries, file offset 0 is common/valid for PT_LOAD (the first LOAD
    // segment often starts at byte 0 and includes the ELF header).
    // PT_NULL is a placeholder and can be all zeros.
    // For other types, allow off==0 only if filesz==0 (empty).
    switch (seg_type) {
        case PT_NULL:
        case PT_LOAD:
        case PT_GNU_STACK:
            return true;
        default:
            return (seg_file_size == 0);
    }
}


static inline bool pht_allow_zero_filesz(uint32_t type) {
    switch (type) {
        case PT_NULL:
        case PT_GNU_STACK:
        case PT_TLS:
            return true;
        default:
            return false;
    }
}


//Valid PHT segment type?
static inline bool seg_type_valid(uint32_t t) {
    return ((t >= PT_NULL   && t <= PT_TLS)   ||
            (t >= SEGMENT_TYPE_LOOS   && t <= SEGMENT_TYPE_HIOS) ||
            (t >= SEGMENT_TYPE_LOPROC && t <= SEGMENT_TYPE_HIPROC));
}



/**
 * @brief Scan a block for a 64-bit ELF Program Header Table (PHT) sequence.
 *
 * Slides a window across @p data in 8-byte steps (with an additional 4-byte
 * start offset tried to handle misaligned tables) looking for runs of at least
 * MIN_CONSECUTIVE_VALID_PHT_ENTRIES (8) consecutive valid 64-bit
 * Program_Header_Entry_64 records. Unlike the 32-bit version, all qualifying
 * runs are scored and the highest-scoring one wins rather than the first.
 *
 * Each candidate entry must pass the following checks to extend the current run:
 *
 *   - seg_type is a recognised ELF segment type (seg_type_valid).
 *   - flags_64 contains no bits outside the allowed set (PF_R, PF_W, PF_X,
 *     PF_MASKOS, PF_MASKPROC).
 *   - flags_64 is non-zero for all non-PT_NULL, non-PT_GNU_STACK entries
 *     (zero flags on a real segment is considered implausible).
 *   - alignment is 0, 1, or a non-zero power of two, and does not exceed 2^20.
 *   - seg_mem_size is greater than or equal to seg_file_size.
 *   - seg_offset is non-zero unless the type is PT_NULL, PT_LOAD, or
 *     PT_GNU_STACK, or seg_file_size is zero (allow_zero_off_pht).
 *   - seg_file_size is non-zero for all entries after the first, unless the
 *     type is PT_NULL, PT_GNU_STACK, or PT_TLS (pht_allow_zero_filesz).
 *
 * Multi-byte fields are byte-swapped before inspection when @p target_endianness
 * and @p elf_endianness differ.
 *
 * Runs that reach the minimum length are then filtered by quality:
 *   - At least one non-PT_NULL entry must be present.
 *   - PT_NULL entries (excluding a legitimate leading PT_NULL) must not
 *     outnumber total entries.
 *   - Degenerate entries (all key fields zero, excluding a leading PT_NULL)
 *     must not exceed one third of the run.
 *   - Runs of 6 or more entries must contain at least one PT_LOAD segment.
 *   - The run's byte range must not overlap an already-classified component
 *     in the block's persisted BlockState
 *     (is_range_claimed_by_component_for_pht).
 *
 * Qualifying runs are scored as:
 *   (valid_count × 10) + (nonnull_count × 8) + (load_count × 15)
 *   − (degenerate_count × 25) − (null_count × 5)
 *
 * The highest-scoring run is written to @p out_component.
 *
 * @param data              Pointer to the block's raw bytes.
 * @param blocksize         Number of bytes in @p data; entry_size must not
 *                          exceed this value or the function returns false
 *                          immediately.
 * @param target_endianness Endianness of the host running this code.
 * @param elf_endianness    Endianness declared in the ELF file (ELF_LITTLE_ENDIAN
 *                          or ELF_BIG_ENDIAN).
 * @param entry_size        Size of one PHT entry in bytes; must be at least
 *                          PHT_ENTRY_SIZE_64 (56) or the function returns false
 *                          immediately.
 * @param out_component     Populated on success with the detected component's
 *                          type, blockOffset, and size.
 * @param blockhashkey      Opaque key used to retrieve the block's persisted
 *                          BlockState for overlap checking.
 * @param sp              ElfTunables controlling minimum run length, quality gate
 *                        fractions, and empty-entry tolerance. Must not be NULL.
 * @return                  true if a valid PHT run was found and written to
 *                          @p out_component; false otherwise.
 */
static inline bool detect_pht_component_64(char *data,
                                            size_t blocksize,
                                            enum Endianness target_endianness,
                                            char elf_endianness,
                                            size_t entry_size,
                                            BlockComponent *out_component,
                                            void *blockhashkey,
                                            const ElfTunables *sp)
{
    if (!data || !out_component) return false;
    if (entry_size < PHT_ENTRY_SIZE_64 || entry_size > blocksize) return false;

    bool   found       = false;
    size_t best_offset = 0;
    size_t best_count  = 0;
    bool   best_partial = false;

    /* Try 8-byte aligned offsets, and also 4-byte-shifted to handle misaligned tables. */
    for (size_t start = 0; start <= 4; start += 4) {
        for (size_t offset = start; offset + entry_size <= blocksize; offset += 8) {

            size_t valid_count      = 0;
            size_t local_offset     = offset;
            size_t null_count       = 0;
            size_t nonnull_count    = 0;
            size_t load_count       = 0;
            size_t degenerate_count = 0;
            bool   first_is_null    = false;

            while (local_offset + entry_size <= blocksize) {

                Program_Header_Entry_64 ph;
                memcpy(&ph, data + local_offset, sizeof(ph));

                if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
                    (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
                    ph.seg_type      = __builtin_bswap32(ph.seg_type);
                    ph.flags_64      = __builtin_bswap32(ph.flags_64);
                    ph.seg_offset    = __builtin_bswap64(ph.seg_offset);
                    ph.seg_file_size = __builtin_bswap64(ph.seg_file_size);
                    ph.seg_mem_size  = __builtin_bswap64(ph.seg_mem_size);
                    ph.alignment     = __builtin_bswap64(ph.alignment);
                }

                if (valid_count > 0 && phdr64_is_degenerate(&ph)) break;

                if (!seg_type_valid(ph.seg_type)) break;

                /* Flags must be subset of allowed. */
                uint32_t allowed = PF_R | PF_W | PF_X | PF_MASKOS | PF_MASKPROC;
                if (ph.flags_64 & ~allowed) break;

                /* Non-NULL, non-GNU_STACK entries with zero flags are implausible. */
                if (ph.seg_type != PT_NULL &&
                    ph.seg_type != PT_GNU_STACK &&
                    ph.flags_64 == 0) break;

                /* Alignment: 0, 1, or non-zero power of two. */
                if (!(ph.alignment == 0 || ph.alignment == 1 || is_pow2_nonzero(ph.alignment)))
                    break;

                /* Alignment cap. */
                if (ph.alignment > (1ULL << 20)) break;

                /* Strong invariant: memsz >= filesz. */
                if (ph.seg_mem_size < ph.seg_file_size) break;

                /* Zero-offset rules. */
                if (ph.seg_offset == 0 && !allow_zero_off_pht(ph.seg_type, ph.seg_file_size))
                    break;

                /* Zero-filesz: allow a whitelisted set of types. */
                if (valid_count > 0 && ph.seg_file_size == 0 && !pht_allow_zero_filesz(ph.seg_type))
                    break;

                /* Track whether the very first entry is PT_NULL. */
                if (valid_count == 0 && ph.seg_type == PT_NULL)
                    first_is_null = true;

                /* Stat tracking — exclude legitimate leading PT_NULL from penalty counts. */
                if (ph.seg_type == PT_NULL) {
                    if (!first_is_null) null_count++;
                } else {
                    nonnull_count++;
                }

                if (ph.seg_type == PT_LOAD) load_count++;

                if (!first_is_null) {
                    if (phdr64_is_degenerate(&ph)) degenerate_count++;
                }

                valid_count++;
                local_offset += entry_size;
            }

            if (valid_count < sp->min_consecutive_valid_pht_entries) continue;

            if (nonnull_count == 0) continue;
            if (null_count > (size_t)(valid_count * sp->pht_max_null_fraction)) continue;
            if (degenerate_count > (size_t)(valid_count * sp->pht_max_degenerate_fraction)) continue;
            if (valid_count >= sp->pht_load_required_min_entries && load_count == 0) continue;

            BlockState *bs = (BlockState *)block_get_state(blockhashkey);
            if (bs != NULL && is_range_claimed_by_component_for_pht(bs, offset, valid_count * entry_size)) {
#ifdef ELF_REASSEMBLY_DEBUG
                lock_fprintf(stdout,
                    "[pht_64_detect] Skipping candidate PHT at offset %zu (length %zu) due to overlap\n",
                    offset, valid_count * entry_size);
#endif
                elf_free_block_state((void **)&bs);
                continue;
            }
            elf_free_block_state((void **)&bs);

            if (valid_count > best_count) {
                best_count   = valid_count;
                best_offset  = offset;
                best_partial = (local_offset + entry_size > blocksize);
                found        = true;
            }
        }
    }

    if (!found) return false;

    out_component->type        = COMPONENT_PHT;
    out_component->section     = SECTION_UNKNOWN;
    out_component->blockOffset = best_offset;
    out_component->size        = best_count * entry_size;

#ifdef ELF_REASSEMBLY_DEBUG
    lock_fprintf(stdout,
        "[pht_64_detect] PHT found at offset %zu with %zu entries (size = %" PRIu64 " bytes)%s\n",
        best_offset, best_count, out_component->size,
        best_partial ? " [PARTIAL]" : "");
#endif

    return true;
}



/**
 * @brief Scan a block for a 32-bit ELF Program Header Table (PHT) sequence.
 *
 * Slides a window across @p data in 4-byte steps looking for a run of at
 * least MIN_CONSECUTIVE_VALID_PHT_ENTRIES (8) consecutive valid 32-bit
 * Program_Header_Entry_32 records. Each candidate entry is accepted only if
 * it passes all of the following checks:
 *
 *   - seg_type is a recognised ELF segment type (seg_type_valid): one of the
 *     standard PT_* values [PT_NULL, PT_TLS], an OS-specific value in
 *     [SEGMENT_TYPE_LOOS, SEGMENT_TYPE_HIOS], or a processor-specific value
 *     in [SEGMENT_TYPE_LOPROC, SEGMENT_TYPE_HIPROC].
 *   - flags_32 contains no bits outside the allowed set (PF_R, PF_W, PF_X,
 *     PF_MASKOS, PF_MASKPROC).
 *   - alignment is 0, 1, or a non-zero power of two.
 *   - seg_offset is non-zero unless the type is PT_NULL, PT_LOAD, or
 *     PT_GNU_STACK, or seg_file_size is zero (allow_zero_off_pht).
 *   - seg_file_size is non-zero for all entries after the first.
 *
 * Multi-byte fields are byte-swapped before inspection when @p target_endianness
 * and @p elf_endianness differ.
 *
 * If a qualifying run is found and its byte range does not overlap an already-
 * classified component in the block's persisted BlockState
 * (is_range_claimed_by_component_for_pht), @p out_component is populated with
 * COMPONENT_PHT at the run's block-local offset and byte length, and the
 * function returns true immediately. If the range overlaps, the run is skipped
 * and the search continues. The first non-overlapping qualifying run wins;
 * no scoring is performed.
 *
 * @param data              Pointer to the block's raw bytes.
 * @param blocksize         Number of bytes in @p data.
 * @param target_endianness Endianness of the host running this code.
 * @param elf_endianness    Endianness declared in the ELF file (ELF_LITTLE_ENDIAN
 *                          or ELF_BIG_ENDIAN).
 * @param entry_size        Size of one PHT entry in bytes; must be at least
 *                          PHT_ENTRY_SIZE_32 (32) or the function returns false
 *                          immediately.
 * @param out_component     Populated on success with the detected component's
 *                          type, blockOffset, and size.
 * @param blockhashkey      Opaque key used to retrieve the block's persisted
 *                          BlockState for overlap checking.
 * @param sp              ElfTunables controlling minimum run length, quality gate
 *                        fractions, and empty-entry tolerance. Must not be NULL.
 * @return                  true if a valid PHT run was found and written to
 *                          @p out_component; false otherwise.
 */
static inline bool detect_pht_component_32(char *data,
                                            size_t blocksize,
                                            enum Endianness target_endianness,
                                            char elf_endianness,
                                            size_t entry_size,
                                            BlockComponent *out_component,
                                            void *blockhashkey,
                                            const ElfTunables *sp)
{
    if (!data || !out_component) return false;
    if (entry_size < PHT_ENTRY_SIZE_32 || entry_size > blocksize) return false;

    bool   found       = false;
    size_t best_offset = 0;
    size_t best_count  = 0;
    bool   best_partial = false;

    for (size_t offset = 0; offset + entry_size <= blocksize; offset += 4) {

        size_t valid_count      = 0;
        size_t local_offset     = offset;
        size_t null_count       = 0;
        size_t nonnull_count    = 0;
        size_t load_count       = 0;
        size_t degenerate_count = 0;
        bool   first_is_null    = false;

        while (local_offset + entry_size <= blocksize) {

            Program_Header_Entry_32 ph;
            memcpy(&ph, data + local_offset, sizeof(ph));

            if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
                (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
                ph.seg_type      = __builtin_bswap32(ph.seg_type);
                ph.flags_32      = __builtin_bswap32(ph.flags_32);
                ph.seg_offset    = __builtin_bswap32(ph.seg_offset);
                ph.seg_file_size = __builtin_bswap32(ph.seg_file_size);
                ph.seg_mem_size  = __builtin_bswap32(ph.seg_mem_size);
                ph.alignment     = __builtin_bswap32(ph.alignment);
            }

            if (valid_count > 0 && phdr32_is_degenerate(&ph)) break;

            if (!seg_type_valid(ph.seg_type)) break;

            /* Flags must be subset of allowed. */
            uint32_t allowed = PF_R | PF_W | PF_X | PF_MASKOS | PF_MASKPROC;
            if (ph.flags_32 & ~allowed) break;

            /* Non-NULL, non-GNU_STACK entries with zero flags are implausible. */
            if (ph.seg_type != PT_NULL &&
                ph.seg_type != PT_GNU_STACK &&
                ph.flags_32 == 0) break;

            /* Alignment: 0, 1, or non-zero power of two. */
            if (!(ph.alignment == 0 || ph.alignment == 1 || is_pow2_nonzero((uint64_t)ph.alignment)))
                break;

            /* Alignment cap (matches 64-bit detector). */
            if (ph.alignment > (1U << 20)) break;

            /* Strong invariant: memsz >= filesz. */
            if (ph.seg_mem_size < ph.seg_file_size) break;

            /* Zero-offset rules. */
            if (ph.seg_offset == 0 && !allow_zero_off_pht(ph.seg_type, (uint64_t)ph.seg_file_size))
                break;

            /* Zero-filesz: allow a whitelisted set of types. */
            if (valid_count > 0 && ph.seg_file_size == 0 && !pht_allow_zero_filesz(ph.seg_type))
                break;

            /* Track whether the very first entry is PT_NULL. */
            if (valid_count == 0 && ph.seg_type == PT_NULL)
                first_is_null = true;

            /* Stat tracking — exclude legitimate leading PT_NULL from penalty counts. */
            if (ph.seg_type == PT_NULL) {
                if (!first_is_null) null_count++;
            } else {
                nonnull_count++;
            }

            if (ph.seg_type == PT_LOAD) load_count++;

            if (!first_is_null) {
                if (phdr32_is_degenerate(&ph)) degenerate_count++;
            }

            valid_count++;
            local_offset += entry_size;
        }

        if (valid_count < sp->min_consecutive_valid_pht_entries) continue;

        if (nonnull_count == 0) continue;
        if (null_count > (size_t)(valid_count * sp->pht_max_null_fraction)) continue;
        if (degenerate_count > (size_t)(valid_count * sp->pht_max_degenerate_fraction)) continue;
        if (valid_count >= sp->pht_load_required_min_entries && load_count == 0) continue;

        BlockState *bs = (BlockState *)block_get_state(blockhashkey);
        if (bs != NULL && is_range_claimed_by_component_for_pht(bs, offset, valid_count * entry_size)) {
#ifdef ELF_REASSEMBLY_DEBUG
            lock_fprintf(stdout,
                "[pht_32_detect] Skipping candidate PHT at offset %zu (length %zu) due to overlap\n",
                offset, valid_count * entry_size);
#endif
            elf_free_block_state((void **)&bs);
            continue;
        }
        elf_free_block_state((void **)&bs);

        if (valid_count > best_count) {
            best_count   = valid_count;
            best_offset  = offset;
            best_partial = (local_offset + entry_size > blocksize);
            found        = true;
        }
    }

    if (!found) return false;

    out_component->type        = COMPONENT_PHT;
    out_component->section     = SECTION_UNKNOWN;
    out_component->blockOffset = best_offset;
    out_component->size        = best_count * entry_size;

#ifdef ELF_REASSEMBLY_DEBUG
    lock_fprintf(stdout,
        "[pht_32_detect] PHT found at offset %zu with %zu entries (size = %" PRIu64 " bytes)%s\n",
        best_offset, best_count, out_component->size,
        best_partial ? " [PARTIAL]" : "");
#endif

    return true;
}



void *portable_memmem(const void *haystack, size_t haystacklen,
                      const void *needle, size_t needlelen) {
    if (needlelen == 0 || haystacklen < needlelen){
        return NULL;
    }

    const uint8_t *h = (const uint8_t *)haystack;
    const uint8_t *n = (const uint8_t *)needle;

    size_t skip[256];
    for (size_t i = 0; i < 256; ++i) {
        skip[i] = needlelen;
    }
    for (size_t i = 0; i < needlelen - 1; ++i) {
        skip[n[i]] = needlelen - i - 1;
    }

    size_t index = 0;
    while (index <= haystacklen - needlelen) {
        size_t j = needlelen - 1;
        while (h[index + j] == n[j]) {
            if (j == 0) {
                return (void *)(h + index);
            }
            --j;
        }
        index += skip[h[index + needlelen - 1]];
    }

    return NULL;
}



/*-------------------------------------------------------------*/
/*             FILE VALIDATOR HELPER DEFINITIONS               */
/*-------------------------------------------------------------*/


static inline void free_sht_entries_32(Section_Header_Entry_32** sht_entries, int numEntries){
    if (!sht_entries) return;
    for (int i = 0; i < numEntries; i++){
        free(sht_entries[i]);
        sht_entries[i] = NULL;
    }
    free(sht_entries);
}


static inline void free_sht_entries_64(Section_Header_Entry_64** sht_entries, int numEntries){
    if (!sht_entries) return;
    for (int i = 0; i < numEntries; i++){
        free(sht_entries[i]);
        sht_entries[i] = NULL;
    }
    free(sht_entries);
}



/**
 * @Description                 Takes an array of 32-bit section header entry pointers
 *                              and returns a new array with all NULL values filtered out
 * @param arr                   An array containing the section header entries, plus the PHT and SHT
 *                              size/offset info encoded within an SHT entry struct.
 * @param size                  The size of this array
 * @param newsize               a pointer to an int for returning the size of the filtered array
 * @return                      The total size of the elf header.
 *
*/
static inline Section_Header_Entry_32** filter_null_32(Section_Header_Entry_32** arr, int size, int* newsize){
    if (!newsize) return NULL;
    if (!arr || size <= 0) { *newsize = 0; return NULL; }

    int nonNullCount = 0;
    for (int i = 0; i < size; i++) if (arr[i] != NULL) nonNullCount++;

    *newsize = nonNullCount;
    if (nonNullCount == 0) {
        return NULL;
    }

    Section_Header_Entry_32** out =
        (Section_Header_Entry_32**)malloc((size_t)nonNullCount * sizeof(*out));
    check_memory_allocation(out, __LINE__, __FILE__, "filter_null_32 out");
    if (!out) { *newsize = 0; return NULL; }

    int j = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] != NULL) out[j++] = arr[i];
    }

    return out;
}


/**
 * @Description                 Takes an array of 64-bit section header entry pointers
 *                              and returns a new array with all NULL values filtered out
 * @param arr                   An array containing the section header entries, plus the PHT and SHT
 *                              size/offset info encoded within an SHT entry struct.
 * @param size                  The size of this array
 * @param newsize               a pointer to an int for returning the size of the filtered array
 * @return                      The total size of the elf header.
 *
*/
static inline Section_Header_Entry_64** filter_null_64(Section_Header_Entry_64** arr, int size, int* newsize){
    if (!newsize) return NULL;
    if (!arr || size <= 0) { *newsize = 0; return NULL; }

    int nonNullCount = 0;
    for (int i = 0; i < size; i++) if (arr[i] != NULL) nonNullCount++;

    *newsize = nonNullCount;
    if (nonNullCount == 0) {
        return NULL;
    }

    Section_Header_Entry_64** out =
        (Section_Header_Entry_64**)malloc((size_t)nonNullCount * sizeof(*out));
    check_memory_allocation(out, __LINE__, __FILE__, "filter_null_64 out");
    if (!out) { *newsize = 0; return NULL; }

    int j = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] != NULL) out[j++] = arr[i];
    }

    return out;
}


/**
 * @brief Compute the total file size of a 32-bit ELF from its Section Header Table.
 *
 * Finds the highest-reaching file-resident section in @p arr (i.e. the entry
 * with the greatest sect_file_off + sect_size) and returns that value as the
 * exact described file extent.
 *
 * Sections of type SHT_NOBITS (.bss) and SHT_NULL are excluded because they
 * occupy no bytes in the file. The ELF header size is used as the initial
 * high-water mark so that files with no sections return a sensible minimum.
 *
 * Callers are expected to inject synthetic entries for the PHT and SHT into
 * @p arr before calling this function, ensuring those regions are included in
 * the high-water mark calculation.
 *
 * If @p arr is NULL or @p numEntries is zero, the function falls back to the
 * ELF header size alone.
 *
 * @param arr         Array of pointers to filtered 32-bit SHT entries.
 *                    May be NULL if no SHT is available. Does not need to be
 *                    sorted.
 * @param elf_header  Parsed 32-bit ELF header; provides the initial minimum
 *                    size. Must not be NULL.
 * @param numEntries  Number of valid entries in @p arr. Treated as empty if <= 0.
 *
 * @return            Estimated total file size in bytes.
 *                    @c UINT64_MAX is returned if an entry range overflows.
 */
static inline uint64_t calculate_elf_size_32(Section_Header_Entry_32 **arr,
                               Elf_Header_32            *elf_header,
                               int                       numEntries)
{
    uint64_t max_end = elf_header->elf_header_size;

    if (numEntries <= 0 || arr == NULL) {
        return max_end;
    }

    for (int i = 0; i < numEntries; i++) {
        if (arr[i]->section_type == SECTION_TYPE_NOBITS ||
            arr[i]->section_type == SECTION_TYPE_NULL) continue;

        uint64_t end;
        if (__builtin_add_overflow((uint64_t)arr[i]->sect_file_off,
                                   (uint64_t)arr[i]->sect_size, &end)) {
            return UINT64_MAX;
        }
        if (end > max_end) max_end = end;
    }

    return max_end;
}



/**
 * @brief Compute the total file size of a 64-bit ELF from its Section Header Table.
 *
 * Finds the highest-reaching file-resident section in @p arr (i.e. the entry
 * with the greatest sect_file_off + sect_size) and returns that value as the
 * exact described file extent.
 *
 * Sections of type SHT_NOBITS (.bss) and SHT_NULL are excluded because they
 * occupy no bytes in the file. The ELF header size is used as the initial
 * high-water mark so that files with no sections return a sensible minimum.
 *
 * Callers are expected to inject synthetic entries for the PHT and SHT into
 * @p arr before calling this function, ensuring those regions are included in
 * the high-water mark calculation.
 *
 * If @p arr is NULL or @p numEntries is zero, the function falls back to the
 * ELF header size alone.
 *
 * @param arr         Array of pointers to filtered 64-bit SHT entries.
 *                    May be NULL if no SHT is available. Does not need to be
 *                    sorted.
 * @param elf_header  Parsed 64-bit ELF header; provides the initial minimum
 *                    size. Must not be NULL.
 * @param numEntries  Number of valid entries in @p arr. Treated as empty if <= 0.
 *
 * @return            Estimated total file size in bytes.
 *                    @c UINT64_MAX is returned if an entry range overflows.
 */
static inline uint64_t calculate_elf_size_64(Section_Header_Entry_64 **arr,
                               Elf_Header_64            *elf_header,
                               int                       numEntries)
{
    uint64_t max_end = elf_header->elf_header_size;

    if (numEntries <= 0 || arr == NULL) {
        return max_end;
    }

    for (int i = 0; i < numEntries; i++) {
        if (arr[i]->section_type == SECTION_TYPE_NOBITS ||
            arr[i]->section_type == SECTION_TYPE_NULL) continue;

        uint64_t end;
        if (__builtin_add_overflow(arr[i]->sect_file_off,
                                   arr[i]->sect_size, &end)) {
            return UINT64_MAX;
        }
        if (end > max_end) max_end = end;
    }

    return max_end;
}


/**
 * @description         Sorts an array of 32-bit section header entries according to offset
 *                      so that they appear in the array in the order they appear in
 *                      the file. Insertion sort chosen over quicksort because the array
 *                      being sorted is very small. Insertion sort is known to be faster than
 *                      quicksort for smaller arrays. 
 *
 * @param arr           The array of 32-bit section header entry pointers
 * @param size          The size of arr
 *
 */
static inline void insertionSort_32(Section_Header_Entry_32** arr, int size){
    int i, j;
    Section_Header_Entry_32* key;
    for (i = 1; i < size; i++) {
        key = arr[i];
        j = i - 1;
        while (j >= 0 && arr[j]->sect_file_off > key->sect_file_off) {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
}



/**
 * @description         Sorts an array of 64-bit section header entries according to offset
 *                      so that they appear in the array in the order they appear in
 *                      the file. Insertion sort chosen over quicksort because the array being
 *                      sorted is very small.Insertion sort is known to be faster than
 *                      quicksort for smaller arrays. 
 *
 * @param arr           The array of 64-bit section header entries
 * @param size          The size of arr
 *
 */
static inline void insertionSort_64(Section_Header_Entry_64** arr, int size){
    int i, j;
    Section_Header_Entry_64* key;
    for (i = 1; i < size; i++) {
        key = arr[i];
        j = i - 1;
        while (j >= 0 && arr[j]->sect_file_off > key->sect_file_off) {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
}



/**
 * @brief Validate the Program Header Table of a 32-bit ELF candidate.
 *
 * Confirms that the PHT described by the ELF header is internally consistent
 * and that all entries fit within the supplied data buffer. This function is
 * intentionally more permissive than the PHT block detector: by the time
 * validation runs, the PHT location and entry count come directly from the
 * ELF header, providing strong prior evidence that a real PHT is present.
 * Applying detector-level strictness here (flag checks, quality gates,
 * tight alignment caps) would cause false negatives on legitimate ELFs
 * produced by non-standard toolchains.
 *
 * A missing PHT (offset == 0 or numEntries == 0) is treated as trivially
 * valid, since many ELF files (e.g. relocatable objects) have no PHT.
 *
 * Per-entry checks applied to every entry:
 *   - seg_type must fall within a recognised PT_* range (standard, OS-specific,
 *     or processor-specific).
 *   - alignment must not exceed 1 GB (1u << 30), covering all current page
 *     sizes including 1 GB hugepages; 0 and 1 are accepted without restriction.
 *   - If seg_file_size is non-zero, the segment's file extent
 *     [seg_offset, seg_offset + seg_file_size) must lie within @p length.
 *   - For PT_LOAD segments: seg_mem_size must be >= seg_file_size.
 *
 * Flags are not validated: unusual flag combinations occur in real ELFs and
 * rejecting them here would produce false negatives without meaningful gain.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t to prevent
 * wraparound on large offset or size values.
 *
 * @param data               Pointer to the candidate file data buffer.
 * @param length             Size of @p data in bytes.
 * @param offset             File offset of the PHT, as read from the ELF header.
 * @param entrySize          Size of one PHT entry in bytes; must be at least
 *                           PHT_ENTRY_SIZE_32 (32) or the function returns 0.
 * @param numEntries         Number of PHT entries declared in the ELF header.
 * @param target_endianness  Endianness of the host system.
 * @param elf_endianness     Endianness of the ELF file (ELF_LITTLE_ENDIAN or
 *                           ELF_BIG_ENDIAN); used to byte-swap fields before
 *                           inspection when it differs from the host.
 *
 * @return  1 if the PHT is absent or all entries pass validation;
 *          0 if any entry fails a structural check or exceeds the buffer.
 */
static inline int PHT_validate_32(char* data,
                     uint64_t length,
                     uint64_t offset,
                     uint16_t entrySize,
                     uint16_t numEntries,
                     enum Endianness target_endianness,
                     char elf_endianness)
{
    /* If there is no PHT, or no entries, treat as trivially valid. */
    if (offset == 0 || numEntries == 0) {
        return 1;
    }

    /* Entry size: be lenient, but require non-zero and at least canonical. */
    if (entrySize == 0 || entrySize < PHT_ENTRY_SIZE_32) {
        return 0;
    }

    /* Bulk bounds: offset + entrySize * numEntries must fit in the buffer. */
    {
        __uint128_t end = (__uint128_t)offset +
                          (__uint128_t)entrySize * (__uint128_t)numEntries;
        if (end > length) {
            return 0;
        }
    }

    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    uint64_t cur = offset;
    for (uint16_t i = 0; i < numEntries; i++) {
        /* Per-entry bound */
        if ((__uint128_t)cur + (__uint128_t)entrySize > length) {
            return 0;
        }

        Program_Header_Entry_32 phe;  /* 32-byte ELF32 PHT entry */
        memcpy(&phe, &data[cur], sizeof(Program_Header_Entry_32));

        /* Endian fixup for ELF32 PHT fields (all 32-bit wide) */
        if (need_swap) {
            phe.seg_type      = __builtin_bswap32(phe.seg_type);
            phe.seg_offset    = __builtin_bswap32(phe.seg_offset);
            phe.seg_vaddr     = __builtin_bswap32(phe.seg_vaddr);
            phe.seg_physaddr  = __builtin_bswap32(phe.seg_physaddr);
            phe.seg_file_size = __builtin_bswap32(phe.seg_file_size);
            phe.seg_mem_size  = __builtin_bswap32(phe.seg_mem_size);
            phe.alignment     = __builtin_bswap32(phe.alignment);
        }

        /* ---- Structural / semantic checks (relaxed) ---- */

        /* Type in allowed ranges (keep strict: strong ELF signal). */
        if (!((phe.seg_type >= PT_NULL   && phe.seg_type <= PT_TLS) ||
              (phe.seg_type >= SEGMENT_TYPE_LOOS   && phe.seg_type <= SEGMENT_TYPE_HIOS) ||
              (phe.seg_type >= SEGMENT_TYPE_LOPROC && phe.seg_type <= SEGMENT_TYPE_HIPROC))) {
            return 0;
        }

        if (phe.alignment > (1u << 30)) { /* heuristic upper bound */
            return 0;
        }

        /* Content bounds: file slice must fit within the input buffer. */
        if (phe.seg_file_size) {
            __uint128_t file_end = (__uint128_t)phe.seg_offset +
                                   (__uint128_t)phe.seg_file_size;
            if (file_end > length) {
                return 0;
            }
        }

        /* PT_LOAD semantics: keep "mem >= file" sanity, drop vaddr%align rule. */
        if (phe.seg_type == PT_LOAD) {
            if (phe.seg_mem_size < phe.seg_file_size) {
                return 0;
            }
            /* Previously: required vaddr%align == offset%align when alignment>1.
               That's spec-level strictness; we've dropped it here. */
        }

        cur += entrySize;
    }

    return 1; /* all entries validated under relaxed rules */
}



/**
 * @brief Validate the Program Header Table of a 64-bit ELF candidate.
 *
 * Confirms that the PHT described by the ELF header is internally consistent
 * and that all entries fit within the supplied data buffer. This function is
 * intentionally more permissive than the PHT block detector: by the time
 * validation runs, the PHT location and entry count come directly from the
 * ELF header, providing strong prior evidence that a real PHT is present.
 * Applying detector-level strictness here (flag checks, quality gates,
 * tight alignment caps) would cause false negatives on legitimate ELFs
 * produced by non-standard toolchains.
 *
 * A missing PHT (offset == 0 or numEntries == 0) is treated as trivially
 * valid, since many ELF files (e.g. relocatable objects) have no PHT.
 *
 * Per-entry checks applied to every entry:
 *   - seg_type must fall within a recognised PT_* range (standard, OS-specific,
 *     or processor-specific).
 *   - alignment must not exceed 1 GB (1u << 30), covering all current page
 *     sizes including 1 GB hugepages; 0 and 1 are accepted without restriction.
 *   - If seg_file_size is non-zero, the segment's file extent
 *     [seg_offset, seg_offset + seg_file_size) must lie within @p length.
 *   - For PT_LOAD segments: seg_mem_size must be >= seg_file_size.
 *
 * Flags are not validated: unusual flag combinations occur in real ELFs and
 * rejecting them here would produce false negatives without meaningful gain.
 * Note that flags_64 in the ELF64 PHT entry is a 32-bit field stored in a
 * 64-bit slot; byte-swapping uses a 32-bit swap accordingly.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t to prevent
 * wraparound on large offset or size values.
 *
 * @param data               Pointer to the candidate file data buffer.
 * @param length             Size of @p data in bytes.
 * @param offset             File offset of the PHT, as read from the ELF header.
 * @param entrySize          Size of one PHT entry in bytes; must be at least
 *                           PHT_ENTRY_SIZE_64 (56) or the function returns 0.
 *                           Entries larger than the canonical size are accepted
 *                           (e.g. Go-generated ELFs); only the first 56 bytes
 *                           of each entry are inspected.
 * @param numEntries         Number of PHT entries declared in the ELF header.
 * @param target_endianness  Endianness of the host system.
 * @param elf_endianness     Endianness of the ELF file (ELF_LITTLE_ENDIAN or
 *                           ELF_BIG_ENDIAN); used to byte-swap fields before
 *                           inspection when it differs from the host.
 *
 * @return  1 if the PHT is absent or all entries pass validation;
 *          0 if any entry fails a structural check or exceeds the buffer.
 */
static inline int PHT_validate_64(char* data,
                    uint64_t length,
                    uint64_t offset,
                    uint16_t entrySize,
                    uint16_t numEntries,
                    enum Endianness target_endianness,
                    char elf_endianness)
{
    /* If there is no PHT, treat as trivially valid. */
    if (offset == 0 || numEntries == 0) {
        return 1;
    }

    /* Entry size: be lenient, but require non-zero and at least canonical
       when entries exist. This allows Go / non-standard larger headers. */
    if (entrySize == 0 || entrySize < PHT_ENTRY_SIZE_64) {
        return 0;
    }

    /* Bulk bounds: offset + entrySize * numEntries must fit in the buffer. */
    {
        __uint128_t end = (__uint128_t)offset +
                          (__uint128_t)entrySize * (__uint128_t)numEntries;
        if (end > length) {
            return 0;
        }
    }

    /* Endianness flag */
    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    uint64_t cur = offset;
    for (uint16_t i = 0; i < numEntries; i++) {
        /* Per-entry bound */
        if ((__uint128_t)cur + (__uint128_t)entrySize > length) {
            return 0;
        }

        Program_Header_Entry_64 phe;
        /* We assume Program_Header_Entry_64 is the canonical 56 bytes.
           If entrySize > sizeof(struct), we only parse the first 56 bytes. */
        memcpy(&phe, &data[cur], sizeof(Program_Header_Entry_64));

        if (need_swap) {
            phe.seg_type     = __builtin_bswap32(phe.seg_type);
            phe.seg_offset   = __builtin_bswap64(phe.seg_offset);
            phe.seg_vaddr    = __builtin_bswap64(phe.seg_vaddr);
            phe.seg_physaddr = __builtin_bswap64(phe.seg_physaddr);
            phe.seg_file_size= __builtin_bswap64(phe.seg_file_size);
            phe.seg_mem_size = __builtin_bswap64(phe.seg_mem_size);
            phe.alignment    = __builtin_bswap64(phe.alignment);
        }

        /* ---- Structural / semantic checks (relaxed) ---- */

        /* Type in allowed ranges (keep this: very strong “this is real ELF” signal). */
        if (!((phe.seg_type >= PT_NULL   && phe.seg_type <= PT_TLS)   ||
              (phe.seg_type >= SEGMENT_TYPE_LOOS   && phe.seg_type <= SEGMENT_TYPE_HIOS)  ||
              (phe.seg_type >= SEGMENT_TYPE_LOPROC && phe.seg_type <= SEGMENT_TYPE_HIPROC))) {
            return 0;
        }

        if (phe.alignment > (1u << 30)) {
            /* absurdly large alignment is suspicious */
            return 0;
        }

        /* Content bounds: file slice must fit in buffer when present. */
        if (phe.seg_file_size) {
            __uint128_t file_end = (__uint128_t)phe.seg_offset +
                                   (__uint128_t)phe.seg_file_size;
            if (file_end > length) {
                return 0;
            }
        }

        /* PT_LOAD semantics: keep the obvious “mem >= file” sanity. */
        if (phe.seg_type == PT_LOAD) {
            if (phe.seg_mem_size < phe.seg_file_size) {
                return 0;
            }
            /* Previously we also required: vaddr%align == offset%align.
               That’s spec-level and stricter than what we want now, so dropped. */
        }

        cur += entrySize;
    }

    return 1;
}



/**
 * @brief Validate and parse the Section Header Table of a 32-bit ELF candidate,
 *        returning a heap-allocated array of section entry pointers augmented with
 *        two synthetic entries for size estimation.
 *
 * Iterates over every SHT entry in the candidate buffer, validates it structurally,
 * byte-swaps its fields when necessary, and stores a heap-allocated copy in the
 * output array. Two additional synthetic entries are appended:
 *
 *   - A synthetic SHT entry at index [adjusted_numEntries - 1], representing the
 *     Section Header Table itself (sect_file_off = sht_off, sect_size = sht_entry_size
 *     * num_sht_entries). Present only if elf_header->sht_off != 0.
 *   - A synthetic PHT entry at index [adjusted_numEntries - 2], representing the
 *     Program Header Table (sect_file_off = pht_off, sect_size = pht_entry_size
 *     * num_pht_entries). Present only if elf_header->pht_off != 0.
 *
 * The SHT and PHT can appear at any offset within the file, including before or
 * after the section data. By encoding them as fake SHT entries they can be sorted
 * alongside real sections by insertionSort_32 and passed to calculate_elf_size_32,
 * which correctly accounts for gaps between all file regions. Synthetic entries
 * use section_type = SECTION_TYPE_PROGBITS (1) as a sentinel; they are otherwise
 * fully zeroed except for sect_file_off, sect_size, and sect_align = 1.
 *
 * After validation the array (including any populated synthetic slots) is passed
 * through filter_null_32, which removes NULL slots (i.e. absent PHT or SHT) and
 * returns a compact, caller-owned array. The intermediate container is freed
 * internally; only the filtered array and its individual entries are returned to
 * the caller, who must free them via free_sht_entries_32.
 *
 * Per-entry validation checks:
 *   - section_type must fall within a recognised range (standard, INIT_ARRAY–NUM,
 *     OS-specific, or processor-specific).
 *   - sect_align must be 0 (treated as 1) or a non-zero power of two.
 *   - For non-NOBITS sections with non-zero sect_size: [sect_file_off, sect_file_off
 *     + sect_size) must lie within @p length.
 *   - For NOBITS or zero-size sections: sect_file_off alone must not exceed @p length.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t.
 *
 * @param data                Pointer to the candidate file data buffer.
 * @param length              Size of @p data in bytes.
 * @param offset              File offset of the SHT, as read from the ELF header.
 * @param entrySize           Size of one SHT entry in bytes; must be at least
 *                            SHT_ENTRY_SIZE_32 (40) or the function returns NULL.
 * @param numEntries          Number of SHT entries; must be non-zero and fit
 *                            in the supplied candidate buffer.
 * @param target_endianness   Endianness of the host system.
 * @param elf_endianness      Endianness of the ELF file; used to byte-swap fields
 *                            when it differs from the host.
 * @param elf_header          Parsed 32-bit ELF header; provides sht_off, pht_off,
 *                            and their respective entry sizes and counts for the
 *                            synthetic entries. Must not be NULL.
 * @param filtered_numEntries Output parameter; receives the count of valid entries
 *                            in the returned array (real + synthetic). Set to 0 on
 *                            failure. Must not be NULL.
 *
 * @return  On success: a newly allocated array of Section_Header_Entry_32* pointers,
 *          caller-owned and to be freed with free_sht_entries_32.
 *          On failure: NULL, with *filtered_numEntries set to 0.
 */
static inline Section_Header_Entry_32** SHT_validate_32(char* data,
                                          uint64_t length,
                                          uint64_t offset,
                                          uint16_t entrySize,
                                          uint16_t numEntries,
                                          enum Endianness target_endianness,
                                          char elf_endianness,
                                          Elf_Header_32* elf_header,
                                          int* filtered_numEntries)
{
    if (!filtered_numEntries || !data || !elf_header) {
        return NULL;
    }
    *filtered_numEntries = 0;

    if (offset == 0 || numEntries == 0) {
        return NULL;
    }

    /* Entry size: be lenient, but require non-zero and at least canonical
       when entries exist. This mirrors the relaxed header logic. */
    if (entrySize == 0 || entrySize < SHT_ENTRY_SIZE_32) {
        return NULL;
    }

    /* Bulk bounds: offset + entrySize * numEntries must fit */
    {
        __uint128_t end = (__uint128_t)offset +
                          (__uint128_t)entrySize * (__uint128_t)numEntries;
        if (end > length) {
            return NULL;
        }
    }

    /* Also sanity-check the synthetic SHT/PHT “entries” we’ll append */
    if (elf_header->sht_off && elf_header->num_sht_entries) {
        __uint128_t end_sh = (__uint128_t)elf_header->sht_off +
                             (__uint128_t)elf_header->sht_entry_size *
                             (__uint128_t)elf_header->num_sht_entries;
        if (end_sh > length) {
            return NULL;
        }
    }
    if (elf_header->pht_off && elf_header->num_pht_entries) {
        __uint128_t end_ph = (__uint128_t)elf_header->pht_off +
                             (__uint128_t)elf_header->pht_entry_size *
                             (__uint128_t)elf_header->num_pht_entries;
        if (end_ph > length) {
            return NULL;
        }
    }

    size_t adjusted_numEntries = (size_t)numEntries + 2u;
    Section_Header_Entry_32** sect_header_entries =
        (Section_Header_Entry_32**)calloc(adjusted_numEntries, sizeof(*sect_header_entries));
    check_memory_allocation(sect_header_entries, __LINE__, __FILE__, "SHT_validate_32 sect_header_entries");
    if (!sect_header_entries) {
        return NULL;
    }

#define FREE_ENTRIES_AND_CONTAINER_32()                                   \
    do {                                                                  \
        for (size_t _j = 0; _j < adjusted_numEntries; ++_j) {             \
            free(sect_header_entries[_j]);                                \
        }                                                                 \
        free(sect_header_entries);                                        \
    } while (0)

#define CLEANUP_FAIL_LOCAL_32()                                           \
    do {                                                                  \
        FREE_ENTRIES_AND_CONTAINER_32();                                  \
        *filtered_numEntries = 0;                                         \
        return NULL;                                                      \
    } while (0)

    /* Synthetic SHT entry */
    if (elf_header->sht_off != 0) {
        sect_header_entries[adjusted_numEntries - 1] =
            (Section_Header_Entry_32*)malloc(sizeof(Section_Header_Entry_32));
        check_memory_allocation(sect_header_entries[adjusted_numEntries - 1], __LINE__, __FILE__, "SHT_validate_32 synth SHT");
        if (!sect_header_entries[adjusted_numEntries - 1]) {
            CLEANUP_FAIL_LOCAL_32();
        }
        sect_header_entries[adjusted_numEntries - 1]->sect_size =
            (uint32_t)elf_header->sht_entry_size * (uint32_t)elf_header->num_sht_entries;
        sect_header_entries[adjusted_numEntries - 1]->sect_file_off = elf_header->sht_off;
        sect_header_entries[adjusted_numEntries - 1]->section_type  = 1; /* synthetic sentinel */
        sect_header_entries[adjusted_numEntries - 1]->sect_name_off = 0;
        sect_header_entries[adjusted_numEntries - 1]->flags         = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_mem_addr = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_idx      = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_info     = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_align    = 1;
        sect_header_entries[adjusted_numEntries - 1]->entry_size    = 0;
    }

    /* Synthetic PHT entry */
    if (elf_header->pht_off != 0) {
        sect_header_entries[adjusted_numEntries - 2] =
            (Section_Header_Entry_32*)malloc(sizeof(Section_Header_Entry_32));
        check_memory_allocation(sect_header_entries[adjusted_numEntries - 2], __LINE__, __FILE__, "SHT_validate_32 synth PHT");
        if (!sect_header_entries[adjusted_numEntries - 2]) {
            CLEANUP_FAIL_LOCAL_32();
        }
        sect_header_entries[adjusted_numEntries - 2]->sect_size =
            (uint32_t)elf_header->pht_entry_size * (uint32_t)elf_header->num_pht_entries;
        sect_header_entries[adjusted_numEntries - 2]->sect_file_off = elf_header->pht_off;
        sect_header_entries[adjusted_numEntries - 2]->section_type  = 1;
        sect_header_entries[adjusted_numEntries - 2]->sect_name_off = 0;
        sect_header_entries[adjusted_numEntries - 2]->flags         = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_mem_addr = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_idx      = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_info     = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_align    = 1;
        sect_header_entries[adjusted_numEntries - 2]->entry_size    = 0;
    }

    uint64_t cur = offset;
    for (uint16_t i = 0; i < numEntries; i++) {
        if ((__uint128_t)cur + (__uint128_t)entrySize > length) {
            CLEANUP_FAIL_LOCAL_32();
        }

        Section_Header_Entry_32* e =
            (Section_Header_Entry_32*)malloc(sizeof(Section_Header_Entry_32));
        check_memory_allocation(e, __LINE__, __FILE__, "SHT_validate_32 e");
        if (!e) {
            CLEANUP_FAIL_LOCAL_32();
        }

        memcpy(e, &data[cur], sizeof(Section_Header_Entry_32));

        if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
            (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
            e->sect_name_off = __builtin_bswap32(e->sect_name_off);
            e->section_type  = __builtin_bswap32(e->section_type);
            e->flags         = __builtin_bswap32(e->flags);
            e->sect_mem_addr = __builtin_bswap32(e->sect_mem_addr);
            e->sect_file_off = __builtin_bswap32(e->sect_file_off);
            e->sect_size     = __builtin_bswap32(e->sect_size);
            e->sect_idx      = __builtin_bswap32(e->sect_idx);
            e->sect_info     = __builtin_bswap32(e->sect_info);
            e->sect_align    = __builtin_bswap32(e->sect_align);
            e->entry_size    = __builtin_bswap32(e->entry_size);
        }

        /* Section type ranges: keep this strict, it’s a good discriminator. */
        if (!((e->section_type >= SECTION_TYPE_NULL       && e->section_type <= SECTION_TYPE_DYNSYM) ||
              (e->section_type >= SECTION_TYPE_INIT_ARRAY && e->section_type <= SECTION_TYPE_NUM) ||
              (e->section_type >= SECTION_TYPE_LOOS       && e->section_type <= SECTION_TYPE_HIOS) ||
              (e->section_type >= SECTION_TYPE_LOPROC     && e->section_type <= SECTION_TYPE_HIPROC))) {
            free(e);
            CLEANUP_FAIL_LOCAL_32();
        }

        /* Alignment: treat 0 as 1; otherwise require power-of-two. */
        {
            uint32_t al = e->sect_align;
            if (al == 0) al = 1;
            if ((al & (al - 1)) != 0) {
                free(e);
                CLEANUP_FAIL_LOCAL_32();
            }
        }

        /* Section contents must fit in buffer when present.
           DOES NOT APPLY TO NOBITS. */
        if (e->sect_size && e->section_type != SECTION_TYPE_NOBITS) {
            __uint128_t sec_end = (__uint128_t)e->sect_file_off + (__uint128_t)e->sect_size;
            if (sec_end > length) {
                free(e);
                CLEANUP_FAIL_LOCAL_32();
            }
        } else {
            /* Still require that the offset itself isn't nonsense. */
            if ((uint64_t)e->sect_file_off > length) {
                free(e);
                CLEANUP_FAIL_LOCAL_32();
            }
        }

        sect_header_entries[i] = e;
        cur += entrySize;
    }

    int filtered_size = 0;
    Section_Header_Entry_32** filtered =
        filter_null_32(sect_header_entries, (int)adjusted_numEntries, &filtered_size);

    if (!filtered || filtered_size <= 0) {
        FREE_ENTRIES_AND_CONTAINER_32();
        *filtered_numEntries = 0;
        return NULL;
    }

    free(sect_header_entries);

    *filtered_numEntries = filtered_size;
    return filtered;

#undef CLEANUP_FAIL_LOCAL_32
#undef FREE_ENTRIES_AND_CONTAINER_32
}



/**
 * @brief Validate and parse the Section Header Table of a 64-bit ELF candidate,
 *        returning a heap-allocated array of section entry pointers augmented with
 *        two synthetic entries for size estimation.
 *
 * Iterates over every SHT entry in the candidate buffer, validates it structurally,
 * byte-swaps its fields when necessary, and stores a heap-allocated copy in the
 * output array. Two additional synthetic entries are appended:
 *
 *   - A synthetic SHT entry at index [adjusted_numEntries - 1], representing the
 *     Section Header Table itself (sect_file_off = sht_off, sect_size = sht_entry_size
 *     * num_sht_entries). Present only if elf_header->sht_off != 0.
 *   - A synthetic PHT entry at index [adjusted_numEntries - 2], representing the
 *     Program Header Table (sect_file_off = pht_off, sect_size = pht_entry_size
 *     * num_pht_entries). Present only if elf_header->pht_off != 0.
 *
 * The SHT and PHT can appear at any offset within the file, including before or
 * after the section data. By encoding them as fake SHT entries they can be sorted
 * alongside real sections by insertionSort_64 and passed to calculate_elf_size_64,
 * which correctly accounts for gaps between all file regions. Synthetic entries
 * use section_type = SECTION_TYPE_PROGBITS (1) as a sentinel; they are otherwise
 * fully zeroed except for sect_file_off, sect_size, and sect_align = 1.
 *
 * After validation the array (including any populated synthetic slots) is passed
 * through filter_null_64, which removes NULL slots (i.e. absent PHT or SHT) and
 * returns a compact, caller-owned array. The intermediate container is freed
 * internally; only the filtered array and its individual entries are returned to
 * the caller, who must free them via free_sht_entries_64.
 *
 * Per-entry validation checks:
 *   - section_type must fall within a recognised range (standard, INIT_ARRAY–NUM,
 *     OS-specific, or processor-specific).
 *   - sect_align must be 0 (treated as 1) or a non-zero power of two.
 *   - For non-NOBITS sections with non-zero sect_size: [sect_file_off, sect_file_off
 *     + sect_size) must lie within @p length.
 *   - For NOBITS or zero-size sections: sect_file_off alone must not exceed @p length.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t.
 *
 * @param data                Pointer to the candidate file data buffer.
 * @param length              Size of @p data in bytes.
 * @param offset              File offset of the SHT, as read from the ELF header.
 * @param entrySize           Size of one SHT entry in bytes; must be at least
 *                            SHT_ENTRY_SIZE_64 (64) or the function returns NULL.
 * @param numEntries          Number of SHT entries; must be non-zero and fit
 *                            in the supplied candidate buffer.
 * @param target_endianness   Endianness of the host system.
 * @param elf_endianness      Endianness of the ELF file; used to byte-swap fields
 *                            when it differs from the host.
 * @param elf_header          Parsed 64-bit ELF header; provides sht_off, pht_off,
 *                            and their respective entry sizes and counts for the
 *                            synthetic entries. Must not be NULL.
 * @param filtered_numEntries Output parameter; receives the count of valid entries
 *                            in the returned array (real + synthetic). Set to 0 on
 *                            failure. Must not be NULL.
 *
 * @return  On success: a newly allocated array of Section_Header_Entry_64* pointers,
 *          caller-owned and to be freed with free_sht_entries_64.
 *          On failure: NULL, with *filtered_numEntries set to 0.
 */
static inline Section_Header_Entry_64** SHT_validate_64(char* data,
                                          uint64_t length,
                                          uint64_t offset,
                                          uint16_t entrySize,
                                          uint16_t numEntries,
                                          enum Endianness target_endianness,
                                          char elf_endianness,
                                          Elf_Header_64* elf_header,
                                          int* filtered_numEntries)
{
    if (!filtered_numEntries || !data || !elf_header) {
        return NULL;
    }   
    *filtered_numEntries = 0;

    if (offset == 0 || numEntries == 0) {
        return NULL;
    }

    /* Entry size: be lenient, but require non-zero and at least canonical
       when entries exist. This mirrors the relaxed header logic. */
    if (entrySize == 0 || entrySize < SHT_ENTRY_SIZE_64) {
        return NULL;
    }

    /* Bulk bounds: offset + entrySize * numEntries must fit */
    {
        __uint128_t end = (__uint128_t)offset +
                          (__uint128_t)entrySize * (__uint128_t)numEntries;
        if (end > length) {
            return NULL;
        }
    }

    /* Also sanity-check the synthetic SHT/PHT “entries” we’ll append */
    if (elf_header->sht_off && elf_header->num_sht_entries) {
        __uint128_t end_sh = (__uint128_t)elf_header->sht_off +
                             (__uint128_t)elf_header->sht_entry_size *
                             (__uint128_t)elf_header->num_sht_entries;
        if (end_sh > length) {
            return NULL;
        }
    }
    if (elf_header->pht_off && elf_header->num_pht_entries) {
        __uint128_t end_ph = (__uint128_t)elf_header->pht_off +
                             (__uint128_t)elf_header->pht_entry_size *
                             (__uint128_t)elf_header->num_pht_entries;
        if (end_ph > length) {
            return NULL;
        }
    }

    size_t adjusted_numEntries = (size_t)numEntries + 2u;
    Section_Header_Entry_64** sect_header_entries =
        (Section_Header_Entry_64**)calloc(adjusted_numEntries, sizeof(*sect_header_entries));
    check_memory_allocation(sect_header_entries, __LINE__, __FILE__, "SHT_validate_64 sect_header_entries");
    if (!sect_header_entries) {
        return NULL;
    }

#define FREE_ENTRIES_AND_CONTAINER()                                       \
    do {                                                                   \
        for (size_t _j = 0; _j < adjusted_numEntries; ++_j) {             \
            free(sect_header_entries[_j]);                                 \
        }                                                                  \
        free(sect_header_entries);                                         \
    } while (0)

#define CLEANUP_FAIL_LOCAL()                                               \
    do {                                                                   \
        FREE_ENTRIES_AND_CONTAINER();                                      \
        *filtered_numEntries = 0;                                          \
        return NULL;                                                       \
    } while (0)

    /* Synthetic SHT entry */
    if (elf_header->sht_off != 0) {
        sect_header_entries[adjusted_numEntries - 1] =
            (Section_Header_Entry_64*)malloc(sizeof(Section_Header_Entry_64));
        check_memory_allocation(sect_header_entries[adjusted_numEntries - 1], __LINE__, __FILE__, "SHT_validate_64 synth SHT");
        if (!sect_header_entries[adjusted_numEntries - 1]) {
            CLEANUP_FAIL_LOCAL();
        }
        sect_header_entries[adjusted_numEntries - 1]->sect_size =
            (uint64_t)elf_header->sht_entry_size * (uint64_t)elf_header->num_sht_entries;
        sect_header_entries[adjusted_numEntries - 1]->sect_file_off = elf_header->sht_off;
        sect_header_entries[adjusted_numEntries - 1]->section_type  = 1; /* synthetic sentinel */
        sect_header_entries[adjusted_numEntries - 1]->sect_name_off  = 0;
        sect_header_entries[adjusted_numEntries - 1]->flags          = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_mem_addr  = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_idx       = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_info      = 0;
        sect_header_entries[adjusted_numEntries - 1]->sect_align     = 1;
        sect_header_entries[adjusted_numEntries - 1]->entry_size     = 0;
    }

    /* Synthetic PHT entry */
    if (elf_header->pht_off != 0) {
        sect_header_entries[adjusted_numEntries - 2] =
            (Section_Header_Entry_64*)malloc(sizeof(Section_Header_Entry_64));
        check_memory_allocation(sect_header_entries[adjusted_numEntries - 2], __LINE__, __FILE__, "SHT_validate_64 synth PHT");
        if (!sect_header_entries[adjusted_numEntries - 2]) {
            CLEANUP_FAIL_LOCAL();
        }
        sect_header_entries[adjusted_numEntries - 2]->sect_size =
            (uint64_t)elf_header->pht_entry_size * (uint64_t)elf_header->num_pht_entries;
        sect_header_entries[adjusted_numEntries - 2]->sect_file_off = elf_header->pht_off;
        sect_header_entries[adjusted_numEntries - 2]->section_type  = 1;
        sect_header_entries[adjusted_numEntries - 2]->sect_name_off  = 0;
        sect_header_entries[adjusted_numEntries - 2]->flags          = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_mem_addr  = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_idx       = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_info      = 0;
        sect_header_entries[adjusted_numEntries - 2]->sect_align     = 1;
        sect_header_entries[adjusted_numEntries - 2]->entry_size     = 0;
    }

    uint64_t cur = offset;
    for (uint16_t i = 0; i < numEntries; i++) {
        if ((__uint128_t)cur + (__uint128_t)entrySize > length) {
            CLEANUP_FAIL_LOCAL();
        }

        Section_Header_Entry_64* e =
            (Section_Header_Entry_64*)malloc(sizeof(Section_Header_Entry_64));
        check_memory_allocation(e, __LINE__, __FILE__, "SHT_validate_64 e");
        if (!e) {
            CLEANUP_FAIL_LOCAL();
        }

        memcpy(e, &data[cur], sizeof(Section_Header_Entry_64));

        if ((target_endianness == LITTLE && elf_endianness == ELF_BIG_ENDIAN) ||
            (target_endianness == BIG    && elf_endianness == ELF_LITTLE_ENDIAN)) {
            e->sect_name_off  = __builtin_bswap32(e->sect_name_off);
            e->section_type   = __builtin_bswap32(e->section_type);
            e->flags          = __builtin_bswap64(e->flags);
            e->sect_mem_addr  = __builtin_bswap64(e->sect_mem_addr);
            e->sect_file_off  = __builtin_bswap64(e->sect_file_off);
            e->sect_size      = __builtin_bswap64(e->sect_size);
            e->sect_idx       = __builtin_bswap32(e->sect_idx);
            e->sect_info      = __builtin_bswap32(e->sect_info);
            e->sect_align     = __builtin_bswap64(e->sect_align);
            e->entry_size     = __builtin_bswap64(e->entry_size);
        }

        /* Section type ranges: keep this strict, it’s a good discriminator. */
        if (!((e->section_type >= SECTION_TYPE_NULL   && e->section_type <= SECTION_TYPE_DYNSYM) ||
              (e->section_type >= SECTION_TYPE_INIT_ARRAY && e->section_type <= SECTION_TYPE_NUM) ||
              (e->section_type >= SECTION_TYPE_LOOS   && e->section_type <= SECTION_TYPE_HIOS) ||
              (e->section_type >= SECTION_TYPE_LOPROC && e->section_type <= SECTION_TYPE_HIPROC))) {
            free(e);
            CLEANUP_FAIL_LOCAL();
        }

        /* Alignment: RELAXED.
           Previously: required power-of-two. Now:
           - treat 0 as 1 (no constraint)
           - only reject absurdly large values that are clearly garbage. */
        {
            uint64_t al = e->sect_align;
            if (al == 0) al = 1;
            if ((al & (al - 1)) != 0) {
                free(e);
                CLEANUP_FAIL_LOCAL();
            }
        }

        /* Section contents must fit in buffer when present. */
        /* DOES NOT APPLY TO NOBITS */
        if (e->sect_size && e->section_type != SECTION_TYPE_NOBITS) {
            __uint128_t sec_end = (__uint128_t)e->sect_file_off + (__uint128_t)e->sect_size;
            if (sec_end > length) {
                free(e);
                CLEANUP_FAIL_LOCAL();
            }
        } else {
            /* Still require that the offset itself isn't nonsense. */
            if (e->sect_file_off > length) {
                free(e);
                CLEANUP_FAIL_LOCAL();
            }
        }

        sect_header_entries[i] = e;
        cur += entrySize;
    }

    int filtered_size = 0;
    Section_Header_Entry_64** filtered =
        filter_null_64(sect_header_entries, (int)adjusted_numEntries, &filtered_size);

    if (!filtered || filtered_size <= 0) {
        FREE_ENTRIES_AND_CONTAINER();
        *filtered_numEntries = 0;
        return NULL;
    }
    free(sect_header_entries);

    *filtered_numEntries = filtered_size;
    return filtered;

#undef CLEANUP_FAIL_LOCAL
#undef FREE_ENTRIES_AND_CONTAINER
}


/**
 * @brief Parse and validate the header of a 32-bit ELF candidate, returning
 *        a heap-allocated, endian-corrected Elf_Header_32 on success.
 *
 * Performs a two-phase check. First, the e_ident bytes are inspected directly
 * from @p data before any allocation:
 *   - Bytes 0–3 must be the ELF magic (0x7f 'E' 'L' 'F').
 *   - EI_CLASS (byte 4) must be ELF_32_BIT.
 *   - EI_DATA  (byte 5) must be ELF_LITTLE_ENDIAN or ELF_BIG_ENDIAN.
 *   - EI_VERSION (byte 6) must be 1 (EV_CURRENT).
 *
 * If these pass, the header body (starting at ELF_BYTES_START = 0x10, i.e.
 * immediately after the 16-byte e_ident) is copied into a freshly allocated
 * Elf_Header_32 and byte-swapped when the file and host endianness differ.
 * The following structural checks are then applied to the swapped fields:
 *
 *   - elf_ver must be 1.
 *   - exec_type must fall within ET_NONE–ET_CORE (0–4), an OS-specific range
 *     (0xFE00–0xFEFF), or a processor-specific range (0xFF00–0xFFFF). Note:
 *     ET_NONE (0) is technically accepted here; in practice it is rejected
 *     upstream by elf_header_discovery before any candidate reaches this
 *     function.
 *   - isa must be non-zero.
 *   - elf_header_size must be >= 52 (the canonical ELF32 header size).
 *   - If num_pht_entries > 0: pht_entry_size must be >= PHT_ENTRY_SIZE_32 (32).
 *   - If num_sht_entries > 0: sht_entry_size must be >= SHT_ENTRY_SIZE_32 (40).
 *   - pht_off must be non-zero when num_pht_entries > 0.
 *   - sht_off must be non-zero when num_sht_entries > 0.
 *   - idx_section_names must be < num_sht_entries when the SHT is present,
 *     unless it equals the extended-index sentinel 0xFFFF.
 *
 * Offset bounds (pht_off, sht_off vs @p length) are not checked here; that
 * is the responsibility of PHT_validate_32 and SHT_validate_32, which run
 * immediately after this function in the validation pipeline.
 *
 * @param data               Pointer to the candidate file data buffer. Must
 *                           contain at least 52 bytes or the function returns
 *                           NULL immediately.
 * @param length             Size of @p data in bytes.
 * @param target_endianness  Endianness of the host system; used to determine
 *                           whether byte-swapping is needed.
 * @param elf_endianness     Endianness of the ELF file as read from EI_DATA
 *                           (ELF_LITTLE_ENDIAN or ELF_BIG_ENDIAN).
 *
 * @return  On success: a newly allocated, endian-corrected Elf_Header_32;
 *          caller is responsible for freeing it.
 *          On failure: NULL.
 */
static inline Elf_Header_32* ELF_header_validate_32(char* data,
                                      uint64_t length,
                                      enum Endianness target_endianness,
                                      char elf_endianness)
{
    /* e_ident + 52-byte ELF32 header must be present */
    if (length < 52) return NULL;

    const unsigned char *ei = (const unsigned char*)data;

    /* Cheap front-door checks  */
    if (!(ei[0] == 0x7f && ei[1] == 'E' && ei[2] == 'L' && ei[3] == 'F')) return NULL;
    if (ei[4] != ELF_32_BIT) return NULL;  /* EI_CLASS */
    if (!(ei[5] == ELF_LITTLE_ENDIAN || ei[5] == ELF_BIG_ENDIAN)) return NULL; /* EI_DATA */
    if (ei[6] != 1) return NULL;           /* EI_VERSION (EV_CURRENT) */

    /* Ensure the full header body fits */
    if (ELF_BYTES_START + sizeof(Elf_Header_32) > length) return NULL;

    /* Allocate the result struct (single allocation) */
    Elf_Header_32 *hdr = (Elf_Header_32*)malloc(sizeof(Elf_Header_32));
    check_memory_allocation(hdr, __LINE__, __FILE__, "Elf_Header_32");
    if (!hdr) return NULL;

    /* Copy raw bytes into struct */
    memcpy(hdr, &data[ELF_BYTES_START], sizeof(Elf_Header_32));

    /* Swap if host/file endianness differ (based on TARGET_ENDIANNESS vs file EI_DATA) */
    const int file_is_le = (ei[5] == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    if (file_is_le != host_is_le) {
        hdr->exec_type         = __builtin_bswap16(hdr->exec_type);
        hdr->isa               = __builtin_bswap16(hdr->isa);
        hdr->elf_ver           = __builtin_bswap32(hdr->elf_ver);
        hdr->entry_point       = __builtin_bswap32(hdr->entry_point);
        hdr->pht_off           = __builtin_bswap32(hdr->pht_off);
        hdr->sht_off           = __builtin_bswap32(hdr->sht_off);
        hdr->flags             = __builtin_bswap32(hdr->flags);
        hdr->elf_header_size   = __builtin_bswap16(hdr->elf_header_size);
        hdr->pht_entry_size    = __builtin_bswap16(hdr->pht_entry_size);
        hdr->num_pht_entries   = __builtin_bswap16(hdr->num_pht_entries);
        hdr->sht_entry_size    = __builtin_bswap16(hdr->sht_entry_size);
        hdr->num_sht_entries   = __builtin_bswap16(hdr->num_sht_entries);
        hdr->idx_section_names = __builtin_bswap16(hdr->idx_section_names);
    }

    /* ---- Sanity checks (cheap invariants + relaxed structural checks) ---- */

    /* Object file version must be 1 */
    if (hdr->elf_ver != 1) { free(hdr); return NULL; }

    /* e_type within standard or OS-/proc-specific ranges */
    if (!((hdr->exec_type >= EXEC_UNKNOWN && hdr->exec_type <= EXEC_CORE) ||
          (hdr->exec_type >= EXEC_LOOS    && hdr->exec_type <= EXEC_HIOS) ||
          (hdr->exec_type >= EXEC_LOPROC  && hdr->exec_type <= EXEC_HIPROC))) {
        free(hdr); return NULL;
    }

    /* ISA must be non-zero (loose default) */
    if (hdr->isa == 0) { free(hdr); return NULL; }

    /* Header size: require at least canonical ELF32 size (52 bytes). */
    if (hdr->elf_header_size < 52) { free(hdr); return NULL; }

    /* Program header entry size:
       If there ARE entries, size must be non-zero and at least canonical.
       If no entries, we don't care about pht_entry_size. */
    if (hdr->num_pht_entries > 0) {
        if (hdr->pht_entry_size == 0 ||
            hdr->pht_entry_size < PHT_ENTRY_SIZE_32) {
            free(hdr);
            return NULL;
        }
    }

    /* Section header entry size:
       Same idea: allow larger-than-canonical sizes when entries exist. */
    if (hdr->num_sht_entries > 0) {
        if (hdr->sht_entry_size == 0 ||
            hdr->sht_entry_size < SHT_ENTRY_SIZE_32) {
            free(hdr);
            return NULL;
        }
    }

    if (hdr->pht_off == 0 && hdr->num_pht_entries != 0) {
        free(hdr);
        return NULL;
    }
    if (hdr->sht_off == 0 && hdr->num_sht_entries != 0) {
        free(hdr);
        return NULL;
    }

    if (hdr->num_sht_entries != 0 &&
        hdr->idx_section_names >= hdr->num_sht_entries &&
        hdr->idx_section_names != 0xFFFF) {
        free(hdr); return NULL;
    }

    return hdr;
}



/**
 * @brief Parse and validate the header of a 64-bit ELF candidate, returning
 *        a heap-allocated, endian-corrected Elf_Header_64 on success.
 *
 * Performs a two-phase check. First, the e_ident bytes are inspected directly
 * from @p data before any allocation:
 *   - Bytes 0–3 must be the ELF magic (0x7f 'E' 'L' 'F').
 *   - EI_CLASS (byte 4) must be ELF_64_BIT.
 *   - EI_DATA  (byte 5) must be ELF_LITTLE_ENDIAN or ELF_BIG_ENDIAN.
 *   - EI_VERSION (byte 6) must be 1 (EV_CURRENT).
 *
 * If these pass, the header body (starting at ELF_BYTES_START = 0x10, i.e.
 * immediately after the 16-byte e_ident) is copied into a freshly allocated
 * Elf_Header_64 and byte-swapped when the file and host endianness differ.
 * The following structural checks are then applied to the swapped fields:
 *
 *   - elf_ver must be 1.
 *   - exec_type must fall within ET_NONE–ET_CORE (0–4), an OS-specific range
 *     (0xFE00–0xFEFF), or a processor-specific range (0xFF00–0xFFFF). Note:
 *     ET_NONE (0) is technically accepted here; in practice it is rejected
 *     upstream by elf_header_discovery before any candidate reaches this
 *     function.
 *   - isa must be non-zero.
 *   - elf_header_size must be >= 64 (the canonical ELF64 header size).
 *   - If num_pht_entries > 0: pht_entry_size must be >= PHT_ENTRY_SIZE_64 (56).
 *   - If num_sht_entries > 0: sht_entry_size must be >= SHT_ENTRY_SIZE_64 (64).
 *   - pht_off must be non-zero when num_pht_entries > 0.
 *   - sht_off must be non-zero when num_sht_entries > 0.
 *   - idx_section_names must be < num_sht_entries when the SHT is present,
 *     unless it equals the extended-index sentinel 0xFFFF.
 *
 * Offset bounds (pht_off, sht_off vs @p length) are not checked here; that
 * is the responsibility of PHT_validate_64 and SHT_validate_64, which run
 * immediately after this function in the validation pipeline.
 *
 * @param data               Pointer to the candidate file data buffer. Must
 *                           contain at least 64 bytes or the function returns
 *                           NULL immediately.
 * @param length             Size of @p data in bytes.
 * @param target_endianness  Endianness of the host system; used to determine
 *                           whether byte-swapping is needed.
 * @param elf_endianness     Endianness of the ELF file as read from EI_DATA
 *                           (ELF_LITTLE_ENDIAN or ELF_BIG_ENDIAN).
 *
 * @return  On success: a newly allocated, endian-corrected Elf_Header_64;
 *          caller is responsible for freeing it.
 *          On failure: NULL.
 */
static inline Elf_Header_64* ELF_header_validate_64(char* data,
                                      uint64_t length,
                                      enum Endianness target_endianness,
                                      char elf_endianness){
    /* e_ident + 64-byte ELF64 header must be present */
    if (length < 64) return NULL;
    const unsigned char *ei = (const unsigned char*)data;

    /* Cheap checks  */
    if (!(ei[0] == 0x7f && ei[1] == 'E' && ei[2] == 'L' && ei[3] == 'F')) return NULL;
    if (ei[4] != ELF_64_BIT) return NULL; /* EI_CLASS */
    if (!(ei[5] == ELF_LITTLE_ENDIAN || ei[5] == ELF_BIG_ENDIAN)) return NULL; /* EI_DATA */
    if (ei[6] != 1) return NULL; /* EI_VERSION (EV_CURRENT) */

    /* Ensure the full header body fits */
    if (ELF_BYTES_START + sizeof(Elf_Header_64) > length) return NULL;

    /* Allocate the result struct (single allocation) */
    Elf_Header_64 *hdr = (Elf_Header_64*)malloc(sizeof(Elf_Header_64));
    check_memory_allocation(hdr, __LINE__, __FILE__, "Elf_Header_64");
    if (!hdr) return NULL; /* (check_memory_allocation may abort; this is just defensive) */

    /* Copy raw bytes into struct */
    memcpy(hdr, &data[ELF_BYTES_START], sizeof(Elf_Header_64));

    /* Swap if host/file endianness differ (based on TARGET_ENDIANNESS vs file EI_DATA) */
    const int file_is_le = (ei[5] == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    if (file_is_le != host_is_le) {
        hdr->exec_type         = __builtin_bswap16(hdr->exec_type);
        hdr->isa               = __builtin_bswap16(hdr->isa);
        hdr->elf_ver           = __builtin_bswap32(hdr->elf_ver);
        hdr->entry_point       = __builtin_bswap64(hdr->entry_point);
        hdr->pht_off           = __builtin_bswap64(hdr->pht_off);
        hdr->sht_off           = __builtin_bswap64(hdr->sht_off);
        hdr->flags             = __builtin_bswap32(hdr->flags);
        hdr->elf_header_size   = __builtin_bswap16(hdr->elf_header_size);
        hdr->pht_entry_size    = __builtin_bswap16(hdr->pht_entry_size);
        hdr->num_pht_entries   = __builtin_bswap16(hdr->num_pht_entries);
        hdr->sht_entry_size    = __builtin_bswap16(hdr->sht_entry_size);
        hdr->num_sht_entries   = __builtin_bswap16(hdr->num_sht_entries);
        hdr->idx_section_names = __builtin_bswap16(hdr->idx_section_names);
    }

    /* ---- Sanity checks (reduce false positives & bogus big allocations) ---- */

    /* Object file version must be 1 */
    if (hdr->elf_ver != 1) { free(hdr); return NULL; }

    /* e_type within standard or OS-/proc-specific ranges */
    if (!((hdr->exec_type >= EXEC_UNKNOWN && hdr->exec_type <= EXEC_CORE) ||
          (hdr->exec_type >= EXEC_LOOS    && hdr->exec_type <= EXEC_HIOS) ||
          (hdr->exec_type >= EXEC_LOPROC  && hdr->exec_type <= EXEC_HIPROC))) {
        free(hdr); return NULL;
    }

    /* ISA must be non-zero (keep loose by default) */
    if (hdr->isa == 0) { free(hdr); return NULL; }

    /* Exact header size for ELF64 */
    if (hdr->elf_header_size < 64) { free(hdr); return NULL; }

    /* Entry sizes: allow 0 iff corresponding count is 0 */
    if (hdr->num_pht_entries > 0) {
        if (hdr->pht_entry_size == 0 ||
            hdr->pht_entry_size < PHT_ENTRY_SIZE_64) {
            free(hdr);
            return NULL;
        }
    }
    if (hdr->num_sht_entries > 0) {
        if (hdr->sht_entry_size == 0 ||
            hdr->sht_entry_size < SHT_ENTRY_SIZE_64) {
            free(hdr);
            return NULL;
        }
    }

    if (hdr->pht_off == 0 && hdr->num_pht_entries != 0) {
        free(hdr);
        return NULL;
    }
    if (hdr->sht_off == 0 && hdr->num_sht_entries != 0) {
        free(hdr);
        return NULL;
    }

    /* e_shstrndx in range when SHT exists; allow 0xFFFF sentinel. */
    if (hdr->num_sht_entries != 0 &&
        hdr->idx_section_names >= hdr->num_sht_entries &&
        hdr->idx_section_names != 0xFFFF) {
        free(hdr);
        return NULL;
    }

    return hdr;
}


/**
 * @brief               Validates whether a given section type value is a standard,
 *                      commonly used ELF section type for 32-bit binaries.
 *
 * @description         This function checks whether the provided `sh_type` field value
 *                      from an ELF section header corresponds to one of the known and
 *                      commonly encountered section types in ELF files.
 *
 *
 * @param type          The section type value (`sh_type`) to validate.
 *
 * @return              true if the type is one of the recognized standard ELF section
 *                      types; false otherwise.
 */
bool is_valid_section_type(uint32_t type) {
    switch (type) {
        case SECTION_TYPE_NULL:
        case SECTION_TYPE_PROGBITS:
        case SECTION_TYPE_SYMTAB:
        case SECTION_TYPE_STRTAB:
        case SECTION_TYPE_RELA:
        case SECTION_TYPE_HASH:
        case SECTION_TYPE_DYNAMIC:
        case SECTION_TYPE_NOTE:
        case SECTION_TYPE_NOBITS:
        case SECTION_TYPE_REL:
        case SECTION_TYPE_SHLIB:
        case SECTION_TYPE_DYNSYM:
        case SECTION_TYPE_INIT_ARRAY:
        case SECTION_TYPE_FINI_ARRAY:
        case SECTION_TYPE_PREINIT_ARRAY:
        case SECTION_TYPE_GROUP:
        case SECTION_TYPE_SYMTAB_SHNDX:
            return true;
    }
    // Allow OS-specific types: 0x60000000 – 0x6FFFFFFF
    if (type >= 0x60000000 && type <= 0x6FFFFFFF) {
        return true;
    }

    // Allow processor-specific types: 0x70000000 – 0x7FFFFFFF
    if (type >= 0x70000000 && type <= 0x7FFFFFFF) {
        return true;
    }

    return false;
}



/**
 * @brief Estimate the total size of a 32-bit ELF file from its Program Header
 *        Table when no Section Header Table is available.
 *
 * This is the fallback size calculation used when SHT parsing fails or the SHT
 * is absent. It walks all PHT entries and returns the highest file-space byte
 * reached by any file-backed segment — i.e. max(seg_offset + seg_file_size)
 * across all non-PT_NULL entries with non-zero seg_file_size. The result is
 * initialised to the end of the ELF header and the PHT region itself, so it is
 * always at least as large as the headers even if all segments have zero filesz.
 *
 * The result is an estimation and is not rounded up to an alignment boundary.
 * The caller uses it directly for comparison against known region endpoints.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t. If any
 * segment's file extent exceeds @p length the function returns 0 immediately,
 * which the caller treats as a validation failure.
 *
 * For oversized PHT entries (pht_entry_size > PHT_ENTRY_SIZE_32), the struct
 * is zeroed before copying so that only the canonical 32 bytes are read and
 * extra bytes do not bleed into the parsed fields.
 *
 * @pre  The PHT has already been validated by PHT_validate_32 — bounds are
 *       assumed safe to read.
 *
 * @param data               Pointer to the candidate file data buffer.
 * @param length             Size of @p data in bytes.
 * @param eh                 Validated, endian-corrected 32-bit ELF header
 *                           providing pht_off, pht_entry_size, num_pht_entries,
 *                           and elf_header_size. Must not be NULL.
 * @param target_endianness  Endianness of the host system.
 * @param elf_endianness     Endianness of the ELF file; used to byte-swap PHT
 *                           entry fields when it differs from the host.
 *
 * @return  Best-effort file size estimate in bytes (>= elf_header_size), or
 *          0 on any error (NULL header, absent PHT, invalid entry size, or
 *          any segment extent exceeding @p length).
 */
static inline uint64_t calculate_elf_size_from_pht_32(
        char *data,
        uint64_t length,
        const Elf_Header_32 *eh,
        enum Endianness target_endianness,
        char elf_endianness){

    if (!eh || eh->pht_off == 0
        || eh->num_pht_entries == 0
        || eh->pht_entry_size == 0) {
        return 0;
    }

    /* Require at least the minimum ELF32 program header size. */
    if (eh->pht_entry_size < PHT_ENTRY_SIZE_32) {
        return 0;
    }

    /* Start with at least the end of the ELF header and the PHT region itself. */
    uint64_t max_end = eh->elf_header_size;
    __uint128_t pht_end = (__uint128_t)eh->pht_off +
                          (__uint128_t)eh->pht_entry_size * (__uint128_t)eh->num_pht_entries;
    if (pht_end > max_end){
        max_end = (uint64_t)pht_end;
    }
    if (pht_end > length){
        return 0;
    }

    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    uint64_t cur = eh->pht_off;
    for (uint16_t i = 0; i < eh->num_pht_entries; i++) {
        /* Bounds-check using the on-disk entry size. */
        if ((__uint128_t)cur + (__uint128_t)eh->pht_entry_size > length) {
            return 0;
        }

        Program_Header_Entry_32 phe;
        memset(&phe, 0, sizeof(Program_Header_Entry_32));

        /* Copy only the minimum required bytes for an ELF32 program header. */
        memcpy(&phe, &data[cur], PHT_ENTRY_SIZE_32);

        if (need_swap) {
            phe.seg_type      = __builtin_bswap32(phe.seg_type);
            phe.seg_offset    = __builtin_bswap32(phe.seg_offset);
            phe.seg_vaddr     = __builtin_bswap32(phe.seg_vaddr);
            phe.seg_physaddr  = __builtin_bswap32(phe.seg_physaddr);
            phe.seg_file_size = __builtin_bswap32(phe.seg_file_size);
            phe.seg_mem_size  = __builtin_bswap32(phe.seg_mem_size);
            phe.flags_32      = __builtin_bswap32(phe.flags_32);
            phe.alignment     = __builtin_bswap32(phe.alignment);
        }

        /* Consider any file-backed segment, not just PT_LOAD. */
        if (phe.seg_type != PT_NULL && phe.seg_file_size) {
            __uint128_t end = (__uint128_t)phe.seg_offset + (__uint128_t)phe.seg_file_size;
            if (end > length) return 0; /* Shouldn't happen if PHT was validated */
            if (end > max_end) max_end = (uint64_t)end;
        }

        cur += eh->pht_entry_size;
    }

    return max_end;
}



/**
 * @brief Estimate the total size of a 64-bit ELF file from its Program Header
 *        Table when no Section Header Table is available.
 *
 * This is the fallback size calculation used when SHT parsing fails or the SHT
 * is absent. It walks all PHT entries and returns the highest file-space byte
 * reached by any file-backed segment — i.e. max(seg_offset + seg_file_size)
 * across all non-PT_NULL entries with non-zero seg_file_size. The result is
 * initialised to the end of the ELF header and the PHT region itself, so it is
 * always at least as large as the headers even if all segments have zero filesz.
 *
 * The result is an estimation and is not rounded up to an alignment boundary.
 * The caller uses it directly for comparison against known region endpoints.
 *
 * Overflow in all bounds arithmetic is handled with __uint128_t. If any
 * segment's file extent exceeds @p length the function returns 0 immediately,
 * which the caller treats as a validation failure.
 *
 * For oversized PHT entries (pht_entry_size > PHT_ENTRY_SIZE_64), the struct
 * is zeroed before copying so that only the canonical 56 bytes are read and
 * extra bytes do not bleed into the parsed fields. Note that flags_64 in the
 * ELF64 PHT entry is a 32-bit field stored in a 64-bit slot; byte-swapping
 * uses a 32-bit swap via a uint32_t intermediate accordingly.
 *
 * @pre  The PHT has already been validated by PHT_validate_64 — bounds are
 *       assumed safe to read.
 *
 * @param data               Pointer to the candidate file data buffer.
 * @param length             Size of @p data in bytes.
 * @param eh                 Validated, endian-corrected 64-bit ELF header
 *                           providing pht_off, pht_entry_size, num_pht_entries,
 *                           and elf_header_size. Must not be NULL.
 * @param target_endianness  Endianness of the host system.
 * @param elf_endianness     Endianness of the ELF file; used to byte-swap PHT
 *                           entry fields when it differs from the host.
 *
 * @return  Best-effort file size estimate in bytes (>= elf_header_size), or
 *          0 on any error (NULL header, absent PHT, invalid entry size, or
 *          any segment extent exceeding @p length).
 */
static inline uint64_t calculate_elf_size_from_pht_64(
        char *data,
        uint64_t length,
        const Elf_Header_64 *eh,
        enum Endianness target_endianness,
        char elf_endianness){

    if (!eh || eh->pht_off == 0 || eh->num_pht_entries == 0 || eh->pht_entry_size == 0) {
        return 0;
    }

    /* Require at least the minimum ELF64 program header size. */
    if (eh->pht_entry_size < PHT_ENTRY_SIZE_64) {
        return 0;
    }

    /* Start with at least the end of the ELF header and the PHT region itself. */
    uint64_t max_end = eh->elf_header_size;
    __uint128_t pht_end = (__uint128_t)eh->pht_off +
                          (__uint128_t)eh->pht_entry_size * (__uint128_t)eh->num_pht_entries;
    if (pht_end > max_end){
        max_end = (uint64_t)pht_end;
    }
    if (pht_end > length){
        return 0;
    }

    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    uint64_t cur = eh->pht_off;
    for (uint16_t i = 0; i < eh->num_pht_entries; i++) {
        /* Bounds-check using the on-disk entry size. */
        if ((__uint128_t)cur + (__uint128_t)eh->pht_entry_size > length) {
            return 0;
        }

        Program_Header_Entry_64 phe;
        memset(&phe, 0, sizeof(Program_Header_Entry_64));

        /* Copy only the minimum required bytes for an ELF64 program header. */
        memcpy(&phe, &data[cur], PHT_ENTRY_SIZE_64);

        if (need_swap) {
            phe.seg_type      = __builtin_bswap32(phe.seg_type);
            uint32_t f32      = (uint32_t)phe.flags_64;
            f32               = __builtin_bswap32(f32);
            phe.flags_64      = (uint64_t)f32;

            phe.seg_offset    = __builtin_bswap64(phe.seg_offset);
            phe.seg_vaddr     = __builtin_bswap64(phe.seg_vaddr);
            phe.seg_physaddr  = __builtin_bswap64(phe.seg_physaddr);
            phe.seg_file_size = __builtin_bswap64(phe.seg_file_size);
            phe.seg_mem_size  = __builtin_bswap64(phe.seg_mem_size);
            phe.alignment     = __builtin_bswap64(phe.alignment);
        }

        /* Consider any file-backed segment, not just PT_LOAD. */
        if (phe.seg_type != PT_NULL && phe.seg_file_size) {
            __uint128_t end = (__uint128_t)phe.seg_offset + (__uint128_t)phe.seg_file_size;
            if (end > length) return 0;
            if (end > max_end) max_end = (uint64_t)end;
        }

        cur += eh->pht_entry_size;
    }

    return max_end;
}


// Helper for checking if a byte falls within printable ascii range
static inline bool shstr_is_printable_ascii(uint8_t c) {
    return (c >= 0x20 && c <= 0x7e);
}


/**
 * @brief Return whether a byte is allowed in an ELF section-name string.
 *
 * Accepts printable ASCII alphanumerics and a small set of common punctuation
 * characters used in section names (e.g., '.', '_', '-', '/').
 *
 * @param[in] c  Byte to test.
 * @retval true  @p c is a permitted name character.
 * @retval false @p c is not permitted (including non-printable ASCII).
 */
static inline bool shstr_is_name_char(uint8_t c) {
    if (!shstr_is_printable_ascii(c)) return false;

    if ((c >= 'a' && c <= 'z') ||
        (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9')) return true;

    switch (c) {
        case '.': case '_': case '-': case '/':
        case '@': case '$': case '+': case ':':
        case '~': case '=': case ',': case '%':
            return true;
        default:
            return false;
    }
}



/*-------------------------------------------------------------*/
/*     .shstrtab validation for elf_file_validate()            */
/*-------------------------------------------------------------*/

/**
 * @brief Validate a contiguous slice of a candidate `.shstrtab` section.
 *
 * Applies a series of heuristic checks to determine whether the byte range
 * [@p exp_off, @p exp_off + @p exp_size) within @p blk plausibly contains
 * ELF section-header string-table content. The checks are ordered from
 * cheapest to most expensive:
 *
 * -# **Bounds** — the slice must lie entirely within @p blocksize and be at
 *    least 16 bytes long.
 * -# **Character sanity** — at least one NUL byte must be present
 * -# **NUL distribution** — the first and last NUL in the slice must be
 *    distinct, ensuring there is room for at least one non-empty string.
 * -# **First-piece anchor** (when @p is_first_piece is true) — the slice
 *    must begin with NUL, or a '.' character must appear within the first
 *    32 bytes before the first NUL, reflecting the ELF convention that the
 *    first byte of `.shstrtab` is a NUL and most section names start with '.'.
 * -# **Last-piece anchor** (when @p is_last_piece is true) — a NUL byte
 *    must appear within the final 32 bytes of the slice, since a well-formed
 *    `.shstrtab` always ends with a NUL-terminated string.
 * -# **Token scan** — the bytes between the first and last NUL are walked as
 *    NUL-separated tokens. Each token must consist solely of characters
 *    accepted by @ref shstr_is_name_char and must not exceed 96 bytes.
 *    At least 3 tokens must be present, at least 30% must begin with '.',
 *    and if fewer than 8 tokens are found at least one must match a known
 *    `.shstrtab` marker string via @ref contains_shstrtab_markers.
 *
 * @param[in] blk           Pointer to the start of the containing block buffer.
 * @param[in] blocksize     Total size of @p blk in bytes.
 * @param[in] exp_off       Byte offset within @p blk at which the slice begins.
 * @param[in] exp_size      Length of the slice in bytes.
 * @param[in] is_first_piece  True if this slice is the first (or only) piece of
 *                            the candidate `.shstrtab`; enables the first-byte
 *                            anchor check.
 * @param[in] is_last_piece   True if this slice is the last (or only) piece of
 *                            the candidate `.shstrtab`; enables the trailing-NUL
 *                            proximity check.
 *
 * @retval true  The slice passes all applicable heuristic checks.
 * @retval false Any check fails: bad bounds, bad character distribution,
 *               malformed tokens, or insufficient dot-prefixed names.
 *
 * @note This is a heuristic validator intended for file-carving workflows.
 *       A @c true return indicates plausibility, not a guarantee of correctness.
 */
static bool validate_shstrtab_piece_slice(const uint8_t *blk,
                                          uint32_t blocksize,
                                          uint64_t exp_off,
                                          uint64_t exp_size,
                                          bool is_first_piece,
                                          bool is_last_piece,
                                          const ElfTunables *sp)
{
    if (!blk || !sp) return false;
    if (exp_off + exp_size > (uint64_t)blocksize) return false;
    if (exp_size < 16) return false;

    const uint8_t *p = blk + exp_off;
    const uint64_t n = exp_size;

    if (is_first_piece && p[0] != 0) return false;
    if (is_last_piece && p[n - 1] != 0) return false;

    uint64_t nul = 0;
    for (uint64_t i = 0; i < n; i++) {
        if (p[i] == 0) nul++;
    }
    if (nul == 0) return false;

    int64_t first_nul = -1, last_nul = -1;
    for (uint64_t i = 0; i < n; i++) if (p[i] == 0) { first_nul = (int64_t)i; break; }
    for (int64_t i = (int64_t)n - 1; i >= 0; i--) if (p[i] == 0) { last_nul = i; break; }
    if (first_nul < 0 || last_nul < 0 || last_nul < first_nul) return false;

    uint32_t tokens = 0, dot = 0;
    uint64_t i = (uint64_t)first_nul + 1;

    while (i <= (uint64_t)last_nul) {
        if (p[i] == 0) { i++; continue; }

        uint64_t s = i;
        uint32_t len = 0;

        while (i <= (uint64_t)last_nul && p[i] != 0) {
            if (!shstr_is_name_char(p[i])) return false;
            if (++len > sp->shstr_max_token_len) return false;
            i++;
        }
        if (i > (uint64_t)last_nul || p[i] != 0 || len == 0) break;

        tokens++;
        if (p[s] == '.') dot++;

        i++;
    }

    if (tokens < sp->shstr_min_tokens) return false;
    if ((uint64_t)dot * 100 < (uint64_t)tokens * (uint64_t)sp->shstr_min_dot_pct) return false;
    if (tokens < 8 && !contains_shstrtab_markers((const char *)p, (size_t)n)) return false;

    return true;
}



/**
 * @brief Check whether a candidate `.shstrtab` buffer is consistent with a
 *        Section Header Table (SHT).
 *
 * Iterates over @p shnum SHT entries in @p sht_bytes, reads each entry's
 * 32-bit @c sh_name field (byte-swapping if @p need_swap is true), and
 * attempts to resolve each offset into a valid, NUL-terminated name inside
 * @p shstr. A name is considered valid when:
 *
 * - @c sh_name is within bounds of @p shstr_sz.
 * - The byte at @c shstr[sh_name] is non-NUL (zero-offset / empty names are
 *   silently skipped, as SHT entry 0 conventionally has @c sh_name = 0).
 * - Every character from @c sh_name up to the terminating NUL is accepted by
 *   @ref shstr_is_name_char.
 * - The string terminates with a NUL within @p shstr_sz and within
 *   @c max_name_len (128) bytes.
 *
 * After scanning all entries the following thresholds are applied:
 *
 * - **Absolute minimum** — at least 2 good hits (safety floor).
 * - **Coverage ratio** — at least @c shstrtab_sht_min_resolve_pct percent of
 *   @p shnum entries must resolve to valid names (configurable via ElfTunables).
 
 * @param[in] sht_bytes  Pointer to a contiguous SHT buffer (may span multiple
 *                       underlying blocks; the caller is responsible for
 *                       assembling a flat view before calling).
 * @param[in] sht_len    Size of @p sht_bytes in bytes.
 * @param[in] shnum      Number of SHT entries expected in @p sht_bytes.
 * @param[in] entsize    Size of each SHT entry in bytes; must be ≥ 4 so that
 *                       @c sh_name can be read.
 * @param[in] need_swap  True if @c sh_name values must be byte-swapped before
 *                       use (i.e. the ELF file endianness differs from the
 *                       host endianness).
 * @param[in] shstr      Pointer to the candidate `.shstrtab` content.
 * @param[in] shstr_sz   Size of @p shstr in bytes.
 *
 * @retval true  The candidate `.shstrtab` satisfies all resolution thresholds.
 * @retval false A bounds check failed, or the resolved-name heuristics are
 *               not met (too few hits, coverage below 2/3, or fewer than 1/3
 *               of names begin with '.').
 *
 * @note This is a heuristic consistency check for carving and reassembly
 *       workflows. A @c true return indicates the two buffers are plausibly
 *       compatible, not that the ELF file is well-formed.
 */
static bool shstrtab_matches_sht(const uint8_t *sht_bytes,
                                 uint64_t sht_len,
                                 uint16_t shnum,
                                 uint16_t entsize,
                                 bool need_swap,
                                 const uint8_t *shstr,
                                 uint64_t shstr_sz,
                                 const ElfTunables *sp)
{
    if (!sht_bytes || !shstr || !sp) return false;
    if (shnum == 0) return false;
    if (entsize < 4) return false;

    const uint64_t need = (uint64_t)shnum * (uint64_t)entsize;
    if (need > sht_len) return false;
    if (shstr_sz < 2) return false;

    const uint32_t min_good_floor = 2;

    const uint32_t min_good = (uint32_t)(
        ((uint64_t)shnum * (uint64_t)sp->shstrtab_sht_min_resolve_pct + 99) / 100);
    const uint32_t effective_min =
        (min_good > min_good_floor) ? min_good : min_good_floor;

    const uint32_t max_name_len = sp->shstr_max_token_len;

    uint32_t good = 0;

    for (uint16_t i = 0; i < shnum; i++) {
        const uint8_t *e = sht_bytes + (uint64_t)i * (uint64_t)entsize;

        uint32_t sh_name = 0;
        memcpy(&sh_name, e + 0, 4);
        if (need_swap) sh_name = __builtin_bswap32(sh_name);

        if ((uint64_t)sh_name >= shstr_sz) continue;

        uint64_t j = (uint64_t)sh_name;

        if (shstr[j] == 0) continue;

        uint32_t len = 0;
        while (j < shstr_sz && shstr[j] != 0 && len < max_name_len) {
            if (!shstr_is_name_char(shstr[j])) break;
            j++;
            len++;
        }

        if (j >= shstr_sz) continue;
        if (shstr[j] != 0) continue;
        if (len == 0) continue;

        good++;
    }

    if (good < effective_min) return false;

    if ((uint64_t)good * 100 < (uint64_t)shnum * (uint64_t)sp->shstrtab_sht_min_resolve_pct) {
        return false;
    }

    return true;
}



/**
 * @brief Validate the `.shstrtab` section of a 64-bit ELF image.
 *
 * Given a mapped 64-bit ELF image in @p data and a parsed ELF header in
 * @p elf_header_64, this function locates the Section Header Table (SHT),
 * reads the SHT entry identified by @c e_shstrndx, and then performs two
 * layers of validation on the referenced `.shstrtab` section:
 *
 * 1. **Structural checks** — the SHT must fit within @p length; the string
 *    table's SHT entry must have type @c SHT_STRTAB and a minimum size of
 *    16 bytes; the section content must lie entirely within @p length.
 *
 * 2. **Content heuristics** (via @ref validate_shstrtab_piece_slice) — the
 *    raw bytes of the `.shstrtab` section must pass character-distribution,
 *    NUL-placement, token-structure, and dot-prefix checks.
 *
 * 3. **Cross-reference consistency** (via @ref shstrtab_matches_sht) — at
 *    least 2/3 of the SHT entries' @c sh_name offsets must resolve to valid,
 *    well-formed names within the candidate `.shstrtab`.
 *
 * Byte-swapping of all multi-byte SHT fields is applied when the ELF file
 * endianness (from @p elf_endianness) differs from the host endianness
 * (from @p target_endianness).
 *
 * @param[in] data               Pointer to the start of the ELF image buffer.
 * @param[in] length             Total size of @p data in bytes.
 * @param[in] target_endianness  Host endianness, used to determine whether
 *                               byte-swapping is required.
 * @param[in] elf_endianness     Endianness byte from the ELF @c e_ident field
 *                               (@c ELFDATA2LSB or @c ELFDATA2MSB).
 * @param[in] elf_header_64      Parsed 64-bit ELF header supplying SHT offset,
 *                               entry size, entry count, and @c e_shstrndx.
 *
 * @retval true  The `.shstrtab` section is structurally sound, passes content
 *               heuristics, and is consistent with the SHT @c sh_name offsets.
 * @retval false Any structural check fails, the content heuristics reject the
 *               section, or the cross-reference consistency check fails.
 *
 * @note Intended for use in a file-carving validator. A @c true return
 *       indicates that the ELF image is a plausible candidate, not that it
 *       is a fully conformant ELF file.
 */
static bool elf_validate_shstrtab_64(const char *data,
                                     uint64_t length,
                                     enum Endianness target_endianness,
                                     char elf_endianness,
                                     const Elf_Header_64 *elf_header_64,
                                     const ElfTunables *sp)
{
    if (!data || !elf_header_64 || !sp) return false;

    if (elf_header_64->sht_off == 0 ||
        elf_header_64->sht_entry_size == 0 ||
        elf_header_64->num_sht_entries == 0) {
        return false;
    }

    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    if (elf_header_64->sht_entry_size < SHT_ENTRY_SIZE_64) return false;
    if (elf_header_64->idx_section_names >= elf_header_64->num_sht_entries) return false;

    __uint128_t sht_end128 = (__uint128_t)elf_header_64->sht_off +
                             (__uint128_t)elf_header_64->sht_entry_size *
                             (__uint128_t)elf_header_64->num_sht_entries;
    if (sht_end128 > length) return false;

    uint64_t shstr_hdr_off = elf_header_64->sht_off +
                             (uint64_t)elf_header_64->idx_section_names *
                             (uint64_t)elf_header_64->sht_entry_size;

    if ((__uint128_t)shstr_hdr_off + (__uint128_t)SHT_ENTRY_SIZE_64 > length) return false;

    Section_Header_Entry_64 sh;
    memcpy(&sh, data + shstr_hdr_off, sizeof(Section_Header_Entry_64));

    if (need_swap) {
        sh.sect_name_off  = __builtin_bswap32(sh.sect_name_off);
        sh.section_type   = __builtin_bswap32(sh.section_type);
        sh.flags          = __builtin_bswap64(sh.flags);
        sh.sect_mem_addr  = __builtin_bswap64(sh.sect_mem_addr);
        sh.sect_file_off  = __builtin_bswap64(sh.sect_file_off);
        sh.sect_size      = __builtin_bswap64(sh.sect_size);
        sh.sect_idx       = __builtin_bswap32(sh.sect_idx);
        sh.sect_info      = __builtin_bswap32(sh.sect_info);
        sh.sect_align     = __builtin_bswap64(sh.sect_align);
        sh.entry_size     = __builtin_bswap64(sh.entry_size);
    }

    if (sh.section_type != SECTION_TYPE_STRTAB) return false;
    if (sh.sect_size < 16) return false;

    __uint128_t shstr_end = (__uint128_t)sh.sect_file_off + (__uint128_t)sh.sect_size;
    if (shstr_end > length) return false;

    const uint8_t *shstr    = (const uint8_t *)(data + sh.sect_file_off);
    uint64_t       shstr_sz = (uint64_t)sh.sect_size;

    if (!validate_shstrtab_piece_slice(shstr, (uint32_t)shstr_sz, 0, shstr_sz,
                                       true, true, sp)) {
        return false;
    }

    const uint8_t *sht_bytes = (const uint8_t *)(data + elf_header_64->sht_off);
    uint64_t sht_len = (uint64_t)elf_header_64->sht_entry_size *
                       (uint64_t)elf_header_64->num_sht_entries;

    if (!shstrtab_matches_sht(sht_bytes,
                              sht_len,
                              elf_header_64->num_sht_entries,
                              elf_header_64->sht_entry_size,
                              need_swap,
                              shstr,
                              shstr_sz,
                              sp)) {
        return false;
    }

    return true;
}



/**
 * @brief Validate the `.shstrtab` section of a 32-bit ELF image.
 *
 * Identical in logic to @ref elf_validate_shstrtab_64, but operates on a
 * 32-bit ELF image. All SHT field widths are 32 bits and the minimum SHT
 * entry size is @c SHT_ENTRY_SIZE_32 rather than @c SHT_ENTRY_SIZE_64.
 * All offset and size arithmetic is widened to @c uint64_t internally to
 * prevent overflow on large inputs.
 *
 * See @ref elf_validate_shstrtab_64 for a full description of the three
 * validation layers (structural checks, content heuristics, and SHT
 * cross-reference consistency).
 *
 * @param[in] data               Pointer to the start of the ELF image buffer.
 * @param[in] length             Total size of @p data in bytes.
 * @param[in] target_endianness  Host endianness, used to determine whether
 *                               byte-swapping is required.
 * @param[in] elf_endianness     Endianness byte from the ELF @c e_ident field
 *                               (@c ELFDATA2LSB or @c ELFDATA2MSB).
 * @param[in] elf_header_32      Parsed 32-bit ELF header supplying SHT offset,
 *                               entry size, entry count, and @c e_shstrndx.
 *
 * @retval true  The `.shstrtab` section is structurally sound, passes content
 *               heuristics, and is consistent with the SHT @c sh_name offsets.
 * @retval false Any structural check fails, the content heuristics reject the
 *               section, or the cross-reference consistency check fails.
 *
 * @note Intended for use in a file-carving validator. A @c true return
 *       indicates that the ELF image is a plausible candidate, not that it
 *       is a fully conformant ELF file.
 */
static bool elf_validate_shstrtab_32(const char *data,
                                     uint64_t length,
                                     enum Endianness target_endianness,
                                     char elf_endianness,
                                     const Elf_Header_32 *elf_header_32,
                                     const ElfTunables *sp)
{
    if (!data || !elf_header_32 || !sp) return false;

    if (elf_header_32->sht_off == 0 ||
        elf_header_32->sht_entry_size == 0 ||
        elf_header_32->num_sht_entries == 0) {
        return false;
    }

    const int file_is_le = (elf_endianness == ELF_LITTLE_ENDIAN);
    const int host_is_le = (target_endianness == LITTLE);
    const int need_swap  = (file_is_le != host_is_le);

    if (elf_header_32->sht_entry_size < SHT_ENTRY_SIZE_32) return false;
    if (elf_header_32->idx_section_names >= elf_header_32->num_sht_entries) return false;

    __uint128_t sht_end128 = (__uint128_t)elf_header_32->sht_off +
                             (__uint128_t)elf_header_32->sht_entry_size *
                             (__uint128_t)elf_header_32->num_sht_entries;
    if (sht_end128 > length) return false;

    uint64_t shstr_hdr_off = (uint64_t)elf_header_32->sht_off +
                             (uint64_t)elf_header_32->idx_section_names *
                             (uint64_t)elf_header_32->sht_entry_size;

    if ((__uint128_t)shstr_hdr_off + (__uint128_t)SHT_ENTRY_SIZE_32 > length) return false;

    Section_Header_Entry_32 sh;
    memcpy(&sh, data + shstr_hdr_off, sizeof(Section_Header_Entry_32));

    if (need_swap) {
        sh.sect_name_off  = __builtin_bswap32(sh.sect_name_off);
        sh.section_type   = __builtin_bswap32(sh.section_type);
        sh.flags          = __builtin_bswap32(sh.flags);
        sh.sect_mem_addr  = __builtin_bswap32(sh.sect_mem_addr);
        sh.sect_file_off  = __builtin_bswap32(sh.sect_file_off);
        sh.sect_size      = __builtin_bswap32(sh.sect_size);
        sh.sect_idx       = __builtin_bswap32(sh.sect_idx);
        sh.sect_info      = __builtin_bswap32(sh.sect_info);
        sh.sect_align     = __builtin_bswap32(sh.sect_align);
        sh.entry_size     = __builtin_bswap32(sh.entry_size);
    }

    if (sh.section_type != SECTION_TYPE_STRTAB) return false;
    if ((uint64_t)sh.sect_size < 16) return false;

    __uint128_t shstr_end = (__uint128_t)sh.sect_file_off + (__uint128_t)sh.sect_size;
    if (shstr_end > length) return false;

    const uint8_t *shstr    = (const uint8_t *)(data + sh.sect_file_off);
    uint64_t       shstr_sz = (uint64_t)sh.sect_size;

    if (!validate_shstrtab_piece_slice(shstr, (uint32_t)shstr_sz, 0, shstr_sz,
                                       true, true, sp)) {
        return false;
    }

    const uint8_t *sht_bytes = (const uint8_t *)(data + elf_header_32->sht_off);
    uint64_t sht_len = (uint64_t)elf_header_32->sht_entry_size *
                       (uint64_t)elf_header_32->num_sht_entries;

    if (!shstrtab_matches_sht(sht_bytes,
                              sht_len,
                              elf_header_32->num_sht_entries,
                              elf_header_32->sht_entry_size,
                              need_swap,
                              shstr,
                              shstr_sz,
                              sp)) {
        return false;
    }

    return true;
}



/***************************************************************/
/*          FUNCTION DEFINITONS FOR CROSS VALIDATION           */
/***************************************************************/

static inline double clampd(double x, double lo, double hi) {
    return (x < lo) ? lo : (x > hi) ? hi : x;
}

static inline double sigmoid_stable(double x){
    if (x >= 0.0) {
        double z = exp(-x);
        return 1.0 / (1.0 + z);
    } else {
        double z = exp(x);
        return z / (1.0 + z);
    }
}

static inline double logit_from_prob(double p){
    /* clamp to avoid inf */
    const double eps = 1e-12;
    if (p < eps) p = eps;
    if (p > 1.0 - eps) p = 1.0 - eps;
    return log(p / (1.0 - p));
}


// Quick endianness fixes for already-loaded fields
static inline uint16_t to_host_endian_16(uint16_t v, bool file_le) { return file_le ? v : __builtin_bswap16(v); }
static inline uint32_t to_host_endian_32(uint32_t v, bool file_le) { return file_le ? v : __builtin_bswap32(v); }
static inline uint64_t to_host_endian_64(uint64_t v, bool file_le) { return file_le ? v : __builtin_bswap64(v); }

// Simple Comparison utilities
static inline int cmp_filecomponent_offset(const void *a, const void *b) {
    const FileComponent *fa = a;
    const FileComponent *fb = b;
    if (fa->fileOffset < fb->fileOffset) return -1;
    if (fa->fileOffset > fb->fileOffset) return 1;
    return 0;
}
static inline bool str_eq(const char *a, const char *b) {
    return a && b && strcmp(a,b)==0;
}
static inline bool str_has_prefix(const char *s, const char *p) {
    return s && p && strncmp(s,p,strlen(p))==0;
}


/* ------------------------------------------------------------
 * Architecture / Machine Type Checks
 * ------------------------------------------------------------ */

static inline uint16_t get_elf_machine_type(const uint8_t *eh,
                                            bool is_64bit,
                                            bool file_is_le){
    (void)is_64bit;
    uint16_t raw = *(const uint16_t *)(eh + 18);
    return to_host_endian_16(raw, file_is_le);
}

static inline bool is_x86_64_architecture(uint16_t machine_type){
    return machine_type == EM_X86_64;
}

static inline bool is_x86_architecture(uint16_t machine_type){
    return machine_type == EM_386;
}

static inline bool is_arm_architecture(uint16_t machine_type){
    return machine_type == EM_ARM;
}

static inline bool is_arm64_architecture(uint16_t machine_type){
    return machine_type == EM_AARCH64;
}

static inline bool is_supported_architecture(uint16_t machine_type){
    return is_x86_64_architecture(machine_type) ||
           is_x86_architecture(machine_type)    ||
           is_arm_architecture(machine_type)    ||
           is_arm64_architecture(machine_type);
}


/* ------------------------------------------------------------
 * Validation helpers that reference the PHT
 * ------------------------------------------------------------ */

// CHECK IF AN ADDRESS FALLS WITHIN PT_LOAD RANGES
static inline bool is_valid_virtual_address(uint64_t vaddr,
                                            const SegmentInfo *segments,
                                            size_t num_segments){
    for (size_t i = 0; i < num_segments; i++){
        if (segments[i].seg_type == PT_LOAD){
            uint64_t vaddr_start = segments[i].seg_vaddr;
            uint64_t vaddr_end   = vaddr_start + segments[i].seg_mem_size;

            if (vaddr >= vaddr_start && vaddr < vaddr_end){
                return true;
            }
        }
    }
    return false;
}

// Build the complete program-segment list from the candidate PHT.
static inline SegmentInfo *build_segment_ranges(CarveInfo *candidate,
                                                size_t *num_segments_out)
{
    uint8_t header_data[64];
    uint8_t entry_data[sizeof(Program_Header_Entry_64)];
    SegmentInfo *segments = NULL;
    size_t segment_count = 0;
    size_t segment_capacity = 0;
    uint64_t pht_offset = 0;
    uint64_t sht_offset = 0;
    uint64_t pht_num_entries = 0;
    uint16_t pht_entry_size = 0;
    uint16_t sht_entry_size = 0;
    uint8_t elf_class;
    bool file_is_le;
    size_t canonical_entry_size;

    if (num_segments_out) {
        *num_segments_out = 0;
    }
    if (!candidate || !candidate->b || !num_segments_out
        || !read_candidate_bytes(candidate, 0, sizeof(header_data),
                                 header_data)
        || header_data[0] != 0x7f || header_data[1] != 'E'
        || header_data[2] != 'L' || header_data[3] != 'F') {
        return NULL;
    }

    elf_class = header_data[4];
    file_is_le = header_data[5] == ELF_LITTLE_ENDIAN;
    if ((elf_class != ELF_32_BIT && elf_class != ELF_64_BIT)
        || (header_data[5] != ELF_LITTLE_ENDIAN
            && header_data[5] != ELF_BIG_ENDIAN)) {
        return NULL;
    }

    if (elf_class == ELF_64_BIT) {
        Elf_Header_64 ehdr;

        memcpy(&ehdr, header_data + ELF_BYTES_START, sizeof(ehdr));
        pht_offset = to_host_endian_64(ehdr.pht_off, file_is_le);
        sht_offset = to_host_endian_64(ehdr.sht_off, file_is_le);
        pht_entry_size =
            to_host_endian_16(ehdr.pht_entry_size, file_is_le);
        sht_entry_size =
            to_host_endian_16(ehdr.sht_entry_size, file_is_le);
        pht_num_entries =
            to_host_endian_16(ehdr.num_pht_entries, file_is_le);
        canonical_entry_size = sizeof(Program_Header_Entry_64);

        if (pht_num_entries == ELF_PN_XNUM) {
            Section_Header_Entry_64 first_section;

            if (sht_offset == 0
                || sht_entry_size < sizeof(first_section)
                || !read_candidate_bytes(candidate, sht_offset,
                                         sizeof(first_section),
                                         (uint8_t *)&first_section)) {
                return NULL;
            }
            pht_num_entries =
                to_host_endian_32(first_section.sect_info, file_is_le);
        }
    }
    else {
        Elf_Header_32 ehdr;

        memcpy(&ehdr, header_data + ELF_BYTES_START, sizeof(ehdr));
        pht_offset = to_host_endian_32(ehdr.pht_off, file_is_le);
        sht_offset = to_host_endian_32(ehdr.sht_off, file_is_le);
        pht_entry_size =
            to_host_endian_16(ehdr.pht_entry_size, file_is_le);
        sht_entry_size =
            to_host_endian_16(ehdr.sht_entry_size, file_is_le);
        pht_num_entries =
            to_host_endian_16(ehdr.num_pht_entries, file_is_le);
        canonical_entry_size = sizeof(Program_Header_Entry_32);

        if (pht_num_entries == ELF_PN_XNUM) {
            Section_Header_Entry_32 first_section;

            if (sht_offset == 0
                || sht_entry_size < sizeof(first_section)
                || !read_candidate_bytes(candidate, sht_offset,
                                         sizeof(first_section),
                                         (uint8_t *)&first_section)) {
                return NULL;
            }
            pht_num_entries =
                to_host_endian_32(first_section.sect_info, file_is_le);
        }
    }

    if (pht_offset == 0 || pht_num_entries == 0
        || pht_entry_size < canonical_entry_size) {
        return NULL;
    }

    for (uint64_t i = 0; i < pht_num_entries; i++) {
        uint64_t entry_delta;
        uint64_t entry_offset;
        SegmentInfo segment = {0};

        if (__builtin_mul_overflow(i, (uint64_t)pht_entry_size,
                                   &entry_delta)
            || __builtin_add_overflow(pht_offset, entry_delta,
                                      &entry_offset)
            || !read_candidate_bytes(candidate, entry_offset,
                                     canonical_entry_size, entry_data)) {
            continue;
        }

        if (elf_class == ELF_64_BIT) {
            Program_Header_Entry_64 entry;

            memcpy(&entry, entry_data, sizeof(entry));
            segment.seg_type =
                to_host_endian_32(entry.seg_type, file_is_le);
            segment.seg_flags =
                to_host_endian_32(entry.flags_64, file_is_le);
            segment.seg_offset =
                to_host_endian_64(entry.seg_offset, file_is_le);
            segment.seg_file_size =
                to_host_endian_64(entry.seg_file_size, file_is_le);
            segment.seg_vaddr =
                to_host_endian_64(entry.seg_vaddr, file_is_le);
            segment.seg_mem_size =
                to_host_endian_64(entry.seg_mem_size, file_is_le);
        }
        else {
            Program_Header_Entry_32 entry;

            memcpy(&entry, entry_data, sizeof(entry));
            segment.seg_type =
                to_host_endian_32(entry.seg_type, file_is_le);
            segment.seg_flags =
                to_host_endian_32(entry.flags_32, file_is_le);
            segment.seg_offset =
                to_host_endian_32(entry.seg_offset, file_is_le);
            segment.seg_file_size =
                to_host_endian_32(entry.seg_file_size, file_is_le);
            segment.seg_vaddr =
                to_host_endian_32(entry.seg_vaddr, file_is_le);
            segment.seg_mem_size =
                to_host_endian_32(entry.seg_mem_size, file_is_le);
        }

        if (segment_count == segment_capacity) {
            size_t new_capacity =
                segment_capacity == 0 ? 8 : segment_capacity * 2;
            SegmentInfo *grown;

            if (new_capacity < segment_capacity
                || new_capacity > SIZE_MAX / sizeof(*segments)) {
                free(segments);
                return NULL;
            }
            grown = (SegmentInfo *)realloc(
                segments, new_capacity * sizeof(*segments));
            if (!grown) {
                free(segments);
                return NULL;
            }
            segments = grown;
            segment_capacity = new_capacity;
        }
        segments[segment_count++] = segment;
    }

    if (segment_count == 0) {
        free(segments);
        return NULL;
    }
    *num_segments_out = segment_count;
    return segments;
}



/* ------------------------------------------------------------
 * Virtual Address / File Offset mapping utilities
 * ------------------------------------------------------------ */
/**
 * @brief Read a file-range from the candidate into @p out (gathers across blocks).
 *        Returns false if any block is missing.
 */
static inline bool read_candidate_bytes(CarveInfo *candidate,
                                        uint64_t file_off,
                                        uint64_t size,
                                        uint8_t *out){
    const uint64_t bs = scalpel_state.blocksize;
    uint64_t num_blocks;
    uint64_t remaining = size;
    uint64_t pos = file_off;

    if (!candidate || !candidate->b || (size > 0 && !out)
        || bs == 0 || file_off > UINT64_MAX - size) {
        return false;
    }
    num_blocks = blockvector_get_num_blocks(candidate->b);

    while (remaining > 0) {
        uint64_t bv_index = pos / bs;
        uint64_t in_block = pos % bs;
        uint64_t chunk = bs - in_block;
        if (chunk > remaining) {
            chunk = remaining;
        }
        if (bv_index >= num_blocks) {
            return false;
        }

        int64_t ap = blockvector_get_apparent_blocknumber(candidate->b, bv_index);
        if (ap == -1) {
            return false;
        }
        uint8_t *blk = get_apparent_block_data(scalpel_state.filemirror, ap);
        if (!blk) {
            return false;
        }
        memcpy(out + (size - remaining), blk + in_block, (size_t)chunk);
        free(blk);

        remaining -= chunk;
        pos += chunk;
    }
    return true;
}


// Read the multi-byte portion of an ELF header after the 16-byte identity.
static inline bool read_candidate_elf_header_32(
    CarveInfo *candidate,
    Elf_Header_32 *header)
{
    uint8_t raw[ELF_BYTES_START + sizeof(Elf_Header_32)];

    if (!header
        || !read_candidate_bytes(candidate, 0, sizeof(raw), raw)) {
        return false;
    }
    memcpy(header, raw + ELF_BYTES_START, sizeof(*header));
    return true;
}


// Read the multi-byte portion of an ELF header after the 16-byte identity.
static inline bool read_candidate_elf_header_64(
    CarveInfo *candidate,
    Elf_Header_64 *header)
{
    uint8_t raw[ELF_BYTES_START + sizeof(Elf_Header_64)];

    if (!header
        || !read_candidate_bytes(candidate, 0, sizeof(raw), raw)) {
        return false;
    }
    memcpy(header, raw + ELF_BYTES_START, sizeof(*header));
    return true;
}


/*
 * Read bytes from the candidate's initial contiguous-layout hypothesis
 * without changing its blockvector. This supplies optional structural
 * evidence when a logically contiguous metadata range has not yet been
 * placed by reassembly.
 */
static inline bool read_candidate_contiguous_baseline_bytes(
    CarveInfo *candidate,
    uint64_t file_off,
    uint64_t size,
    uint8_t *out)
{
    const uint64_t blocksize = scalpel_state.blocksize;
    const int64_t apparent_blocks =
        filemirror_apparent_blocks(scalpel_state.filemirror);
    int64_t header_apparent;
    uint64_t remaining = size;
    uint64_t position = file_off;

    if (!candidate || !candidate->b || (size > 0 && !out)
        || blocksize == 0 || apparent_blocks <= 0
        || file_off > UINT64_MAX - size) {
        return false;
    }

    header_apparent =
        blockvector_get_apparent_blocknumber(candidate->b, 0);
    if (header_apparent < 0) {
        return false;
    }

    while (remaining > 0) {
        const uint64_t block_index = position / blocksize;
        const uint64_t in_block = position % blocksize;
        uint64_t chunk = blocksize - in_block;
        int64_t apparent;

        if (chunk > remaining) {
            chunk = remaining;
        }
        if (block_index > (uint64_t)(INT64_MAX - header_apparent)
            || chunk > UINT32_MAX) {
            return false;
        }

        apparent = header_apparent + (int64_t)block_index;
        if (apparent < 0 || apparent >= apparent_blocks
            || !get_apparent_block_bytes(
                   scalpel_state.filemirror, apparent, in_block,
                   (uint32_t)chunk, out + (size - remaining))) {
            return false;
        }

        remaining -= chunk;
        position += chunk;
    }

    return true;
}


/*
 * File-offset <-> link-time virtual address translation helpers.
 *
 * These functions map between on-disk file offsets and the virtual addresses
 * recorded in the ELF file (p_vaddr, sh_addr, st_value, and DT_* pointer
 * tags). They are used to perform internal consistency checks — for example,
 * verifying that a relocation's r_offset falls inside the section it targets,
 * or that a DT_SYMTAB pointer corresponds to a file-backed PT_LOAD range.
 *
 * Important limitations:
 *
 *   - Link-time VAs only. For ET_DYN objects (shared libraries and PIE
 *     executables) the dynamic linker applies a load bias at runtime, so
 *     actual in-memory addresses are (load_bias + ELF_VA). That bias is
 *     unknown at carving time and is intentionally ignored here. All
 *     comparisons are made purely within the ELF file's own address space,
 *     never against runtime addresses.
 *
 *   - File-backed ranges only. Mapping is performed through PT_LOAD segments
 *     using p_offset and p_filesz. Addresses that fall in the memory-only
 *     portion of a segment (p_filesz < p_memsz, e.g. .bss) cannot be mapped
 *     to a file offset and will cause the mapping functions to return false.
 *
 *   - Single-segment containment. A range must be wholly contained within one
 *     PT_LOAD segment to be mapped. Ranges that straddle segment boundaries
 *     are not supported.
 */

/**
 * @brief Map a file-range [file_off, file_off+len) to a single PT_LOAD VA range.
 *        Fails if not wholly contained in one PT_LOAD or if PHT cannot be built.
 */
static inline bool map_file_range_to_va(CarveInfo *candidate,
                                        uint64_t file_off,
                                        uint64_t len,
                                        uint64_t *va_start_out,
                                        uint64_t *va_end_out){
    size_t nsegs = 0;
    SegmentInfo *segs = build_segment_ranges(candidate, &nsegs);
    bool found = false;

    if (!segs || nsegs == 0) {
        free(segs);
        return false;
    }

    for (size_t i = 0; i < nsegs; ++i) {
        if (segs[i].seg_type != PT_LOAD) {
            continue;
        }
        uint64_t p_off = segs[i].seg_offset;
        uint64_t p_fsz = segs[i].seg_file_size;
        uint64_t delta;

        if (file_off >= p_off
            && (delta = file_off - p_off) <= p_fsz
            && len <= p_fsz - delta
            && segs[i].seg_vaddr <= UINT64_MAX - delta
            && segs[i].seg_vaddr + delta <= UINT64_MAX - len) {
            uint64_t va0 = segs[i].seg_vaddr + delta;
            uint64_t va1 = va0 + len;
            if (va_start_out) {
                *va_start_out = va0;
            }
            if (va_end_out) {
                *va_end_out = va1;
            }
            found = true;
            break;
        }
    }
    free(segs);
    return found;
}

/**
 * @brief Map a VA into file offset using PT_LOAD (only if VA lies within file-backed part).
 */
static inline bool map_va_to_file_off(CarveInfo *candidate,
                                      uint64_t va,
                                      uint64_t *file_off_out){
    size_t nsegs = 0;
    SegmentInfo *segs = build_segment_ranges(candidate, &nsegs);
    bool found = false;

    if (!segs || nsegs == 0) {
        free(segs);
        return false;
    }

    for (size_t i = 0; i < nsegs; ++i) {
        if (segs[i].seg_type != PT_LOAD) {
            continue;
        }
        uint64_t v0 = segs[i].seg_vaddr;
        if (va >= v0 && va - v0 < segs[i].seg_file_size) {
            uint64_t delta = va - v0;
            if (segs[i].seg_offset <= UINT64_MAX - delta
                && file_off_out) {
                *file_off_out = segs[i].seg_offset + delta;
            }
            if (segs[i].seg_offset <= UINT64_MAX - delta) {
                found = true;
                break;
            }
        }
    }
    free(segs);
    return found;
}



/**
 * @brief Map a section header’s memory range to a PT_LOAD-backed VA interval.
 *
 * Given a parsed section header (already endian-correct) and the list of
 * PT_LOAD segments for the candidate, this function checks whether the
 * section’s in-memory range
 *
 *     [sh->sect_mem_addr, sh->sect_mem_addr + sh->sect_size)
 *
 * is fully contained inside one of the PT_LOAD segments. If so, it returns
 * that interval via @p out_va0 and @p out_va1.
 *
 * This is used by higher-level validators (e.g. relocation-vs-SHT checks) to
 * verify that relocation offsets actually fall inside the section that the
 * relocation section (sh_info) claims to target.
 *
 * @param[in]  sh       Parsed section header (widened to 64-bit form).
 * @param[in]  segs     Array of PT_LOAD segment descriptors.
 * @param[in]  nsegs    Number of elements in @p segs.
 * @param[out] out_va0  On success, start VA of the section.
 * @param[out] out_va1  On success, end VA (one past last byte) of the section.
 *
 * @return true if the section is fully contained in some PT_LOAD segment,
 *         false otherwise.
 */
static inline bool section_to_va_range(const Section_Header_Entry_64 *sh,
                                        const SegmentInfo *segs,
                                        size_t nsegs,
                                        uint64_t *out_va0,
                                        uint64_t *out_va1){

    uint64_t sec_va  = sh->sect_mem_addr;
    uint64_t sec_len = sh->sect_size;

    if (sec_va == 0 || sec_len == 0) {
        return false;
    }

    uint64_t sec_end = sec_va + sec_len;

    for (size_t i = 0; i < nsegs; ++i) {
        uint64_t seg_va   = segs[i].seg_vaddr;
        uint64_t seg_end  = seg_va + segs[i].seg_mem_size;

        if (sec_va >= seg_va && sec_end <= seg_end) {
            *out_va0 = sec_va;
            *out_va1 = sec_end;
            return true;
        }
    }

    return false;
}



/* ------------------------------------------------------------
 * Entry reader utilities
 * ------------------------------------------------------------ */
static inline uint64_t
read_reloc_offset(const uint8_t *p,
                  bool is_64,
                  bool is_rela,
                  bool file_is_le){
    if (is_64) {
        if (is_rela) {
            Elf64_Rela r;

            memcpy(&r, p, sizeof(r));
            return to_host_endian_64(r.r_offset, file_is_le);
        } else {
            Elf64_Rel r;

            memcpy(&r, p, sizeof(r));
            return to_host_endian_64(r.r_offset, file_is_le);
        }
    } else {
        if (is_rela) {
            Elf32_Rela r;

            memcpy(&r, p, sizeof(r));
            return (uint64_t)to_host_endian_32(r.r_offset, file_is_le);
        } else {
            Elf32_Rel r;

            memcpy(&r, p, sizeof(r));
            return (uint64_t)to_host_endian_32(r.r_offset, file_is_le);
        }
    }
}


static inline bool
get_sht_entry(CarveInfo                *cand,
              uint16_t                  index,
              bool                      is_64,
              bool                      file_is_le,
              Section_Header_Entry_64  *out_sh)
{
    if (is_64) {
        Elf_Header_64 eh;
        if (!read_candidate_elf_header_64(cand, &eh)) {
            return false;
        }

        uint64_t sht_off     = to_host_endian_64(eh.sht_off,     file_is_le);
        uint16_t sht_entsize = to_host_endian_16(eh.sht_entry_size, file_is_le);
        uint16_t sht_num     = to_host_endian_16(eh.num_sht_entries, file_is_le);

        if (index >= sht_num) {
            return false;
        }

        uint64_t off = sht_off + (uint64_t)index * (uint64_t)sht_entsize;

        Section_Header_Entry_64 raw;
        if (!read_candidate_bytes(cand, off, sizeof(raw), (uint8_t *)&raw)) {
            return false;
        }

        /* endian-fix into out_sh */
        out_sh->sect_name_off = to_host_endian_32(raw.sect_name_off, file_is_le);
        out_sh->section_type  = to_host_endian_32(raw.section_type,  file_is_le);
        out_sh->flags         = to_host_endian_64(raw.flags,         file_is_le);
        out_sh->sect_mem_addr = to_host_endian_64(raw.sect_mem_addr, file_is_le);
        out_sh->sect_file_off = to_host_endian_64(raw.sect_file_off, file_is_le);
        out_sh->sect_size     = to_host_endian_64(raw.sect_size,     file_is_le);
        out_sh->sect_idx      = to_host_endian_32(raw.sect_idx,      file_is_le);
        out_sh->sect_info     = to_host_endian_32(raw.sect_info,     file_is_le);
        out_sh->sect_align    = to_host_endian_64(raw.sect_align,    file_is_le);
        out_sh->entry_size    = to_host_endian_64(raw.entry_size,    file_is_le);
        return true;

    } else {
        Elf_Header_32 eh;
        if (!read_candidate_elf_header_32(cand, &eh)) {
            return false;
        }

        uint32_t sht_off     = to_host_endian_32(eh.sht_off,        file_is_le);
        uint16_t sht_entsize = to_host_endian_16(eh.sht_entry_size, file_is_le);
        uint16_t sht_num     = to_host_endian_16(eh.num_sht_entries,file_is_le);

        if (index >= sht_num) {
            return false;
        }

        uint64_t off = (uint64_t)sht_off + (uint64_t)index * (uint64_t)sht_entsize;

        Section_Header_Entry_32 raw32;
        if (!read_candidate_bytes(cand, off, sizeof(raw32), (uint8_t *)&raw32)) {
            return false;
        }

        /* widen 32-bit into 64-bit out struct so caller has one type */
        out_sh->sect_name_off = to_host_endian_32(raw32.sect_name_off, file_is_le);
        out_sh->section_type  = to_host_endian_32(raw32.section_type,  file_is_le);
        out_sh->flags         = (uint64_t)to_host_endian_32(raw32.flags, file_is_le);
        out_sh->sect_mem_addr = (uint64_t)to_host_endian_32(raw32.sect_mem_addr, file_is_le);
        out_sh->sect_file_off = (uint64_t)to_host_endian_32(raw32.sect_file_off, file_is_le);
        out_sh->sect_size     = (uint64_t)to_host_endian_32(raw32.sect_size,     file_is_le);
        out_sh->sect_idx      = to_host_endian_32(raw32.sect_idx,      file_is_le);
        out_sh->sect_info     = to_host_endian_32(raw32.sect_info,     file_is_le);
        out_sh->sect_align    = (uint64_t)to_host_endian_32(raw32.sect_align,    file_is_le);
        out_sh->entry_size    = (uint64_t)to_host_endian_32(raw32.entry_size,    file_is_le);
        return true;
    }
}


/* ------------------------------------------------------------
 * .dynamic parsing
 * ------------------------------------------------------------ */

/**
 * @brief Parse a candidate's @c .dynamic section into a @ref DynamicView.
 *
 * Walks the @c Elf{32,64}_Dyn array at file offset @p dyn_file_off and
 * extracts a summary of the dynamic linking metadata into @p dv_out. The
 * result is used by higher-level cross-validation routines to verify that
 * relocation tables, symbol tables, and string tables are internally
 * consistent with what the @c .dynamic section advertises.
 *
 * ELF class (32/64-bit) and byte order are autodetected from the candidate's
 * first apparent block (the ELF header block at BV slot 0).
 *
 * The following @c DT_* tags are recorded when encountered:
 *   - Relocations: @c DT_RELA / @c DT_RELASZ / @c DT_RELAENT,
 *                  @c DT_REL  / @c DT_RELSZ  / @c DT_RELENT,
 *                  @c DT_JMPREL / @c DT_PLTRELSZ / @c DT_PLTREL.
 *   - Symbols:     @c DT_SYMTAB / @c DT_SYMENT.
 *   - Strings:     @c DT_STRTAB / @c DT_STRSZ.
 *   - Hash tables: @c DT_HASH (SysV) / @c DT_GNU_HASH.
 *   - Flags:       @c DT_TEXTREL.
 *
 * Parsing stops at the first @c DT_NULL entry or when the slice is exhausted.
 * All virtual-address values are stored as link-time ELF VAs; no load-bias
 * adjustment is applied (see the VA translation comment block for details).
 *
 * After the main walk, if a SysV hash table (@c DT_HASH) was found, its
 * header is read to derive @c dynsym_count_sysv (= @c nchain, the number of
 * dynamic symbol table entries). If a GNU hash table (@c DT_GNU_HASH) was
 * found, its header is read to derive @c gnu_symoffset (= the symbol table
 * index of the first hashed symbol). Both reads are performed via
 * @ref map_va_to_file_off followed by @ref read_candidate_bytes and are
 * silently skipped if the mapping fails.
 *
 * Only the four supported architectures are accepted: @c EM_386,
 * @c EM_X86_64, @c EM_ARM, and @c EM_AARCH64. Any other @c e_machine value
 * causes an early return of @c false.
 *
 * @param[in]  candidate    Carving/reassembly context; provides the block
 *                          vector used to read the ELF header and the
 *                          @c .dynamic slice.
 * @param[in]  dyn_file_off File offset (within the candidate view) where the
 *                          @c .dynamic slice begins.
 * @param[in]  dyn_size     Size in bytes of the @c .dynamic slice. The range
 *                          must fit within the current candidate.
 * @param[out] dv_out       Receives the parsed dynamic metadata. Zeroed on
 *                          entry regardless of outcome. Must not be NULL.
 *
 * @retval true  Parsing succeeded; @p dv_out is populated.
 * @retval false Any hard failure: NULL @p dv_out, missing or unreadable ELF
 *               header block, unsupported architecture, an invalid dynamic
 *               range, or failure to read the @c .dynamic slice.
 */
static inline bool parse_dynamic_view(CarveInfo *candidate,
                                      uint64_t dyn_file_off,
                                      uint64_t dyn_size,
                                      DynamicView *dv_out){
    if (!candidate || !candidate->b || !dv_out) {
        return false;
    }
    memset(dv_out, 0, sizeof(*dv_out));

    int64_t eh_ap = blockvector_get_apparent_blocknumber(candidate->b, 0);
    if (eh_ap == -1) {
        return false;
    }
    uint8_t *eh = get_apparent_block_data(scalpel_state.filemirror, eh_ap);
    if (!eh) {
        return false;
    }
    bool is_64      = (eh[4] == ELF_64_BIT);
    bool file_is_le = (eh[5] == ELF_LITTLE_ENDIAN);
    uint16_t machine = get_elf_machine_type(eh, is_64, file_is_le);

    if (!(machine == EM_386 || machine == EM_X86_64 || machine == EM_ARM || machine == EM_AARCH64)) {
        free(eh);
        return false;
    }

    const uint64_t candidate_length =
        blockvector_get_data_length(candidate->b);
    if (dyn_size == 0 || dyn_size > SIZE_MAX
        || dyn_file_off > candidate_length
        || dyn_size > candidate_length - dyn_file_off) {
        free(eh);
        return false;
    }

    uint8_t *buf = (uint8_t *)malloc((size_t)dyn_size);
    if (!buf) {
        free(eh);
        return false;
    }
    if (!read_candidate_bytes(candidate, dyn_file_off, dyn_size, buf)) {
        free(buf);
        free(eh);
        return false;
    }

    uint64_t off = 0;
    if (is_64) {
        while (off + sizeof(Elf64_Dyn) <= dyn_size) {
            Elf64_Dyn d;
            memcpy(&d, buf + off, sizeof(d));
            uint64_t tag = to_host_endian_64((uint64_t)d.d_tag, file_is_le);
            uint64_t val = to_host_endian_64((uint64_t)d.d_un.d_val, file_is_le);
            off += sizeof(Elf64_Dyn);

            if (tag == DT_NULL) {
                break;
            }
            switch (tag) {
                case DT_RELA:      dv_out->has_rela = true; dv_out->rela_va = val; break;
                case DT_RELASZ:    dv_out->rela_sz = val; break;
                case DT_RELAENT:   dv_out->rela_ent = val; break;

                case DT_REL:       dv_out->has_rel = true;  dv_out->rel_va = val; break;
                case DT_RELSZ:     dv_out->rel_sz = val; break;
                case DT_RELENT:    dv_out->rel_ent = val; break;

                case DT_JMPREL:    dv_out->has_jmprel = true; dv_out->jmprel_va = val; break;
                case DT_PLTRELSZ:  dv_out->jmprel_sz = val; break;
                case DT_PLTREL:    dv_out->jmprel_is_rela = (val == DT_RELA); break;

                case DT_SYMTAB:    dv_out->has_symtab = true; dv_out->symtab_va = val; break;
                case DT_SYMENT:    dv_out->syment = val; break;

                case DT_STRTAB:    dv_out->has_strtab = true; dv_out->strtab_va = val; break;
                case DT_STRSZ:     dv_out->strsz = val; break;

                case DT_HASH:      dv_out->has_sysv_hash = true; dv_out->sysv_hash_va = val; break;
                case DT_GNU_HASH:  dv_out->has_gnu_hash  = true; dv_out->gnu_hash_va  = val; break;

                case DT_TEXTREL:   dv_out->textrel_present = true; break;

                default: break;
            }
        }
    } else {
        while (off + sizeof(Elf32_Dyn) <= dyn_size) {
            Elf32_Dyn d;
            memcpy(&d, buf + off, sizeof(d));
            uint32_t tag = to_host_endian_32((uint32_t)d.d_tag, file_is_le);
            uint32_t val = to_host_endian_32((uint32_t)d.d_un.d_val, file_is_le);
            off += sizeof(Elf32_Dyn);

            if (tag == DT_NULL) {
                break;
            }
            switch (tag) {
                case DT_RELA:      dv_out->has_rela = true; dv_out->rela_va = val; break;
                case DT_RELASZ:    dv_out->rela_sz = val; break;
                case DT_RELAENT:   dv_out->rela_ent = val; break;

                case DT_REL:       dv_out->has_rel = true;  dv_out->rel_va = val; break;
                case DT_RELSZ:     dv_out->rel_sz = val; break;
                case DT_RELENT:    dv_out->rel_ent = val; break;

                case DT_JMPREL:    dv_out->has_jmprel = true; dv_out->jmprel_va = val; break;
                case DT_PLTRELSZ:  dv_out->jmprel_sz = val; break;
                case DT_PLTREL:    dv_out->jmprel_is_rela = (val == DT_RELA); break;

                case DT_SYMTAB:    dv_out->has_symtab = true; dv_out->symtab_va = val; break;
                case DT_SYMENT:    dv_out->syment = val; break;

                case DT_STRTAB:    dv_out->has_strtab = true; dv_out->strtab_va = val; break;
                case DT_STRSZ:     dv_out->strsz = val; break;

                case DT_HASH:      dv_out->has_sysv_hash = true; dv_out->sysv_hash_va = val; break;
                case DT_GNU_HASH:  dv_out->has_gnu_hash  = true; dv_out->gnu_hash_va  = val; break;

                case DT_TEXTREL:   dv_out->textrel_present = true; break;

                default: break;
            }
        }
    }

    if (dv_out->has_sysv_hash) {
        uint64_t hash_fo = 0;
        if (map_va_to_file_off(candidate, dv_out->sysv_hash_va, &hash_fo)) {
            uint32_t words[2] = {0, 0};
            if (read_candidate_bytes(candidate, hash_fo, sizeof(words), (uint8_t *)words)) {
                if (!file_is_le) {
                    words[0] = __builtin_bswap32(words[0]);
                    words[1] = __builtin_bswap32(words[1]);
                }
                dv_out->dynsym_count_sysv = words[1];
            }
        }
    }
    if (dv_out->has_gnu_hash) {
        uint64_t gnu_fo = 0;
        if (map_va_to_file_off(candidate, dv_out->gnu_hash_va, &gnu_fo)) {
            uint32_t hdr[4] = {0,0,0,0};
            if (read_candidate_bytes(candidate, gnu_fo, sizeof(hdr), (uint8_t *)hdr)) {
                if (!file_is_le) {
                    hdr[0] = __builtin_bswap32(hdr[0]);
                    hdr[1] = __builtin_bswap32(hdr[1]);
                    hdr[2] = __builtin_bswap32(hdr[2]);
                    hdr[3] = __builtin_bswap32(hdr[3]);
                }
                dv_out->gnu_symoffset = hdr[1];
            }
        }
    }

    free(buf);
    free(eh);
    return true;
}



static inline bool is_dynamic_ptr_tag(uint64_t tag){
    /* Tags whose d_un is an address / virtual pointer that we can
     * optionally validate against PT_LOAD.
     *
     * This list can be extended (DT_INIT_ARRAY, DT_FINI_ARRAY, ...),
     * but this is a safe minimal set.
     */
    switch (tag) {
    case DT_PLTGOT:
    case DT_HASH:
    case DT_STRTAB:
    case DT_SYMTAB:
    case DT_RELA:
    case DT_REL:
    case DT_JMPREL:
    case DT_INIT:
    case DT_FINI:
    case DT_VERSYM:
    case DT_VERDEF:
    case DT_VERNEED:
    case DT_GNU_HASH:
        return true;
    default:
        return false;
    }
}

static inline bool is_dynamic_known_tag(uint64_t tag){
    /* We accept a broad set of common tags so we don't reject legit files.
     * Can be tightened
     */
    switch (tag) {
    case DT_NULL:
    case DT_NEEDED:
    case DT_PLTRELSZ:
    case DT_PLTGOT:
    case DT_HASH:
    case DT_STRTAB:
    case DT_SYMTAB:
    case DT_RELA:
    case DT_RELASZ:
    case DT_RELAENT:
    case DT_STRSZ:
    case DT_SYMENT:
    case DT_INIT:
    case DT_FINI:
    case DT_SONAME:
    case DT_RPATH:
    case DT_SYMBOLIC:
    case DT_REL:
    case DT_RELSZ:
    case DT_RELENT:
    case DT_PLTREL:
    case DT_DEBUG:
    case DT_TEXTREL:
    case DT_JMPREL:
    case DT_BIND_NOW:
    case DT_INIT_ARRAY:
    case DT_FINI_ARRAY:
    case DT_INIT_ARRAYSZ:
    case DT_FINI_ARRAYSZ:
    case DT_RUNPATH:
    case DT_FLAGS:
    case DT_PREINIT_ARRAY:
    case DT_PREINIT_ARRAYSZ:
    /* GNU / versioning */
    case DT_GNU_HASH:
    case DT_VERSYM:
    case DT_VERDEF:
    case DT_VERDEFNUM:
    case DT_VERNEED:
    case DT_VERNEEDNUM:
        return true;
    default:
        return false;
    }
}


/**
 * @brief Validate a single ELF dynamic table entry at a raw byte pointer.
 *
 * Performs a lightweight, per-entry structural check on one @c Elf{32,64}_Dyn
 * record. The check is intentionally minimal so that it can be called in a
 * tight sliding-window scan by @ref scan_for_valid_dynamic_entries without
 * incurring the cost of cross-referencing other tables.
 *
 * Validation rules applied in order:
 *   1. @c DT_NULL always passes — it is the standard @c .dynamic terminator.
 *   2. The tag must be recognised by @ref is_dynamic_known_tag; any unknown
 *      or reserved tag causes immediate rejection.
 *   3. If @p use_segments is true, tags identified as pointer-like by
 *      @ref is_dynamic_ptr_tag (e.g. @c DT_STRTAB, @c DT_SYMTAB,
 *      @c DT_JMPREL) must have their @c d_un.d_val fall within one of the
 *      supplied PT_LOAD ranges via @ref is_valid_virtual_address. Scalar
 *      tags (sizes, counts, flags) are accepted without an address check
 *      regardless of @p use_segments.
 *
 * @param[in] ptr          Pointer to the first byte of the candidate dynamic
 *                         entry. The caller must ensure that at least
 *                         @c sizeof(Elf64_Dyn) bytes are readable at this
 *                         address when @p is_64 is true, or at least
 *                         @c sizeof(Elf32_Dyn) bytes when @p is_64 is false.
 * @param[in] is_64        ELF class flag; true for 64-bit entries, false for
 *                         32-bit entries.
 * @param[in] file_is_le   File endianness flag; true if the ELF file is
 *                         little-endian.
 * @param[in] segs         Array of PT_LOAD segment descriptors used for
 *                         address containment checks. May be NULL if
 *                         @p use_segments is false.
 * @param[in] nsegs        Number of elements in @p segs.
 * @param[in] use_segments If true, pointer-like tags must resolve to an
 *                         address inside one of the segments in @p segs.
 *                         If false, address containment is not enforced and
 *                         @p segs / @p nsegs are ignored.
 *
 * @retval true  The entry is structurally acceptable: the tag is known (or
 *               @c DT_NULL), and any pointer-like value satisfies the
 *               optional PT_LOAD containment check.
 * @retval false The tag is unrecognised, or @p use_segments is true and a
 *               pointer-like tag's value does not fall within any PT_LOAD
 *               range.
 *
 * @note This function does not validate semantic relationships between tags
 *       (e.g. that @c DT_STRSZ is consistent with @c DT_STRTAB). Such checks
 *       are the responsibility of higher-level validators such as
 *       @ref validate_relocation_run_against_dynamic.
 */
static inline bool validate_one_dynamic_entry(const uint8_t *ptr,
                                                bool is_64,
                                                bool file_is_le,
                                                const SegmentInfo *segs,
                                                size_t nsegs,
                                                bool use_segments){
    uint64_t tag;
    uint64_t val;

    if (is_64) {
        Elf64_Dyn d;
        memcpy(&d, ptr, sizeof(d));
        tag = to_host_endian_64((uint64_t)d.d_tag, file_is_le);
        val = to_host_endian_64((uint64_t)d.d_un.d_val, file_is_le);
    } else {
        Elf32_Dyn d;
        memcpy(&d, ptr, sizeof(d));
        tag = (uint64_t)to_host_endian_32((uint32_t)d.d_tag, file_is_le);
        val = (uint64_t)to_host_endian_32((uint32_t)d.d_un.d_val, file_is_le);
    }

    /* DT_NULL is always fine – it's the terminator */
    if (tag == DT_NULL) {
        return true;
    }

    /* If it's a tag we don't even recognize, reject */
    if (!is_dynamic_known_tag(tag)) {
        return false;
    }

    /* If we want to enforce PT_LOAD containment, do it only for pointer-like tags */
    if (use_segments && is_dynamic_ptr_tag(tag)) {
        if (!is_valid_virtual_address(val, segs, nsegs)) {
            return false;
        }
    }

    /* All other (scalar) tags are fine */
    return true;
}



/**
 * @brief Scan a block-local component slice for a plausible @c .dynamic array.
 *
 * Searches the byte range [@p comp_offset, @p comp_offset + @p comp_size)
 * within @p block_data for the longest consecutive run of structurally valid
 * @c Elf{32,64}_Dyn entries, trying every possible byte alignment within a
 * single entry-size window. Each candidate entry is validated by
 * @ref validate_one_dynamic_entry. Runs that terminate with a @c DT_NULL
 * entry are preferred over longer runs that do not, since a well-formed
 * @c .dynamic array always ends with @c DT_NULL.
 *
 * Selection policy (in priority order):
 *   1. Prefer any run that encounters @c DT_NULL over all runs that do not,
 *      regardless of length.
 *   2. Among runs with equal @c DT_NULL status, prefer the longer run.
 *
 * Verdict policy:
 *   - @c VR_PASS         — a valid run was found and PT_LOAD containment was
 *                          enforced (@p use_segments was true).
 *   - @c VR_INCONCLUSIVE — a valid run was found but PT_LOAD containment was
 *                          not enforced; there is insufficient context to
 *                          fully validate or invalidate the result.
 *   - @c VR_FAIL         — no valid run was found, or slice bounds were
 *                          invalid.
 *
 * @param[in] block_data   Pointer to the start of the block buffer.
 * @param[in] block_size   Size of @p block_data in bytes.
 * @param[in] comp_offset  Byte offset within @p block_data where the
 *                         component slice begins.
 * @param[in] comp_size    Length in bytes of the component slice.
 * @param[in] is_64        ELF class flag; true for 64-bit entries, false for
 *                         32-bit entries.
 * @param[in] file_is_le   File endianness flag; true if the ELF file is
 *                         little-endian.
 * @param[in] segs         Optional array of PT_LOAD segment descriptors used
 *                         for pointer-tag address containment checks. May be
 *                         NULL if @p use_segments is false.
 * @param[in] nsegs        Number of elements in @p segs.
 * @param[in] use_segments If true, pointer-like @c DT_* tags must resolve to
 *                         an address inside one of @p segs, and a successful
 *                         result is reported as @c VR_PASS. If false, address
 *                         containment is not enforced and a successful result
 *                         is reported as @c VR_INCONCLUSIVE.
 *
 * @return A @ref DynamicScanResult describing the best run found:
 *   - @c start      — byte offset within the component slice where the run begins.
 *   - @c count      — number of consecutive valid entries in the run.
 *   - @c entry_size — size in bytes of each entry (@c sizeof(Elf{32,64}_Dyn)).
 *   - @c saw_dt_null — true if the run terminated with a @c DT_NULL entry.
 *   - @c span_bytes — total byte length of the run (@c count * @c entry_size).
 *   - @c result     — @c VR_PASS, @c VR_INCONCLUSIVE, or @c VR_FAIL.
 *
 * @note This function does not fetch the ELF header and does not attempt to
 *       semantically cross-check related tag pairs (e.g. @c DT_RELA against
 *       @c DT_RELASZ). Such checks are the responsibility of higher-level
 *       validators such as @ref validate_relocation_run_against_dynamic.
 */
static inline DynamicScanResult scan_for_valid_dynamic_entries(const uint8_t *block_data,
                                                            uint64_t block_size,
                                                            uint64_t comp_offset,
                                                            uint64_t comp_size,
                                                            bool     is_64,
                                                            bool     file_is_le,
                                                            const SegmentInfo *segs, size_t nsegs,
                                                            bool     use_segments){
    DynamicScanResult out = {0};
    out.result = VR_FAIL;

    /* bounds + overflow check */
    uint64_t end = 0;
    if (comp_offset > block_size ||
        __builtin_add_overflow(comp_offset, comp_size, &end) ||
        end > block_size) {
        return out;
    }

    const uint8_t *slice    = block_data + comp_offset;
    const uint64_t slice_sz = comp_size;

    const uint64_t esz = is_64 ? (uint64_t)sizeof(Elf64_Dyn)
                               : (uint64_t)sizeof(Elf32_Dyn);

    if (esz == 0 || slice_sz < esz) {
        return out;
    }

    uint64_t best_count   = 0;
    uint64_t best_start   = 0;
    bool     best_saw_null = false;

    /* try all alignments within a single entry-size window */
    const uint64_t limit = (slice_sz < esz) ? slice_sz : esz;
    for (uint64_t start = 0; start < limit; ++start) {
        uint64_t i     = start;
        uint64_t count = 0;
        bool     saw_null = false;

        while (i + esz <= slice_sz) {
            const uint8_t *p = slice + i;

            if (!validate_one_dynamic_entry(p,
                                            is_64,
                                            file_is_le,
                                            segs,
                                            nsegs,
                                            use_segments)) {
                break;
            }

            /* check if this entry was DT_NULL so we can prefer runs that terminate */
            uint64_t tag;
            if (is_64) {
                Elf64_Dyn d;
                memcpy(&d, p, sizeof(d));
                tag = to_host_endian_64((uint64_t)d.d_tag, file_is_le);
            } else {
                Elf32_Dyn d;
                memcpy(&d, p, sizeof(d));
                tag = (uint64_t)to_host_endian_32((uint32_t)d.d_tag, file_is_le);
            }
            if (tag == DT_NULL) {
                saw_null = true;
                count++;   /* count the DT_NULL itself */
                i += esz;
                break;     /* dynamic arrays normally stop here */
            }

            ++count;
            i += esz;
        }

        /* choose the best run:
         * 1) prefer runs that saw DT_NULL
         * 2) then prefer longer runs
         */
        if (saw_null) {
            if (!best_saw_null || count > best_count) {
                best_saw_null = true;
                best_count    = count;
                best_start    = start;
            }
        } else {
            if (!best_saw_null && count > best_count) {
                best_count = count;
                best_start = start;
            }
        }
    }

    if (best_count == 0) {
        return out;
    }

    out.start      = best_start;
    out.count      = best_count;
    out.entry_size = esz;
    out.saw_dt_null = best_saw_null;
    out.result     = use_segments ? VR_PASS : VR_INCONCLUSIVE;
    out.span_bytes = best_count * esz;
    return out;
}



/* ------------------------------------------------------------
 * Validation for Relocation Entries
 * ------------------------------------------------------------ */

static inline bool is_valid_x86_64_relocation_type(uint32_t t){
    // Include the newer CODE_4 and CODE_6 relocation forms.
    return (t <= R_X86_64_RELATIVE64) ||
           (t == R_X86_64_GOTPCRELX)  ||
           (t == R_X86_64_REX_GOTPCRELX) ||
           (t >= 43 && t <= 45) || t == 50;
}

static inline bool is_valid_x86_relocation_type(uint32_t t){
    return (t <= R_386_GOT32X);
}

// AAELF64 assigns different relocation codes to LP64 and the older ILP32 ABI.
// Reserved gaps must not make another architecture's records look valid.
static inline bool is_valid_arm64_relocation_type(uint32_t t, bool is_64){
    if (t == 0 || (t >= 0xe000 && t <= 0xffff)) {
        return true;
    }
    if (!is_64) {
        return (t >= 0x001 && t <= 0x01d)
               || (t >= 0x050 && t <= 0x07f)
               || (t >= 0x0b4 && t <= 0x0bc);
    }
    // Include both null encodings, static/TLS, PAuthABI and dynamic records.
    return (t >= 0x100 && t <= 0x118)
           || (t >= 0x11a && t <= 0x125)
           || (t >= 0x12b && t <= 0x13d)
           || (t >= 0x200 && t <= 0x23d)
           || (t >= 0x244 && t <= 0x256)
           || (t >= 0x400 && t <= 0x408)
           || (t >= 0x411 && t <= 0x414);
}

static inline bool is_valid_arm_relocation_type(uint32_t t){
    // AAELF32 defined/private ranges, plus legacy GNU relocation values.
    return t <= 138 || (t >= 160 && t <= 176)
           || (t >= 249 && t <= 255);
}

// MIPS relocation values occupy defined groups separated by reserved gaps.
static inline bool is_valid_mips_relocation_type(uint32_t t){
    return t <= 12 ||
           (t >= 16 && t <= 51) ||
           (t >= 60 && t <= 65) ||
           (t >= 100 && t <= 113) ||
           (t >= 126 && t <= 128) ||
           (t >= 133 && t <= 142) ||
           (t >= 145 && t <= 157) ||
           (t >= 162 && t <= 166) ||
           (t >= 169 && t <= 170) ||
           (t >= 172 && t <= 173) ||
           (t >= 248 && t <= 250) ||
           (t >= 253 && t <= 254);
}

static inline bool has_relocation_type_validator(uint16_t em){
    return em == EM_X86_64 || em == EM_386 || em == EM_AARCH64 ||
           em == EM_ARM || em == EM_MIPS || em == EM_MIPS_RS3_LE;
}

static inline bool is_valid_relocation_type_for_arch(uint32_t t, uint16_t em,
                                                     bool is_64){
    if (em == EM_X86_64){
        return is_valid_x86_64_relocation_type(t);
    }
    if (em == EM_386){
        return is_valid_x86_relocation_type(t);
    }
    if (em == EM_AARCH64){
        return is_valid_arm64_relocation_type(t, is_64);
    }
    if (em == EM_ARM){
        return is_valid_arm_relocation_type(t);
    }
    if (em == EM_MIPS || em == EM_MIPS_RS3_LE){
        return is_valid_mips_relocation_type(t);
    }
    return false;
}

static inline bool is_valid_relocation_info_for_arch(uint64_t info,
                                                      bool is_64,
                                                      uint16_t machine){
    if (is_64 && (machine == EM_MIPS || machine == EM_MIPS_RS3_LE)) {
        const uint32_t type1 = (uint32_t)(info & 0xffu);
        const uint32_t type2 = (uint32_t)((info >> 8) & 0xffu);
        const uint32_t type3 = (uint32_t)((info >> 16) & 0xffu);

        return is_valid_mips_relocation_type(type1) &&
               is_valid_mips_relocation_type(type2) &&
               is_valid_mips_relocation_type(type3);
    }

    const uint32_t type = is_64 ? ELF64_R_TYPE(info)
                                : ELF32_R_TYPE((uint32_t)info);
    return is_valid_relocation_type_for_arch(type, machine, is_64);
}



/**
 * @brief Validate a single ELF relocation entry at a raw byte pointer.
 *
 * Performs a lightweight, per-entry structural check on one @c Elf{32,64}_Rel
 * or @c Elf{32,64}_Rela record. The check is intentionally minimal so that it
 * can be called in a tight sliding-window scan by
 * @ref scan_for_valid_relocation_entries without incurring the cost of
 * cross-referencing symbol tables or @c .dynamic metadata.
 *
 * Validation rules applied in order:
 *   1. The relocation type extracted from @c r_info must be permitted for
 *      @p machine by @ref is_valid_relocation_type_for_arch. Unknown or
 *      reserved types cause immediate rejection.
 *   2. If @p use_segments is true, @c r_offset must fall within one of the
 *      supplied PT_LOAD ranges via @ref is_valid_virtual_address.
 *
 * @param[in] ptr          Pointer to the first byte of the candidate
 *                         relocation entry. The caller must ensure that
 *                         enough bytes are readable for the chosen
 *                         class/flavor combination:
 *                         @c sizeof(Elf64_Rela), @c sizeof(Elf64_Rel),
 *                         @c sizeof(Elf32_Rela), or @c sizeof(Elf32_Rel).
 * @param[in] is_64        ELF class flag; true for 64-bit entries, false for
 *                         32-bit entries.
 * @param[in] is_rela      Relocation flavor; true for RELA (explicit addend),
 *                         false for REL (implicit addend).
 * @param[in] file_is_le   File endianness flag; true if the ELF file is
 *                         little-endian.
 * @param[in] machine      @c e_machine value from the ELF header (e.g.
 *                         @c EM_X86_64, @c EM_AARCH64). Used to select the
 *                         architecture-specific relocation type allowlist.
 * @param[in] segs         Array of PT_LOAD segment descriptors used for
 *                         @c r_offset containment checks. May be NULL if
 *                         @p use_segments is false.
 * @param[in] nsegs        Number of elements in @p segs.
 * @param[in] use_segments If true, @c r_offset must fall within one of the
 *                         PT_LOAD ranges in @p segs. If false, address
 *                         containment is not enforced and @p segs /
 *                         @p nsegs are ignored.
 *
 * @retval true  The entry's relocation type is valid for @p machine, and
 *               @c r_offset satisfies the optional PT_LOAD containment check.
 * @retval false The relocation type is not permitted for @p machine, or
 *               @p use_segments is true and @c r_offset does not fall within
 *               any PT_LOAD range.
 *
 * @note Symbol indices and addend values are not validated here. Such checks
 *       are the responsibility of higher-level validators such as
 *       @ref validate_relocation_run_against_dynamic and
 *       @ref validate_reloc_run_against_sht.
 */
static inline bool validate_one_reloc_entry(const uint8_t *ptr,
                                            bool is_64,
                                            bool is_rela,
                                            bool file_is_le,
                                            uint16_t machine,
                                            const SegmentInfo *segs,
                                            size_t nsegs,
                                            bool use_segments){
    if (is_64) {
        if (is_rela) {
            Elf64_Rela entry;

            memcpy(&entry, ptr, sizeof(entry));
            uint64_t r_offset = to_host_endian_64(entry.r_offset, file_is_le);
            uint64_t r_info   = to_host_endian_64(entry.r_info,   file_is_le);
            if (!is_valid_relocation_info_for_arch(r_info, true, machine)) {
                return false;
            }
            if (use_segments && !is_valid_virtual_address(r_offset, segs, nsegs)) {
                return false;
            }
            return true;
        } else {
            Elf64_Rel entry;

            memcpy(&entry, ptr, sizeof(entry));
            uint64_t r_offset = to_host_endian_64(entry.r_offset, file_is_le);
            uint64_t r_info   = to_host_endian_64(entry.r_info,   file_is_le);
            if (!is_valid_relocation_info_for_arch(r_info, true, machine)) {
                return false;
            }
            if (use_segments && !is_valid_virtual_address(r_offset, segs, nsegs)) {
                return false;
            }
            return true;
        }
    } else {
        if (is_rela) {
            Elf32_Rela entry;

            memcpy(&entry, ptr, sizeof(entry));
            uint32_t r_offset = to_host_endian_32(entry.r_offset, file_is_le);
            uint32_t r_info   = to_host_endian_32(entry.r_info,   file_is_le);
            if (!is_valid_relocation_info_for_arch(r_info, false, machine)) {
                return false;
            }
            if (use_segments && !is_valid_virtual_address((uint64_t)r_offset, segs, nsegs)) {
                return false;
            }
            return true;
        } else {
            Elf32_Rel entry;

            memcpy(&entry, ptr, sizeof(entry));
            uint32_t r_offset = to_host_endian_32(entry.r_offset, file_is_le);
            uint32_t r_info   = to_host_endian_32(entry.r_info,   file_is_le);
            if (!is_valid_relocation_info_for_arch(r_info, false, machine)) {
                return false;
            }
            if (use_segments && !is_valid_virtual_address((uint64_t)r_offset, segs, nsegs)) {
                return false;
            }
            return true;
        }
    }
}



/**
 * @brief Scan a block-local component slice for valid ELF relocation entries.
 *
 * Searches the byte range [@p comp_offset, @p comp_offset + @p comp_size)
 * within @p block_data for the longest consecutive run of structurally valid
 * relocation entries. Both REL and RELA flavors are tried, and all byte
 * alignments within a single entry-size window are attempted for each flavor.
 * Each candidate entry is validated by @ref validate_one_reloc_entry. The
 * flavor and alignment combination that produces the longest valid run wins.
 *
 * This function does not fetch the ELF header, does not build PT_LOAD ranges,
 * and does not consult @c .dynamic — the caller must supply @p is_64,
 * @p file_is_le, @p machine, and optionally @p segs.
 *
 * Verdict policy:
 *   - @c VR_PASS         — a valid run was found with PT_LOAD containment
 *                          enforced; the result is backed by segment evidence.
 *   - @c VR_INCONCLUSIVE — a valid run was found but PT_LOAD containment was
 *                          not enforced; there is insufficient context to
 *                          fully validate or invalidate the result.
 *   - @c VR_FAIL         — no valid run was found, or the slice bounds were
 *                          invalid; the slice is definitively not a
 *                          well-formed relocation table.
 *
 * @param[in]  block_data   Pointer to the start of the block buffer.
 * @param[in]  block_size   Size of @p block_data in bytes.
 * @param[in]  comp_offset  Byte offset within @p block_data where the
 *                          component slice begins.
 * @param[in]  comp_size    Length in bytes of the component slice.
 * @param[in]  is_64        ELF class flag; true for 64-bit entries, false for
 *                          32-bit entries.
 * @param[in]  file_is_le   File endianness flag; true if the ELF file is
 *                          little-endian.
 * @param[in]  machine      @c e_machine value from the ELF header. Used to
 *                          select the architecture-specific relocation type
 *                          allowlist via @ref is_valid_relocation_type_for_arch.
 * @param[in]  segs         Optional array of PT_LOAD segment descriptors. May
 *                          be NULL if @p use_segments is false.
 * @param[in]  nsegs        Number of elements in @p segs.
 * @param[in]  use_segments If true, @c r_offset must fall within one of
 *                          @p segs for each entry, and a successful result is
 *                          reported as @c VR_PASS. If false, address
 *                          containment is not enforced and a successful result
 *                          is reported as @c VR_INCONCLUSIVE.
 *
 * @return A @ref RelocScanResult describing the best run found:
 *   - @c start      — byte offset within the component slice where the run begins.
 *   - @c count      — number of consecutive valid entries in the run.
 *   - @c entry_size — size in bytes of each entry for the winning flavor.
 *   - @c is_rela    — true if the winning flavor is RELA, false if REL.
 *   - @c span_bytes — total byte length of the run (@c count * @c entry_size).
 *   - @c result     — @c VR_PASS, @c VR_INCONCLUSIVE, or @c VR_FAIL.
 *
 * @note Symbol indices, addends, and cross-references to @c .dynamic or the
 *       SHT are not checked here. Use @ref validate_relocation_run_against_dynamic
 *       and @ref validate_reloc_run_against_sht for deeper validation once a
 *       run has been identified.
 */
static inline RelocScanResult scan_for_valid_relocation_entries(const uint8_t *block_data,
                                                        uint64_t block_size,
                                                        uint64_t comp_offset,
                                                        uint64_t comp_size,
                                                        bool     is_64,
                                                        bool     file_is_le,
                                                        uint16_t machine,
                                                        const SegmentInfo *segs, size_t nsegs,
                                                        bool     use_segments)
{
    RelocScanResult out = (RelocScanResult){0};
    out.result = VR_FAIL;

    /* Slice bounds + overflow guard */
    uint64_t end = 0;
    if (comp_offset > block_size ||
        __builtin_add_overflow(comp_offset, comp_size, &end) ||
        end > block_size) {
        return out;
    }

    const uint8_t *slice     = block_data + comp_offset;
    const uint64_t slice_sz  = comp_size;

    /* Relocation flavors and per-class entry sizes */
    typedef struct {
        bool     is_rela;   /* false = REL, true = RELA */
        uint64_t esize32;   /* entry size for ELF32 */
        uint64_t esize64;   /* entry size for ELF64 */
    } RelocFlavor;

    static const RelocFlavor kFlavors[] = {
        { false, sizeof(Elf32_Rel),  sizeof(Elf64_Rel)  }, /* REL  */
        { true,  sizeof(Elf32_Rela), sizeof(Elf64_Rela) }  /* RELA */
    };

    uint64_t best_count   = 0;
    bool     best_is_rela = false;
    uint64_t best_start   = 0;
    uint64_t best_esz     = 0;

    /* Try both flavors; for each, try all byte alignments within one entry-size window */
    for (size_t f = 0; f < (sizeof(kFlavors) / sizeof(kFlavors[0])); ++f) {
        const bool     scan_rela = kFlavors[f].is_rela;
        const uint64_t esz       = is_64 ? (uint64_t)kFlavors[f].esize64
                                         : (uint64_t)kFlavors[f].esize32;

        if (esz == 0) continue;
        const uint64_t limit = (slice_sz < esz) ? slice_sz : esz;

        for (uint64_t start = 0; start < limit; ++start) {
            uint64_t i = start;
            uint64_t count = 0;

            while (i + esz <= slice_sz) {
                const uint8_t *p = slice + i;

                if (!validate_one_reloc_entry(p,
                                              is_64,
                                              scan_rela,
                                              file_is_le,
                                              machine,
                                              segs,
                                              nsegs,
                                              use_segments)) {
                    break;
                }
                ++count;
                i += esz;
            }

            if (count > best_count) {
                best_count   = count;
                best_is_rela = scan_rela;
                best_start   = start;
                best_esz     = esz;
            }
        }
    }

    if (best_count == 0) {
        return out; /* no sustained run found */
    }

    out.is_rela     = best_is_rela;
    out.start       = best_start;
    out.count       = best_count;
    out.entry_size  = best_esz;
    out.result      = use_segments ? VR_PASS : VR_INCONCLUSIVE;
    out.span_bytes  = best_count * best_esz;
    return out;
}



/**
 * @brief Cross-validate a known relocation run against @c .dynamic semantics.
 *
 * Given a relocation run already identified by a structural scanner, this
 * function verifies that the run is consistent with the metadata advertised
 * in the candidate's @c .dynamic section. It does not rescan or re-parse
 * entries; it operates purely on the run boundaries and per-entry field values.
 *
 * The following checks are applied in order:
 *   1. Both @p use_segments and @p dv must be non-NULL; otherwise the
 *      necessary anchors are absent and the result is @c VR_INCONCLUSIVE.
 *   2. The run's file range [@p abs_file_off, @p abs_file_off + @p abs_file_len)
 *      is mapped to a VA range via PT_LOAD. If the mapping fails despite PT_LOAD
 *      being present, the result is @c VR_FAIL (contradiction).
 *   3. The run's VA range must fall within exactly one @c .dynamic relocation
 *      window (@c DT_RELA, @c DT_REL, or @c DT_JMPREL). Zero or multiple
 *      matches are rejected as @c VR_FAIL.
 *   4. The relocation flavor (REL vs RELA) must match what the enclosing
 *      window requires. For @c DT_JMPREL the flavor is taken from
 *      @c DT_PLTREL.
 *   5. If the window advertises an entry size (@c DT_RELAENT / @c DT_RELENT),
 *      @p entry_size must match.
 *   6. If the run falls in the PLT window (@c DT_JMPREL), every entry's
 *      relocation type must be the architecture-specific JUMP_SLOT type
 *      (@c R_X86_64_JUMP_SLOT, @c R_386_JMP_SLOT, @c R_AARCH64_JUMP_SLOT,
 *      or @c R_ARM_JUMP_SLOT).
 *   7. If @c dynsym_count_sysv is known from the SysV hash header, every
 *      entry's symbol index (@c r_sym) must be strictly less than that count.
 *
 * Verdict policy:
 *   - @c VR_PASS         — all checks passed with both anchors present.
 *   - @c VR_INCONCLUSIVE — required anchors (@p use_segments or @p dv) are
 *                          absent; cannot validate or invalidate.
 *   - @c VR_FAIL         — a contradiction was detected (mapping failure,
 *                          window mismatch, flavor/entsize mismatch, invalid
 *                          PLT type, or out-of-bounds symbol index).
 *
 * @param[in] slice_base   Pointer to the base of the component slice containing
 *                         the run (i.e. @c block_data + @c comp_offset).
 * @param[in] run_start    Byte offset within @p slice_base where the run begins.
 * @param[in] run_count    Number of relocation entries in the run.
 * @param[in] entry_size   Size in bytes of each entry.
 * @param[in] run_is_rela  True if the run is RELA (explicit addend), false if REL.
 * @param[in] is_64        ELF class flag; true for 64-bit, false for 32-bit.
 * @param[in] file_is_le   File endianness flag; true if little-endian.
 * @param[in] machine      @c e_machine from the ELF header; used for the
 *                         PLT-only type check.
 * @param[in] abs_file_off Absolute file offset of the first byte of the run.
 * @param[in] abs_file_len Total byte length of the run (@p run_count *
 *                         @p entry_size).
 * @param[in] candidate    Carving/reassembly context used for VA mapping.
 * @param[in] segs         PT_LOAD segment map used for VA mapping.
 * @param[in] nsegs        Number of elements in @p segs.
 * @param[in] use_segments Must be true for validation to proceed; if false
 *                         the function returns @c VR_INCONCLUSIVE immediately.
 * @param[in] dv           Parsed @c .dynamic view; if NULL the function returns
 *                         @c VR_INCONCLUSIVE immediately.
 *
 * @retval VR_PASS         All @c .dynamic constraints satisfied.
 * @retval VR_INCONCLUSIVE Required anchors absent; result is indeterminate.
 * @retval VR_FAIL         A structural or semantic contradiction was detected.
 */
static inline ValidateResult
validate_relocation_run_against_dynamic(const uint8_t *slice_base,
                                        uint64_t      run_start,
                                        uint64_t      run_count,
                                        uint64_t      entry_size,
                                        bool          run_is_rela,
                                        bool          is_64,
                                        bool          file_is_le,
                                        uint16_t      machine,
                                        uint64_t      abs_file_off,
                                        uint64_t      abs_file_len,
                                        CarveInfo    *candidate,
                                        const SegmentInfo *segs,
                                        size_t        nsegs,
                                        bool          use_segments,
                                        const DynamicView *dv){

    /* If either anchor is missing, we can’t validate against .dynamic here. */
    if (!use_segments || !dv) {
        return VR_INCONCLUSIVE;
    }

    /* Map the exact run [FO,len) to [VA0,VA1). PHT is required at this point. */
    uint64_t va0 = 0, va1 = 0;
    if (!map_file_range_to_va(candidate, abs_file_off, abs_file_len, &va0, &va1)) {
        /* PHT placed but mapping failed => contradiction. */
        return VR_FAIL;
    }

    /* Determine which .dynamic window this run lies in (must be exactly one). */
    bool in_rela = (dv->has_rela    && va0 >= dv->rela_va    && va1 <= (dv->rela_va    + dv->rela_sz));
    bool in_rel  = (dv->has_rel     && va0 >= dv->rel_va     && va1 <= (dv->rel_va     + dv->rel_sz));
    bool in_jmp  = (dv->has_jmprel  && va0 >= dv->jmprel_va  && va1 <= (dv->jmprel_va  + dv->jmprel_sz));

    int hits = (in_rela?1:0) + (in_rel?1:0) + (in_jmp?1:0);
    if (hits != 1) {
        /* None or multiple windows -> inconsistent with .dynamic. */
        return VR_FAIL;
    }

    /* Expected flavor from the window. */
    bool want_rela = in_rela ? true : (in_rel ? false : dv->jmprel_is_rela);
    if (run_is_rela != want_rela) {
        return VR_FAIL;
    }

    /* Enforce DT_*ENT if provided (JMPREL uses RELENT/RELAENT per flavor). */
    uint64_t expect_ent = 0;
    if (in_rela){
        expect_ent = dv->rela_ent;
    }else if (in_rel){
        expect_ent = dv->rel_ent;
    }else{
        expect_ent = want_rela ? dv->rela_ent : dv->rel_ent;
    }

    if (expect_ent && entry_size != expect_ent) {
        return VR_FAIL;
    }

    /* If we’re in the PLT window (JMPREL), enforce PLT-only relocation types. */
    if (in_jmp) {
        for (uint64_t k = 0; k < run_count; ++k) {
            const uint8_t *p = slice_base + run_start + k * entry_size;
            uint64_t r_info = 0;
            if (is_64) {
                if (want_rela){
                    Elf64_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_64(entry.r_info, file_is_le);
                }else{
                    Elf64_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_64(entry.r_info, file_is_le);
                }
            } else {
                if (want_rela){
                    Elf32_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_32(entry.r_info, file_is_le);
                }else{
                    Elf32_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_32(entry.r_info, file_is_le);
                }
            }
            uint32_t type = is_64 ? ELF64_R_TYPE(r_info) : ELF32_R_TYPE((uint32_t)r_info);

            bool plt_ok = false;
            switch (machine) {
                case EM_X86_64:  plt_ok = (type == R_X86_64_JUMP_SLOT);  break;
                case EM_386:     plt_ok = (type == R_386_JMP_SLOT);      break;
                case EM_AARCH64: plt_ok = (type == R_AARCH64_JUMP_SLOT); break;
                case EM_ARM:     plt_ok = (type == R_ARM_JUMP_SLOT);     break;
                default:         plt_ok = false;                         break;
            }
            if (!plt_ok) return VR_FAIL;
        }
    }

    // symbol index bounds using SysV hash (hard upper bound only)
    if (dv->dynsym_count_sysv) {
        for (uint64_t k = 0; k < run_count; ++k) {
            const uint8_t *p = slice_base + run_start + k * entry_size;
            uint64_t r_info = 0;

            if (is_64) {
                if (run_is_rela) {
                    Elf64_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_64(entry.r_info, file_is_le);
                }
                else {
                    Elf64_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_64(entry.r_info, file_is_le);
                }
            } else {
                if (run_is_rela) {
                    Elf32_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_32(entry.r_info, file_is_le);
                }
                else {
                    Elf32_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_info = to_host_endian_32(entry.r_info, file_is_le);
                }
            }

            uint64_t r_sym = is_64
                ? (uint64_t)ELF64_R_SYM(r_info)
                : (uint64_t)ELF32_R_SYM((uint32_t)r_info);

            /* Hard upper bound: reloc may never point past dynsym. */
            if (r_sym >= dv->dynsym_count_sysv) {
                return VR_FAIL;
            }
        }
    }

    /* All dynamic constraints satisfied with anchors available; PASS. */
    return VR_PASS;
}



/**
 * @brief Cross-validate a known relocation run against the Section Header Table.
 *
 * Given a relocation run already identified by a structural scanner, this
 * function verifies that the run is consistent with the SHT and the section
 * it claims to relocate. It does not rescan or re-parse entries; it operates
 * on the run boundaries and per-entry @c r_offset values.
 *
 * The following checks are applied in order:
 *   1. The run's file range is mapped to a VA range via PT_LOAD. If the
 *      mapping fails, the result is @c VR_INCONCLUSIVE (PT_LOAD may not yet
 *      be placed).
 *   2. The ELF header is read to locate the SHT (@c e_shoff, @c e_shnum,
 *      @c e_shentsize). If the SHT is absent or unreadable the result is
 *      @c VR_INCONCLUSIVE.
 *   3. Every @c SHT_REL / @c SHT_RELA section whose flavor matches
 *      @p run_is_rela is considered as a candidate host section:
 *        a. @c sh_entsize must match @p entry_size (if non-zero).
 *        b. The run must fit within @c sh_size.
 *        c. The target section is identified via @c sh_info and its VA range
 *           is derived from its @c sh_addr via @ref section_to_va_range.
 *        d. Every entry's @c r_offset must fall within the target section's
 *           VA range.
 *   4. If any candidate host section satisfies all of the above, the result
 *      is @c VR_PASS. If no candidate satisfies all checks the result is
 *      @c VR_FAIL.
 *
 * Verdict policy:
 *   - @c VR_PASS         — the run is consistent with at least one SHT
 *                          relocation section and its target section.
 *   - @c VR_INCONCLUSIVE — required anchors are absent (PT_LOAD mapping
 *                          failed, or SHT is not available or unreadable).
 *   - @c VR_FAIL         — no SHT relocation section is consistent with the
 *                          run; the run is definitively contradicted by the
 *                          SHT.
 *
 * @param[in] slice_base   Pointer to the base of the component slice containing
 *                         the run (i.e. @c block_data + @c comp_offset).
 * @param[in] run_start    Byte offset within @p slice_base where the run begins.
 * @param[in] run_count    Number of relocation entries in the run.
 * @param[in] entry_size   Size in bytes of each entry.
 * @param[in] run_is_rela  True if the run is RELA (explicit addend), false if REL.
 * @param[in] is_64        ELF class flag; true for 64-bit, false for 32-bit.
 * @param[in] file_is_le   File endianness flag; true if little-endian.
 * @param[in] abs_file_off Absolute file offset of the first byte of the run.
 * @param[in] abs_file_len Total byte length of the run (@p run_count *
 *                         @p entry_size).
 * @param[in] candidate    Carving/reassembly context used for reading the ELF
 *                         header, SHT entries, and VA mapping.
 * @param[in] segs         PT_LOAD segment map used for VA mapping and target
 *                         section VA range derivation.
 * @param[in] nsegs        Number of elements in @p segs.
 *
 * @retval VR_PASS         The run is consistent with at least one SHT section.
 * @retval VR_INCONCLUSIVE Required anchors absent; result is indeterminate.
 * @retval VR_FAIL         No SHT section is consistent with the run.
 */
static inline ValidateResult
validate_reloc_run_against_sht(const uint8_t  *slice_base,
                               uint64_t        run_start,
                               uint64_t        run_count,
                               uint64_t        entry_size,
                               bool            run_is_rela,
                               bool            is_64,
                               bool            file_is_le,
                               uint64_t        abs_file_off,
                               uint64_t        abs_file_len,
                               CarveInfo      *candidate,
                               const SegmentInfo *segs,
                               size_t          nsegs){
    /* 0) map the run to VA */
    uint64_t run_va0 = 0, run_va1 = 0;
    if (!map_file_range_to_va(candidate, abs_file_off, abs_file_len, &run_va0, &run_va1)) {
        return VR_INCONCLUSIVE;
    }

    /* 1) read ELF header */
    uint16_t shnum;
    uint64_t shoff;
    uint16_t shentsize;

    if (is_64) {
        Elf_Header_64 eh;
        if (!read_candidate_elf_header_64(candidate, &eh)) {
            return VR_INCONCLUSIVE;
        }
        shnum     = to_host_endian_16(eh.num_sht_entries, file_is_le);
        shoff     = to_host_endian_64(eh.sht_off,         file_is_le);
        shentsize = to_host_endian_16(eh.sht_entry_size,  file_is_le);
    } else {
        Elf_Header_32 eh;
        if (!read_candidate_elf_header_32(candidate, &eh)) {
            return VR_INCONCLUSIVE;
        }
        shnum     = to_host_endian_16(eh.num_sht_entries, file_is_le);
        shoff     = (uint64_t)to_host_endian_32(eh.sht_off, file_is_le);
        shentsize = to_host_endian_16(eh.sht_entry_size,  file_is_le);
    }

    if (shoff == 0 || shnum == 0 || shentsize == 0) {
        return VR_INCONCLUSIVE;
    }

    /* 2) walk SHT */
    for (uint16_t i = 0; i < shnum; ++i) {
        Section_Header_Entry_64 sh;
        if (!get_sht_entry(candidate, i, is_64, file_is_le, &sh)) {
            continue;
        }

        /* filter by type + flavor */
        uint32_t shtype = sh.section_type;
        if (run_is_rela) {
            if (shtype != SHT_RELA) continue;
        } else {
            if (shtype != SHT_REL)  continue;
        }

        /* entsize check */
        if (sh.entry_size && sh.entry_size != entry_size) {
            continue;
        }

        /* size check */
        if (run_count * entry_size > sh.sect_size) {
            continue;
        }

        /* target section via sh_info */
        if (sh.sect_info >= shnum) {
            continue;
        }

        Section_Header_Entry_64 tgt;
        if (!get_sht_entry(candidate, (uint16_t)sh.sect_info, is_64, file_is_le, &tgt)) {
            continue;
        }

        /* target VA range */
        uint64_t tgt_va0 = 0, tgt_va1 = 0;
        if (!section_to_va_range(&tgt, segs, nsegs, &tgt_va0, &tgt_va1)) {
            continue;
        }

        /* 3) per-reloc check */
        bool all_ok = true;
        for (uint64_t k = 0; k < run_count; ++k) {
            const uint8_t *p = slice_base + run_start + k * entry_size;
            uint64_t r_off;

            if (is_64) {
                if (run_is_rela) {
                    Elf64_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_off = to_host_endian_64(entry.r_offset, file_is_le);
                } else {
                    Elf64_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_off = to_host_endian_64(entry.r_offset, file_is_le);
                }
            } else {
                if (run_is_rela) {
                    Elf32_Rela entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_off = (uint64_t)to_host_endian_32(entry.r_offset, file_is_le);
                } else {
                    Elf32_Rel entry;

                    memcpy(&entry, p, sizeof(entry));
                    r_off = (uint64_t)to_host_endian_32(entry.r_offset, file_is_le);
                }
            }

            if (r_off < tgt_va0 || r_off >= tgt_va1) {
                all_ok = false;
                break;
            }
        }

        if (all_ok) {
            return VR_PASS;
        }
    }

    return VR_FAIL;
}



/* ------------------------------------------------------------
 * Validation for Symbol Entries
 * ------------------------------------------------------------ */

static inline bool is_valid_symbol_type(uint8_t st_info){
    uint8_t st_type = (uint8_t)(st_info & 0x0Fu);
    return (st_type >= STT_NOTYPE && st_type <= STT_TLS);
}

static inline bool is_valid_symbol_binding(uint8_t st_info){
    uint8_t st_binding = (uint8_t)(st_info >> 4);
    return (st_binding >= STB_LOCAL && st_binding <= STB_WEAK);
}

static inline bool is_valid_symbol_visibility(uint8_t st_other) {
    /* ELF: visibility is in low 2 bits: 0..3; upper bits must be zero. */
    uint8_t vis = (uint8_t)(st_other & 0x3u);
    return (st_other == vis);
}

static inline bool is_all_zero_sym64(const Elf64_Sym *s) {
    return s->st_name  == 0 &&
           s->st_info  == 0 &&
           s->st_other == 0 &&
           s->st_shndx == 0 &&
           s->st_value == 0 &&
           s->st_size  == 0;
}

static inline bool is_all_zero_sym32(const Elf32_Sym *s) {
    return s->st_name  == 0 &&
           s->st_info  == 0 &&
           s->st_other == 0 &&
           s->st_shndx == 0 &&
           s->st_value == 0 &&
           s->st_size  == 0;
}


/**
 * @brief Validate a single ELF symbol table entry at a raw byte pointer.
 *
 * Performs a lightweight, per-entry structural check on one @c Elf{32,64}_Sym
 * record. The check is intentionally minimal so that it can be called in a
 * tight sliding-window scan by @ref scan_for_valid_symbol_entries without
 * incurring the cost of cross-referencing string tables or @c .dynamic metadata.
 *
 * Validation rules applied in order:
 *   1. An all-zero entry is accepted unconditionally as the conventional null
 *      symbol (index 0 in both @c .symtab and @c .dynsym). @p *is_zero_entry
 *      is set to true in this case.
 *   2. The symbol type extracted from @c st_info must be valid per
 *      @ref is_valid_symbol_type.
 *   3. The symbol binding extracted from @c st_info must be valid per
 *      @ref is_valid_symbol_binding.
 *   4. The symbol visibility in @c st_other must be valid per
 *      @ref is_valid_symbol_visibility; the upper bits of @c st_other must
 *      be zero.
 *   5. If @p use_segments is true, defined symbols with a non-zero @c st_value
 *      and a section index other than @c SHN_UNDEF, @c SHN_ABS, or
 *      @c SHN_COMMON must have their @c st_value fall within one of the
 *      supplied PT_LOAD ranges via @ref is_valid_virtual_address.
 *
 * @param[in]  ptr           Pointer to the first byte of the candidate symbol
 *                           entry. The caller must ensure that at least
 *                           @c sizeof(Elf64_Sym) bytes are readable when
 *                           @p is_64bit is true, or at least
 *                           @c sizeof(Elf32_Sym) bytes when false.
 * @param[in]  is_64bit      ELF class flag; true for 64-bit entries, false for
 *                           32-bit entries.
 * @param[in]  file_is_le    File endianness flag; true if the ELF file is
 *                           little-endian.
 * @param[in]  segs          Array of PT_LOAD segment descriptors used for
 *                           @c st_value containment checks. May be NULL if
 *                           @p use_segments is false.
 * @param[in]  nsegs         Number of elements in @p segs.
 * @param[in]  use_segments  If true, defined symbols with a non-zero
 *                           @c st_value must fall within one of @p segs.
 *                           If false, address containment is not enforced.
 * @param[out] is_zero_entry If non-NULL, set to true when the entry is the
 *                           all-zero null symbol, false otherwise.
 *
 * @retval true  The entry is structurally valid: type, binding, and visibility
 *               fields are well-formed, and any defined @c st_value satisfies
 *               the optional PT_LOAD containment check.
 * @retval false A field fails its structural predicate, or @p use_segments is
 *               true and a defined symbol's @c st_value does not fall within
 *               any PT_LOAD range.
 *
 * @note @c st_name offsets are not validated here; string table bounds
 *       checking is the responsibility of higher-level validators such as
 *       @ref validate_dynsym_run_against_dynamic and
 *       @ref validate_strtab_against_symtab.
 */
static inline bool validate_one_sym_entry(const uint8_t *ptr,
                                          bool is_64bit,
                                          bool file_is_le,
                                          const SegmentInfo *segs,
                                          size_t nsegs,
                                          bool use_segments,
                                          bool *is_zero_entry) {
    if (is_zero_entry) {
        *is_zero_entry = false;
    }

    if (is_64bit) {
        Elf64_Sym sym;

        memcpy(&sym, ptr, sizeof(sym));
        uint32_t st_name  = sym.st_name;
        uint8_t  st_info  = sym.st_info;
        uint8_t  st_other = sym.st_other;
        uint16_t st_shndx = sym.st_shndx;
        uint64_t st_value = sym.st_value;
        uint64_t st_size  = sym.st_size;

        if (!file_is_le) {
            st_name  = __builtin_bswap32(st_name);
            st_shndx = __builtin_bswap16(st_shndx);
            st_value = __builtin_bswap64(st_value);
            st_size  = __builtin_bswap64(st_size);
        }

        if (is_all_zero_sym64(&sym)) {
            if (is_zero_entry) {
                *is_zero_entry = true;
            }
            return true;
        }

        if (!is_valid_symbol_type(st_info)) {
            return false;
        }
        if (!is_valid_symbol_binding(st_info)) {
            return false;
        }
        if (!is_valid_symbol_visibility(st_other)) {
            return false;
        }

        if (use_segments &&
            st_value != 0 &&
            st_shndx != SHN_UNDEF &&
            st_shndx != SHN_ABS &&
            st_shndx != SHN_COMMON) {
            if (!is_valid_virtual_address(st_value, segs, nsegs)) {
                return false;
            }
        }

        return true;
    } else {
        Elf32_Sym sym;

        memcpy(&sym, ptr, sizeof(sym));
        uint32_t st_name  = sym.st_name;
        uint8_t  st_info  = sym.st_info;
        uint8_t  st_other = sym.st_other;
        uint16_t st_shndx = sym.st_shndx;
        uint32_t st_value = sym.st_value;
        uint32_t st_size  = sym.st_size;

        if (!file_is_le) {
            st_name  = __builtin_bswap32(st_name);
            st_shndx = __builtin_bswap16(st_shndx);
            st_value = __builtin_bswap32(st_value);
            st_size  = __builtin_bswap32(st_size);
        }

        if (is_all_zero_sym32(&sym)) {
            if (is_zero_entry) {
                *is_zero_entry = true;
            }
            return true;
        }

        if (!is_valid_symbol_type(st_info)) {
            return false;
        }
        if (!is_valid_symbol_binding(st_info)) {
            return false;
        }
        if (!is_valid_symbol_visibility(st_other)) {
            return false;
        }

        if (use_segments &&
            st_value != 0 &&
            st_shndx != SHN_UNDEF &&
            st_shndx != SHN_ABS &&
            st_shndx != SHN_COMMON) {
            if (!is_valid_virtual_address((uint64_t)st_value, segs, nsegs)) {
                return false;
            }
        }

        return true;
    }
}

/* ------------------------------------------------------------
 * Cross-validation + structural validation for symbol entries
 * ------------------------------------------------------------ */

/**
 * @brief Scan a block-local component slice for valid ELF symbol table entries.
 *
 * Searches the byte range [@p comp_offset, @p comp_offset + @p comp_size)
 * within @p block_data for the longest consecutive run of structurally valid
 * @c Elf{32,64}_Sym entries, trying every possible byte alignment within a
 * single entry-size window. Each candidate entry is validated by
 * @ref validate_one_sym_entry.
 *
 * At most one all-zero null symbol is permitted per run. A second all-zero
 * entry terminates the run immediately, since legitimate symbol tables contain
 * at most one null entry (at index 0).
 *
 * This function does not fetch the ELF header, does not build PT_LOAD ranges,
 * and does not consult @c .dynamic — the caller must supply @p is_64bit,
 * @p file_is_le, and optionally @p segs.
 *
 * Verdict policy:
 *   - @c VR_PASS         — a valid run was found with PT_LOAD containment
 *                          enforced; the result is backed by segment evidence.
 *   - @c VR_INCONCLUSIVE — a valid run was found but PT_LOAD containment was
 *                          not enforced; there is insufficient context to
 *                          fully validate or invalidate the result.
 *   - @c VR_FAIL         — no valid run was found, or the slice bounds were
 *                          invalid; the slice is definitively not a
 *                          well-formed symbol table.
 *
 * @param[in]  block_data   Pointer to the start of the block buffer.
 * @param[in]  block_size   Size of @p block_data in bytes.
 * @param[in]  comp_offset  Byte offset within @p block_data where the
 *                          component slice begins.
 * @param[in]  comp_size    Length in bytes of the component slice.
 * @param[in]  is_64bit     ELF class flag; true for 64-bit entries, false for
 *                          32-bit entries.
 * @param[in]  file_is_le   File endianness flag; true if the ELF file is
 *                          little-endian.
 * @param[in]  segs         Optional array of PT_LOAD segment descriptors. May
 *                          be NULL if @p use_segments is false.
 * @param[in]  nsegs        Number of elements in @p segs.
 * @param[in]  use_segments If true, defined symbols with a non-zero
 *                          @c st_value must fall within one of @p segs, and
 *                          a successful result is reported as @c VR_PASS.
 *                          If false, address containment is not enforced and
 *                          a successful result is reported as
 *                          @c VR_INCONCLUSIVE.
 *
 * @return A @ref SymbolScanResult describing the best run found:
 *   - @c start      — byte offset within the component slice where the run begins.
 *   - @c count      — number of consecutive valid entries in the run.
 *   - @c entry_size — size in bytes of each entry (@c sizeof(Elf{32,64}_Sym)).
 *   - @c span_bytes — total byte length of the run (@c count * @c entry_size).
 *   - @c result     — @c VR_PASS, @c VR_INCONCLUSIVE, or @c VR_FAIL.
 *
 * @note @c st_name offsets and string table bounds are not checked here. Use
 *       @ref validate_dynsym_run_against_dynamic or
 *       @ref validate_strtab_against_symtab for deeper validation once a run
 *       has been identified.
 */
static inline SymbolScanResult
scan_for_valid_symbol_entries(const uint8_t *block_data,
                                 uint64_t block_size,
                                 uint64_t comp_offset,
                                 uint64_t comp_size,
                                 bool     is_64bit,
                                 bool     file_is_le,
                                 const SegmentInfo *segs,
                                 size_t nsegs,
                                 bool     use_segments){

    SymbolScanResult out = (SymbolScanResult){0};
    out.result = VR_FAIL;

    /* Slice bounds + trivial guards */
    uint64_t end = 0;
    if (comp_offset > block_size ||
        __builtin_add_overflow(comp_offset, comp_size, &end) ||
        end > block_size) {
        return out;
    }

    const uint8_t *slice    = block_data + comp_offset;
    const uint64_t slice_sz = comp_size;

    const uint64_t esize = is_64bit ? (uint64_t)sizeof(Elf64_Sym)
                                    : (uint64_t)sizeof(Elf32_Sym);
    if (esize == 0 || slice_sz < esize) {
        return out; /* cannot hold even a single entry */
    }

    uint64_t best_run   = 0;
    uint64_t best_start = 0;

    /* Try all byte alignments within one entry-size window (or slice end) */
    const uint64_t limit = (slice_sz < esize) ? slice_sz : esize;
    for (uint64_t a = 0; a < limit; ++a) {
        uint64_t i = a;
        uint64_t run = 0;
        bool null_seen = false;

        while (i + esize <= slice_sz) {
            const uint8_t *p = slice + i;
            bool is_zero = false;

            if (!validate_one_sym_entry(p,
                                        is_64bit,
                                        file_is_le,
                                        segs,
                                        nsegs,
                                        use_segments,
                                        &is_zero)) {
                break;
            }

            if (is_zero) {
                if (null_seen) {
                    break; /* only one all-zero null symbol allowed per run */
                }
                null_seen = true;
            }

            ++run;
            i += esize;
        }

        if (run > best_run) {
            best_run   = run;
            best_start = a;
        }
    }

    if (best_run == 0) {
        return out; /* no sustained run found */
    }

    out.start      = best_start;
    out.count      = best_run;
    out.entry_size = esize;
    out.result     = use_segments ? VR_PASS : VR_INCONCLUSIVE;
    out.span_bytes = best_run * esize;
    return out;
}



/**
 * @brief Cross-validate a known @c .dynsym run against @c .dynamic semantics.
 *
 * Given a symbol table run already identified by a structural scanner, this
 * function verifies that the run is consistent with the metadata advertised
 * in the candidate's @c .dynamic section. It does not rescan or re-parse
 * entries; it operates on the run boundaries and per-entry field values.
 *
 * The following checks are applied in order:
 *   1. Both @p use_segments and @p dv must be present and @p dv must contain
 *      a @c DT_SYMTAB entry; otherwise the necessary anchors are absent and
 *      the result is @c VR_INCONCLUSIVE.
 *   2. The run's file range is mapped to a VA range via PT_LOAD. If the
 *      mapping fails despite PT_LOAD being present, the result is @c VR_FAIL
 *      (contradiction).
 *   3. If @c DT_SYMENT is present, @p entry_size must match.
 *   4. The run's VA start must be at or after @c DT_SYMTAB.
 *   5. If @c DT_SYMENT is present, the offset from @c DT_SYMTAB to the run
 *      start must be a multiple of the entry size (alignment check).
 *   6. If the symbol count is known from the SysV hash header
 *      (@c dynsym_count_sysv), the run must start inside the real @c .dynsym
 *      extent and must not extend more than one entry past its end.
 *   7. If @c DT_STRTAB and @c DT_STRSZ are present, every entry's @c st_name
 *      offset must be strictly less than @c DT_STRSZ.
 *   8. For every entry with a non-zero @c st_value and a non-special section
 *      index (@c SHN_UNDEF, @c SHN_ABS, @c SHN_COMMON), @c st_value must
 *      fall within a PT_LOAD range.
 *
 * Verdict policy:
 *   - @c VR_PASS         — all checks passed with both anchors present.
 *   - @c VR_INCONCLUSIVE — required anchors (@p use_segments, @p dv, or
 *                          @c DT_SYMTAB) are absent; cannot validate or
 *                          invalidate.
 *   - @c VR_FAIL         — a contradiction was detected (mapping failure,
 *                          entry size mismatch, alignment violation, VA range
 *                          containment failure, @c st_name out of bounds, or
 *                          @c st_value outside PT_LOAD).
 *
 * @param[in] slice_base   Pointer to the base of the component slice containing
 *                         the run (i.e. @c block_data + @c comp_offset).
 * @param[in] run_start    Byte offset within @p slice_base where the run begins.
 * @param[in] run_count    Number of symbol entries in the run.
 * @param[in] entry_size   Size in bytes of each entry.
 * @param[in] is_64        ELF class flag; true for 64-bit, false for 32-bit.
 * @param[in] file_is_le   File endianness flag; true if little-endian.
 * @param[in] abs_file_off Absolute file offset of the first byte of the run.
 * @param[in] abs_file_len Total byte length of the run (@p run_count *
 *                         @p entry_size).
 * @param[in] candidate    Carving/reassembly context used for VA mapping.
 * @param[in] segs         PT_LOAD segment map used for VA mapping and
 *                         @c st_value containment checks.
 * @param[in] nsegs        Number of elements in @p segs.
 * @param[in] use_segments Must be true for validation to proceed; if false
 *                         the function returns @c VR_INCONCLUSIVE immediately.
 * @param[in] dv           Parsed @c .dynamic view. If NULL, or if
 *                         @c has_symtab is false, the function returns
 *                         @c VR_INCONCLUSIVE immediately.
 *
 * @retval VR_PASS         All @c .dynamic constraints satisfied.
 * @retval VR_INCONCLUSIVE Required anchors absent; result is indeterminate.
 * @retval VR_FAIL         A structural or semantic contradiction was detected.
 */
static inline ValidateResult
validate_dynsym_run_against_dynamic(const uint8_t    *slice_base,
                                    uint64_t          run_start,
                                    uint64_t          run_count,
                                    uint64_t          entry_size,
                                    bool              is_64,
                                    bool              file_is_le,
                                    uint64_t          abs_file_off,
                                    uint64_t          abs_file_len,
                                    CarveInfo        *candidate,
                                    const SegmentInfo *segs,
                                    size_t            nsegs,
                                    bool              use_segments,
                                    const DynamicView *dv){

    /* Must have PHT (to map FO→VA) and a dynamic view with DT_SYMTAB info. */
    if (!use_segments || !dv || !dv->has_symtab) {
        return VR_INCONCLUSIVE;
    }

    /* Map the exact run to VA. */
    uint64_t va0 = 0, va1 = 0;
    if (!map_file_range_to_va(candidate, abs_file_off, abs_file_len, &va0, &va1)) {
        return VR_FAIL; /* PHT present but mapping failed */
    }

    /* Determine the expected entry size. */
    uint64_t expected_syment = dv->syment ? (uint64_t)dv->syment
                                          : entry_size; /* fall back to caller’s size */
    if (dv->syment && entry_size != expected_syment) {
        return VR_FAIL; /* DT_SYMENT disagrees with run */
    }

    /* The run must start at/after DT_SYMTAB. */
    if (va0 < dv->symtab_va) {
        return VR_FAIL;
    }

    /* Enforce alignment to DT_SYMENT when provided. */
    if (dv->syment && ((va0 - dv->symtab_va) % expected_syment) != 0) {
        return VR_FAIL;
    }

    /* If we know the symbol count from SysV hash, enforce sensible containment. */
    if (dv->dynsym_count_sysv > 0) {
        uint64_t dynsym_end = dv->symtab_va +
                            (uint64_t)dv->dynsym_count_sysv * expected_syment;

        /* must start inside the real dynsym */
        if (va0 < dv->symtab_va || va0 >= dynsym_end) {
            return VR_FAIL;
        }

        /* allow spill of at most 1 extra entry past the end */
        if (va1 > dynsym_end + expected_syment) {
            return VR_FAIL;
        }
    }

    /* If we can, also enforce string table bounds and value address sanity per entry. */
    if (dv->has_strtab && dv->strsz > 0) {
        for (uint64_t i = 0; i < run_count; ++i) {
            const uint8_t *p = slice_base + run_start + i * entry_size;

            if (is_64) {
                Elf64_Sym entry;

                memcpy(&entry, p, sizeof(entry));
                uint32_t st_name  = entry.st_name;
                uint16_t st_shndx = entry.st_shndx;
                uint64_t st_value = entry.st_value;
                if (!file_is_le) {
                    st_name  = __builtin_bswap32(st_name);
                    st_shndx = __builtin_bswap16(st_shndx);
                    st_value = __builtin_bswap64(st_value);
                }
                if ((uint64_t)st_name >= dv->strsz) {
                    return VR_FAIL;
                }
                if (st_value != 0 &&
                    st_shndx != SHN_UNDEF && st_shndx != SHN_ABS && st_shndx != SHN_COMMON) {
                    if (!is_valid_virtual_address(st_value, segs, nsegs)) {
                        return VR_FAIL;
                    }
                }
            } else {
                Elf32_Sym entry;

                memcpy(&entry, p, sizeof(entry));
                uint32_t st_name  = entry.st_name;
                uint16_t st_shndx = entry.st_shndx;
                uint32_t st_value = entry.st_value;
                if (!file_is_le) {
                    st_name  = __builtin_bswap32(st_name);
                    st_shndx = __builtin_bswap16(st_shndx);
                    st_value = __builtin_bswap32(st_value);
                }
                if ((uint64_t)st_name >= dv->strsz) {
                    return VR_FAIL;
                }
                if (st_value != 0 &&
                    st_shndx != SHN_UNDEF && st_shndx != SHN_ABS && st_shndx != SHN_COMMON) {
                    if (!is_valid_virtual_address((uint64_t)st_value, segs, nsegs)) {
                        return VR_FAIL;
                    }
                }
            }
        }
    }

    return VR_PASS;
}



/* ------------------------------------------------------------
 * Validate string tables against symbol tables
 * ------------------------------------------------------------ */

 /**
 * @brief Validates a string table section against its associated symbol table.
 *
 * Walks every symbol entry in the given symbol table section and verifies that
 * each non-zero @c st_name offset refers to a valid, NUL-terminated string
 * that lies entirely within the bounds of the associated string table section.
 *
 * @param[in] cand       Pointer to the candidate carve-info context used for
 *                       raw byte reads.
 * @param[in] sym_sh     Section header entry describing the symbol table
 *                       (@c SHT_SYMTAB or @c SHT_DYNSYM).
 * @param[in] str_sh     Section header entry describing the associated string
 *                       table (@c SHT_STRTAB).
 * @param[in] is_64      @c true if the ELF file uses the 64-bit symbol format
 *                       (@c Elf64_Sym); @c false for 32-bit (@c Elf32_Sym).
 * @param[in] file_is_le @c true if the ELF file is little-endian; @c false for
 *                       big-endian. Used when interpreting @c st_name fields.
 *
 * @retval VR_PASS        All symbol name offsets are within bounds and each
 *                        referenced string is properly NUL-terminated.
 * @retval VR_FAIL        A structural problem was detected: the string table is
 *                        empty, the derived entry size is zero, a symbol's
 *                        @c st_name offset is out of range, or a referenced
 *                        string is not NUL-terminated within the string table.
 * @retval VR_INCONCLUSIVE A byte-read operation on the candidate image failed,
 *                        preventing a definitive determination.
 *
 * @note If @c sym_sh->entry_size is zero the function falls back to
 *       @c sizeof(Elf64_Sym) or @c sizeof(Elf32_Sym) according to @p is_64.
 * @note Symbol entries whose @c st_name is @c 0 are silently skipped, as the
 *       ELF specification reserves index 0 for the empty string.
 */
static inline ValidateResult
validate_strtab_against_symtab(CarveInfo                      *cand,
                               const Section_Header_Entry_64  *sym_sh,
                               const Section_Header_Entry_64  *str_sh,
                               bool                            is_64,
                               bool                            file_is_le){
    /* 1) strtab bounds */
    uint64_t str_off  = str_sh->sect_file_off;
    uint64_t str_size = str_sh->sect_size;
    if (str_size == 0) {
        return VR_FAIL;
    }

    /* 2) symtab bounds */
    uint64_t sym_off  = sym_sh->sect_file_off;
    uint64_t sym_size = sym_sh->sect_size;
    uint64_t entsize  = sym_sh->entry_size
                        ? sym_sh->entry_size
                        : (is_64 ? (uint64_t)sizeof(Elf64_Sym)
                                 : (uint64_t)sizeof(Elf32_Sym));

    if (entsize == 0) {
        return VR_FAIL;
    }

    /* walk all symbols in this section */
    for (uint64_t off = 0; off + entsize <= sym_size; off += entsize) {
        uint8_t buf[sizeof(Elf64_Sym)];
        if (!read_candidate_bytes(cand, sym_off + off, entsize, buf)) {
            return VR_INCONCLUSIVE;
        }

        uint32_t st_name;
        if (is_64) {
            Elf64_Sym entry;

            memcpy(&entry, buf, sizeof(entry));
            st_name = to_host_endian_32(entry.st_name, file_is_le);
        } else {
            Elf32_Sym entry;

            memcpy(&entry, buf, sizeof(entry));
            st_name = to_host_endian_32(entry.st_name, file_is_le);
        }

        if (st_name == 0) {
            continue; /* empty name is fine */
        }

        /* name offset must be inside strtab */
        if ((uint64_t)st_name >= str_size) {
            return VR_FAIL;
        }

        /* ensure NUL-termination within the strtab slice */
        uint64_t name_pos = str_off + (uint64_t)st_name;
        bool saw_nul = false;
        for (uint64_t k = 0; k < str_size - st_name; ++k) {
            uint8_t c;
            if (!read_candidate_bytes(cand, name_pos + k, 1, &c)) {
                return VR_INCONCLUSIVE;
            }
            if (c == 0) {
                saw_nul = true;
                break;
            }
        }
        if (!saw_nul) {
            return VR_FAIL;
        }
    }

    return VR_PASS;
}



/* ------------------------------------------------------------
 * Segment Validation Helpers
 * ------------------------------------------------------------ */

/**
 * @brief Decide if a section type is legal for a given PT_* segment type.
 *
 * This is a policy helper used during block placement to reject obviously
 * incompatible (section, segment) pairs. It is intentionally strict for
 * segments with very specific payloads (e.g., PT_DYNAMIC, PT_GNU_EH_FRAME)
 * and permissive for segments that either have no file payload or vary widely
 * across toolchains (e.g., PT_NOTE, PT_GNU_STACK, PT_GNU_RELRO).
 *
 * Policy summary:
 *   - PT_LOAD         → all section types permitted (file-backed content)
 *   - PT_DYNAMIC      → only @c SECTION_DYNAMIC
 *   - PT_GNU_EH_FRAME → @c SECTION_EH_FRAME or @c SECTION_EH_FRAME_HEADER
 *   - PT_INTERP       → @c SECTION_STRING or @c SECTION_UNKNOWN
 *   - PT_NOTE         → permissive (heterogeneous payload)
 *   - PT_PHDR         → permissive (image of the PHT itself)
 *   - PT_TLS          → permissive (file-backed template data)
 *   - PT_GNU_RELRO    → permissive (overlaps PT_LOAD; no independent type constraint)
 *   - PT_GNU_STACK    → permissive (typically @c filesz == 0)
 *   - unknown types   → permissive (minimize false negatives)
 *
 * @param[in] section_type  The model's section classification (@c SECTION_*).
 * @param[in] segment_type  A @c PT_* program header type (e.g., @c PT_LOAD).
 * @return @c true if the section is considered compatible with the segment type,
 *         @c false if the pair is considered structurally invalid.
 *
 * @note This is not an ELF spec validator; it is a practical filter tuned to
 *       minimize false negatives during fragmented binary reassembly.
 */
static inline bool is_section_compatible_with_segment(SectionDataType section_type,
                                                      uint32_t segment_type)
{
    switch (segment_type) {
        case PT_LOAD: {
            /* Any file-backed section content is generally fine in PT_LOAD. */
            return true;
        }

        case PT_DYNAMIC: {
            /* Only .dynamic should live in PT_DYNAMIC. */
            return (section_type == SECTION_DYNAMIC);
        }

        case PT_GNU_EH_FRAME: {
            /* Exception-handling metadata. */
            return (section_type == SECTION_EH_FRAME ||
                    section_type == SECTION_EH_FRAME_HEADER);
        }

        case PT_INTERP: {
            /* The interpreter path is a short string. Stay permissive to SECTION_STRING/UNKNOWN. */
            return (section_type == SECTION_STRING || section_type == SECTION_UNKNOWN);
        }

        case PT_NOTE: {
            /* Notes are heterogeneous; keep permissive to avoid false negatives. */
            return true;
        }

        case PT_PHDR: {
            /* Image of the program header table; keep permissive. */
            return true;
        }

        case PT_TLS: {
            /* TLS templates can be file-backed; keep permissive. */
            return true;
        }

        case PT_GNU_RELRO: {
            /* Protection window overlapping PT_LOAD; don't reject by type. */
            return true;
        }

        case PT_GNU_STACK: {
            /* Typically filesz == 0; if encountered, do not special-case reject. */
            return true;
        }

        default: {
            /* Unknown segment types: be permissive. */
            return true;
        }
    }
}


/**
 * @brief Locate the program segment that covers a given file offset.
 *
 * Searches the candidate's Program Header Table (PHT) for a segment whose
 * file-backed byte range [@c p_offset, @c p_offset + @c p_filesz) contains
 * @p file_offset. When multiple segments overlap the same offset, a
 * @c PT_LOAD segment is preferred over all others.
 *
 * @param[in]  candidate    Carve context whose block vector is used to read
 *                          the PHT via @ref build_segment_ranges().
 * @param[in]  file_offset  Absolute file offset to look up, measured from the
 *                          start of the ELF image.
 * @param[out] out          On success, populated with the matching segment's
 *                          @c seg_type, @c seg_offset, @c seg_file_size, and
 *                          any other fields carried by @c SegmentInfo.
 *                          Undefined on failure.
 * @retval true  A covering segment was found and @p out has been filled.
 * @retval false No segment covers @p file_offset, or the PHT could not be
 *               read (e.g., insufficient blocks in the candidate).
 *
 * @warning Containment is determined by file offsets (@c p_offset / @c p_filesz),
 *          not by virtual addresses (@c p_vaddr / @c p_memsz). Segments with
 *          @c p_filesz == 0 are skipped unconditionally.
 * @note PHT parsing, cross-block reads, and endianness/class handling are
 *       delegated to @ref build_segment_ranges() to avoid duplication.
 */
static inline bool find_segment_for_offset(CarveInfo *candidate,
                                           uint64_t file_offset,
                                           SegmentInfo *out)
{
    size_t nsegs = 0;
    SegmentInfo *segs = build_segment_ranges(candidate, &nsegs);
    bool found = false;
    bool found_load = false;
    SegmentInfo best = {0};

    if (!out || !segs || nsegs == 0) {
        free(segs);
        return false;
    }

    for (size_t i = 0; i < nsegs; i++) {
        uint64_t off = segs[i].seg_offset;
        uint64_t sz  = segs[i].seg_file_size;

        if (sz == 0) {
            continue; /* memory-only, or no file-backed content */
        }

        if (file_offset >= off && file_offset - off < sz) {
            if (segs[i].seg_type == PT_LOAD) {
                *out = segs[i];
                found = true;
                found_load = true;
                break;
            }
            if (!found) {
                best = segs[i];
                found = true;
            }
        }
    }

    if (found && !found_load) {
        *out = best;
    }
    free(segs);
    return found;
}



/***************************************************************/
/*         ELF BLOCK AND FILE VALIDATOR DEFINITIONS            */
/***************************************************************/



/**
 * @brief Validates an ELF data block and attaches ML-derived structural metadata to it.
 *
 * This function is the core block validator for ELF file reassembly. Its primary
 * purpose is to analyse the block's contents and store a @c BlockState describing the
 * ELF structural components found within it. An existing nonzero confidence, such as a
 * MoDiCo prior, is preserved. A zero confidence is promoted to
 * @c BLOCK_CONFIDENCE_VALID because ONYX supplies placement metadata rather than a
 * reliable whole-block exclusion decision and arbitrary ELF data must remain eligible.
 *
 * The analysis pipeline proceeds in three stages:
 *
 * 1. **Chunked ONNX inference** — The block is split into 4096-byte chunks. Each chunk
 *    is fed to a globally-initialised ONNX model (@c elf_onnx_global_get()) which
 *    returns @c RegionTripletC predictions (class, offset, size). Predictions are
 *    converted to @c BlockComponent entries with chunk-adjusted absolute offsets.
 *    STRING regions that contain known section-name tokens are promoted to SHSTRTAB.
 *    Component storage grows with the classifier output.
 *
 * 2. **Manual structure-table detection** — Both the Section Header Table (SHT) and
 *    Program Header Table (PHT) are searched heuristically for 32-bit and 64-bit ELF
 *    variants, trying little-endian and big-endian layouts. Any tables found are
 *    appended to the component list with priority; if the cap would be exceeded they
 *    overwrite the tail of the ML-derived components rather than being dropped.
 *
 * 3. **State storage** — The final component array is written into a @c BlockState and
 *    committed via @c block_put_state(). If no components were found the block is
 *    returned without any state attached.
 *
 * @note This function calls @c handle_error() with @c SCALPEL_GENERAL_ABORT (and does
 *       not return) if:
 *       - @p blocksize is less than 4096 bytes, or
 *       - the global ONNX handle has not been initialised (call
 *         @c elf_onnx_global_init() from @c scalpel.c before invoking validators).
 *
 * @param[in]  data          Pointer to the raw block data to be analysed.
 * @param[in]  length        Total byte length of the data buffer.
 * @param[in,out] decision   Existing nonzero confidence is preserved; zero is promoted
 *                           to @c BLOCK_CONFIDENCE_VALID.
 * @param[out] validates_to  Set to @p length unconditionally.
 * @param[in]  needleidx     Needle index passed through unchanged as the return value.
 * @param[in]  blocksize     Configured block size; must be ≥ 4096 bytes.
 * @param[in]  blockhashkey  Opaque key used to look up and store per-block state via
 *                           @c block_get_state() / @c block_put_state(). Must not be
 *                           @c NULL.
 *
 * @return The unchanged @p needleidx value.
 */
// classify one exemplar block from its per-chunk ONNX inference results (4096 bytes per
// chunk) plus manual SHT/PHT detection, producing the component map stored via
// block_put_state. 'chunk_triplets'/'chunk_counts' hold one entry per chunk of this block,
// as produced by elf_onnx_infer_batch() over the same chunking this function derives from
// 'length' and 'blocksize'. Called by elf_batched_block_validate(). The attached
// BlockState drives section placement; an existing nonzero whole-block confidence is
// preserved.
static inline uint32_t elf_classify_block(char *data,
                                          uint64_t length,
                                          BlockValidationDecision *decision,
                                          uint64_t *validates_to,
                                          uint32_t needleidx,
                                          uint32_t blocksize,
                                          void *blockhashkey,
                                          RegionTripletC *const *chunk_triplets,
                                          const size_t *chunk_counts) {
    if (*decision == BLOCK_CONFIDENCE_INVALID) {
        *decision = BLOCK_CONFIDENCE_VALID;
    }
    *validates_to = length;
    const ElfTunables sp = default_tunables();

    // We still proceed if not a multiple of 4096: process full 4096 chunks + a final padded chunk.
    const uint64_t safe_span   = (length < (uint64_t)blocksize) ? length : (uint64_t)blocksize;
    const uint64_t num_chunks  = (safe_span == 0) ? 0 : (uint64_t)((safe_span + 4095ULL) / 4096ULL);

// #ifdef ELF_REASSEMBLY_DEBUG
//     lock_fprintf(stdout,
//                  "[elf_classify_block] blockhashkey=%p needleidx=%u blocksize=%u length=%" PRIu64
//                  " safe_span=%" PRIu64 " num_chunks=%" PRIu64 " onnx_handle=%p\n",
//                  blockhashkey, needleidx, blocksize, (uint64_t)length,
//                  safe_span, num_chunks, (void*)h);
// #endif

    // Accumulate ML-derived components here.
    BlockComponent *components = NULL;
    size_t comp_cap = 0;
    size_t comp_count = 0;

    // ------------------------------
    // Per-chunk inference results (4096 bytes per chunk), supplied by the caller
    // ------------------------------
    for (uint64_t chunk_idx = 0; chunk_idx < num_chunks; ++chunk_idx) {
        const uint64_t chunk_base = chunk_idx * 4096ULL;
        const uint64_t remaining  = (safe_span > chunk_base) ? (safe_span - chunk_base) : 0;
        const uint64_t chunk_len  = (remaining >= 4096ULL) ? 4096ULL : remaining;

        if (chunk_len == 0) break;

        const RegionTripletC *triplets = chunk_triplets[chunk_idx];
        const size_t triplet_count = chunk_counts[chunk_idx];

        // Convert triplets -> BlockComponents with chunk-adjusted offsets.
        for (size_t t = 0; t < triplet_count; ++t) {
            const int32_t cls = triplets[t].cls;
            if (cls == 0 || cls == 1 || cls == 2 || cls == 3) continue;

            const uint64_t rel_off = (uint64_t)(uint32_t)triplets[t].offset;
            const uint64_t rel_sz  = (uint64_t)(uint32_t)triplets[t].size;

            if (rel_off >= 4096ULL || rel_sz == 0) continue;

            uint64_t abs_off = chunk_base + rel_off;
            if (abs_off >= safe_span) continue;

            uint64_t abs_sz = rel_sz;
            bool partial = false;

            // Clamp to available span inside the block.
            if (abs_off + abs_sz > safe_span) {
                abs_sz = safe_span - abs_off;
                partial = true;
            }

            // Mark as partial if it touches a chunk boundary (likely continuation).
            if (!partial) {
                const bool touches_left  = (rel_off == 0) && (chunk_idx > 0);
                const bool touches_right = (rel_off + rel_sz >= 4096ULL) && (chunk_idx + 1 < num_chunks);
                if (touches_left || touches_right) partial = true;
            }

            SectionDataType section_type = cls_to_section_type(cls);

            // shstrtab refinement: STRING regions that contain known section-name tokens become SHSTRTAB.
            if (section_type == SECTION_STRING) {
                if (abs_off + abs_sz <= safe_span) {
                    const char *region = (const char *)(data + abs_off);
                    if (contains_shstrtab_markers(region, (size_t)abs_sz)) {
                        section_type = SECTION_SHSTRTAB;
#ifdef ELF_REASSEMBLY_DEBUG
                        lock_fprintf(stdout,
                                     "[elf_classify_block] SHSTRTAB discovered: chunk=%" PRIu64
                                     " abs_off=%" PRIu64 " size=%" PRIu64 " partial=%d\n",
                                     chunk_idx, abs_off, abs_sz, (int)partial);
#endif
                    }
                }
            }

            ensure_component_capacity(&components, &comp_cap,
                                      comp_count + 1);

            components[comp_count].type        = COMPONENT_SECTION;
            components[comp_count].section     = section_type;
            components[comp_count].blockOffset = abs_off;
            components[comp_count].size        = abs_sz;

            comp_count++;
        }
    }

    // ------------------------------
    // Manual SHT detection (32/64 + both endiannesses)
    // ------------------------------
    BlockComponent detected_32, detected_64;
    bool found_32 = detect_sht_component_32(data, safe_span, TARGET_ENDIANNESS, ELF_LITTLE_ENDIAN, 40,
                                           &detected_32, blockhashkey, &sp);
    if (!found_32) {
        found_32 = detect_sht_component_32(data, safe_span, TARGET_ENDIANNESS, ELF_BIG_ENDIAN, 40,
                                           &detected_32, blockhashkey, &sp);
    }

    bool found_64 = detect_sht_component_64(data, safe_span, TARGET_ENDIANNESS, ELF_LITTLE_ENDIAN, 64,
                                           &detected_64, blockhashkey, &sp);
    if (!found_64) {
        found_64 = detect_sht_component_64(data, safe_span, TARGET_ENDIANNESS, ELF_BIG_ENDIAN, 64,
                                           &detected_64, blockhashkey, &sp);
    }

#ifdef ELF_REASSEMBLY_DEBUG
    if (found_32) {
        lock_fprintf(stdout,
                     "[elf_classify_block] SHT32 detected: off=%" PRIu64 " size=%" PRIu64 "\n",
                     (uint64_t)detected_32.blockOffset, (uint64_t)detected_32.size);
    }
    if (found_64) {
        lock_fprintf(stdout,
                     "[elf_classify_block] SHT64 detected: off=%" PRIu64 " size=%" PRIu64 "\n",
                     (uint64_t)detected_64.blockOffset, (uint64_t)detected_64.size);
    }
#endif

    // ------------------------------
    // Manual PHT detection (32/64 + both endiannesses)
    // ------------------------------
    BlockComponent pht_detected_32, pht_detected_64;
    bool pht_found_32 = detect_pht_component_32(data, safe_span, TARGET_ENDIANNESS, ELF_LITTLE_ENDIAN,
                                               PHT_ENTRY_SIZE_32, &pht_detected_32, blockhashkey, &sp);
    if (!pht_found_32) {
        pht_found_32 = detect_pht_component_32(data, safe_span, TARGET_ENDIANNESS, ELF_BIG_ENDIAN,
                                               PHT_ENTRY_SIZE_32, &pht_detected_32, blockhashkey, &sp);
    }

    bool pht_found_64 = detect_pht_component_64(data, safe_span, TARGET_ENDIANNESS, ELF_LITTLE_ENDIAN,
                                               PHT_ENTRY_SIZE_64, &pht_detected_64, blockhashkey, &sp);
    if (!pht_found_64) {
        pht_found_64 = detect_pht_component_64(data, safe_span, TARGET_ENDIANNESS, ELF_BIG_ENDIAN,
                                               PHT_ENTRY_SIZE_64, &pht_detected_64, blockhashkey, &sp);
    }

#ifdef ELF_REASSEMBLY_DEBUG
    if (pht_found_32) {
        lock_fprintf(stdout,
                     "[elf_classify_block] PHT32 detected: off=%" PRIu64 " size=%" PRIu64 "\n",
                     (uint64_t)pht_detected_32.blockOffset, (uint64_t)pht_detected_32.size);
    }
    if (pht_found_64) {
        lock_fprintf(stdout,
                     "[elf_classify_block] PHT64 detected: off=%" PRIu64 " size=%" PRIu64 "\n",
                     (uint64_t)pht_detected_64.blockOffset, (uint64_t)pht_detected_64.size);
    }
#endif

    // ------------------------------
    // Append SHT/PHT components after the classifier-derived regions.
    // ------------------------------
    {
        size_t manual_total = 0;
        if (found_32)     manual_total++;
        if (found_64)     manual_total++;
        if (pht_found_32) manual_total++;
        if (pht_found_64) manual_total++;

        if (manual_total > 0) {
            if (comp_count > SIZE_MAX - manual_total) {
                check_memory_allocation(NULL, __LINE__, __FILE__,
                                        "BlockComponents count");
            }
            ensure_component_capacity(&components, &comp_cap,
                                      comp_count + manual_total);

            size_t w = comp_count;
            if (found_32) {
                components[w++] = detected_32;
            }
            if (found_64) {
                components[w++] = detected_64;
            }
            if (pht_found_32) {
                components[w++] = pht_detected_32;
            }
            if (pht_found_64) {
                components[w++] = pht_detected_64;
            }
            comp_count = w;
        }
    }

    if (comp_count == 0) {
        free(components);
        components = NULL;
        comp_cap = 0;
    } else {
        BlockComponent *tmp = (BlockComponent *)realloc(components, comp_count * sizeof(BlockComponent));
        if (tmp) components = tmp;
    }

#ifdef ELF_REASSEMBLY_DEBUG
    // Log final component list (major summary only)
    lock_fprintf(stdout, "[elf_classify_block] final components: n=%zu\n", comp_count);
    for (size_t i = 0; i < comp_count; ++i) {
        lock_fprintf(stdout,
                     "  [comp %zu] type=%d section=%d off=%" PRIu64 " size=%" PRIu64 "\n",
                     i, (int)components[i].type, (int)components[i].section,
                     (uint64_t)components[i].blockOffset, (uint64_t)components[i].size);
    }
#endif

    //ensures unknown / non-elf blocks do not get state assigned to them
    if (comp_count == 0) {
        free(components);
        *validates_to = length;
        return needleidx;
    }

    // ------------------------------
    // Store state on the block
    // ------------------------------
    BlockState *state = (BlockState *)block_get_state(blockhashkey);

    if (!state) {
        state = (BlockState *)malloc(sizeof(BlockState));
        check_memory_allocation(state, __LINE__, __FILE__, "BlockState");
        state->components = NULL;
        state->num_components = 0;
        
    } else {
        free(state->components);
        state->components = NULL;
        state->num_components = 0;
        
    }

    state->components = components;         // may be NULL if none
    state->num_components = comp_count;     // may be 0
  
    block_put_state(blockhashkey, state);
    elf_free_block_state((void **)&state);

// #ifdef ELF_REASSEMBLY_DEBUG
//     lock_fprintf(stdout,
//                  "[elf_classify_block] block_put_state: blockhashkey=%p state=%p components=%p num_components=%zu\n",
//                  blockhashkey, (void*)state, (void*)components, comp_count);
// #endif

    // ONYX attaches placement metadata without discarding a prior confidence.
    *validates_to = length;
    return needleidx;
}


// conservative per-chunk device working-set estimate for the U-Net's input, output, intermediate
// activations, execution workspace, and ONNX Runtime arena growth
#define ELF_ONNX_BYTES_PER_CHUNK ((size_t)128 * 1024 * 1024)

// per-Run chunk ceiling for the planner. CUDA throughput reaches its plateau at this size
// without the latency and workspace growth measured at larger batches. The trial Run below
// still verifies it on the selected provider and halves it after an allocation failure.
// SCALPEL3_ELF_BATCH forces an exact batch for controlled experiments.
#define ELF_ONNX_MAX_BATCH 64

// floor for the halve-on-failed-trial loop at session init. A small-memory GPU can still
// execute useful work at batch one; the planner chooses a larger value whenever it fits.
#define ELF_ONNX_MIN_BATCH 1

// CPU shape processing reaches its throughput plateau between twenty-four and thirty-two
// workers on the reference machine. Use at most one quarter of the detected physical cores
// so concurrently running cursor validators retain most of the host. Smaller machines scale
// this limit down.
#define ELF_ONNX_MAX_DECODE_THREADS 32

// ceiling on how many apparent blocks a validation worker claims from the shared cursor
// at a time; the actual claim size scales down on small images so every worker gets
// several turns at the cursor instead of one worker draining the whole image
#define ELF_WORK_CHUNK_BLOCKS 4096

// displacement-solve work controls. These control the arithmetic quick path;
// they must not limit the checkpointable scored reassembly that follows it.
#define ELF_GAPSOLVE_SCAN_MAX_BYTES (8ULL * 1024 * 1024)
#define ELF_GAPSOLVE_MAX_TRIALS     2048

// make sure the ELF ONNX model file exists, reconstructing it from its split pieces when
// necessary. The model is stored in git as elf_onnx/<name>.part_NNN chunks, so a plain
// clone has no assembled model until init_scalpel3.sh runs; reconstructing here makes a
// pulled tree work directly. The pieces are concatenated into a temporary file that is
// renamed into place, so an interrupted reconstruction never leaves a truncated model
// behind. Returns false with a precise, user-actionable message in errmsg when the model
// cannot be made available at all.
static inline bool elf_onnx_ensure_model(const char *model_path,
                                         char *errmsg, size_t errmsg_sz) {
    struct stat st;

    if (stat(model_path, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0) {
        return true;
    }

    // derive <model dir>/elf_onnx/<model name>.part_NNN from the model path
    char dir[PATH_MAX];
    const char *base = strrchr(model_path, '/');

    if (! base || (size_t)(base - model_path) >= sizeof(dir)) {
        snprintf(errmsg, errmsg_sz, "ELF ONNX model path is not usable: %s.", model_path);
        return false;
    }
    memcpy(dir, model_path, (size_t)(base - model_path));
    dir[base - model_path] = '\0';
    base++;

    // count the pieces
    int nparts = 0;
    char part_path[PATH_MAX];

    for (int i = 0; i < 64; i++) {
        snprintf(part_path, sizeof(part_path), "%s/elf_onnx/%s.part_%03d", dir, base, i);
        if (stat(part_path, &st) != 0 || ! S_ISREG(st.st_mode)) {
            break;
        }
        nparts++;
    }

    if (nparts == 0) {
        snprintf(errmsg, errmsg_sz,
                 "ELF ONNX model file is missing: %s. Its split pieces "
                 "(%s/elf_onnx/%s.part_000, ...) were not found either. Run "
                 "init_scalpel3.sh in the scalpel3 base directory, or restore the model, "
                 "and retry.",
                 model_path, dir, base);
        return false;
    }

    scalpel_log("ELF ONNX model not found; reconstructing it from %d pieces...\n",
                nparts);

    char tmp_path[PATH_MAX];
    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", model_path);

    FILE *out = fopen(tmp_path, "wb");
    if (! out) {
        snprintf(errmsg, errmsg_sz,
                 "ELF ONNX model reconstruction failed: cannot write %s.", tmp_path);
        return false;
    }

    static char iobuf[262144];
    bool io_ok = true;

    for (int i = 0; i < nparts && io_ok; i++) {
        snprintf(part_path, sizeof(part_path), "%s/elf_onnx/%s.part_%03d", dir, base, i);

        FILE *in = fopen(part_path, "rb");
        if (! in) {
            io_ok = false;
            break;
        }

        size_t got;
        while ((got = fread(iobuf, 1, sizeof(iobuf), in)) > 0) {
            if (fwrite(iobuf, 1, got, out) != got) {
                io_ok = false;
                break;
            }
        }
        if (ferror(in)) {
            io_ok = false;
        }
        fclose(in);
    }

    if (fclose(out) != 0) {
        io_ok = false;
    }

    if (! io_ok || rename(tmp_path, model_path) != 0) {
        unlink(tmp_path);
        snprintf(errmsg, errmsg_sz,
                 "ELF ONNX model reconstruction from %s/elf_onnx/%s.part_* failed; "
                 "run init_scalpel3.sh in the scalpel3 base directory and retry.",
                 dir, base);
        return false;
    }

    scalpel_log("ELF ONNX model reconstructed: %s\n", model_path);
    return true;
}


// prove a session can actually run its batch by pushing one dummy batch of zeroed
// chunks through it. The batch planner sizes from free-memory arithmetic, which cannot
// see provider internals (arena growth, the compiled model's working set), so only a
// real Run settles whether the batch fits on the device.
static int elf_onnx_probe_batch(elf_onnx_handle_t h, size_t nchunks) {
    if (! h || nchunks == 0) {
        return ELF_ONNX_BADARG;
    }

    uint8_t *blobs = (uint8_t *)calloc(nchunks, 4096u);
    RegionTripletC **triplets =
        (RegionTripletC **)calloc(nchunks, sizeof(RegionTripletC *));
    size_t *counts = (size_t *)calloc(nchunks, sizeof(size_t));
    int result = ELF_ONNX_NOMEM;

    if (blobs && triplets && counts) {
        result = elf_onnx_infer_batch(h, blobs, nchunks, triplets, counts);
        for (size_t i = 0; i < nchunks; i++) {
            free(triplets[i]);
        }
    }
    free(blobs);
    free(triplets);
    free(counts);
    if (result == ELF_ONNX_NOMEM) {
        result = ELF_ONNX_RETRYABLE;
    }
    return result;
}


// decode-mode selection for the ELF ONNX model. The heavy postprocess pipeline is the
// default; the SCALPEL3_ONNX_DECODE_MODE environment variable ("raw" or "raw_argmax")
// selects the raw argmax decoder instead, for experiments comparing the two.
static inline int elf_onnx_decode_config(char *decode_name, size_t decode_name_sz) {
    const char *e = getenv("SCALPEL3_ONNX_DECODE_MODE");

    if (decode_name && decode_name_sz > 0) {
        strncpy(decode_name, "heavy", decode_name_sz - 1);
        decode_name[decode_name_sz - 1] = '\0';
    }

    if (e && (! strcasecmp(e, "raw") || ! strcasecmp(e, "raw_argmax"))) {
        if (decode_name && decode_name_sz > 0) {
            strncpy(decode_name, "raw", decode_name_sz - 1);
            decode_name[decode_name_sz - 1] = '\0';
        }
        return ELF_ONNX_DECODE_RAW_ARGMAX;
    }

    // anything else (unset, heavy, or an unknown value) selects the default heavy postprocess
    return ELF_ONNX_DECODE_HEAVY_POSTPROCESS;
}


// exit watcher for the ELF batched block validator, mirroring modico_exit_watcher: a tiny
// thread that polls TAKE_CHECKPOINT_AND_EXIT and terminates any in-flight ONNX Run on
// every active session, so a checkpoint-and-exit is not stuck behind a batched inference.
typedef struct ElfExitWatcher {
    atomic_bool stop;
    atomic_bool terminated;
    atomic_int *failure;
    elf_onnx_handle_t *handles;
    int num_handles;
} ElfExitWatcher;

static void *elf_exit_watcher(void *arg) {
    ElfExitWatcher *watcher = (ElfExitWatcher *)arg;
    struct timespec pause = {0, 100000000};
    bool termination_sent = false;

    while (! atomic_load_explicit(&watcher->stop, memory_order_acquire)) {
        bool exit_requested =
            atomic_load_explicit(&TAKE_CHECKPOINT_AND_EXIT, memory_order_acquire);
        bool failed = watcher->failure
                   && atomic_load_explicit(watcher->failure,
                                           memory_order_acquire) != ELF_ONNX_OK;

        if (! termination_sent && (exit_requested || failed)) {
            for (int i = 0; i < watcher->num_handles; i++) {
                if (watcher->handles[i]
                    && elf_onnx_terminate(watcher->handles[i]) == ELF_ONNX_OK) {
                    if (exit_requested) {
                        atomic_store_explicit(&watcher->terminated, true,
                                              memory_order_release);
                    }
                }
            }
            termination_sent = true;
        }
        nanosleep(&pause, NULL);
    }

    return NULL;
}


// per-worker context for the batched ELF validator. One worker per ONNX session; workers
// claim ranges of apparent blocks from a shared cursor, so any number of sessions (one on
// most providers, one per GPU device on cuda) service the same pass without partitioning.
typedef struct ElfValidateWorker {
    elf_onnx_handle_t h;
    FileMirror *fm;
    uint32_t needleidx;
    uint32_t blocksize;
    uint64_t num_blocks;
    uint64_t claim_blocks;
    uint32_t flush_capacity;
    atomic_ullong *next_apparent;
    atomic_int *shared_failure;
    atomic_bool *interrupt_reported;
    pthread_mutex_t *report_lock;
    long *last_report;
    const struct timespec *phase_start;
    int worker_id;
} ElfValidateWorker;

// service the shared cursor with one session: claim a range of apparent blocks, stage its
// exemplar blocks' chunks into a contiguous buffer, and classify a full buffer with one
// batched inference call. Duplicates share their exemplar's decision and state. Runs on
// the main thread for single-session providers and on one thread per device for cuda.
static void *elf_validate_worker(void *arg) {
    ElfValidateWorker *w = (ElfValidateWorker *)arg;
    FileMirror *fm = w->fm;
    const uint32_t needleidx = w->needleidx;
    const uint32_t blocksize = w->blocksize;
    const uint64_t num_blocks = w->num_blocks;
    const uint64_t claim_blocks = w->claim_blocks;
    const uint32_t flush_capacity = w->flush_capacity;

    uint8_t *stage = (uint8_t *)malloc((size_t)flush_capacity * 4096u);
    RegionTripletC **stage_triplets =
        (RegionTripletC **)calloc(flush_capacity, sizeof(RegionTripletC *));
    size_t *stage_counts = (size_t *)calloc(flush_capacity, sizeof(size_t));
    int64_t *stage_block = (int64_t *)malloc(flush_capacity * sizeof(int64_t));
    char **stage_data = (char **)malloc(flush_capacity * sizeof(char *));
    uint64_t *stage_length = (uint64_t *)malloc(flush_capacity * sizeof(uint64_t));
    uint32_t *stage_chunk0 = (uint32_t *)malloc(flush_capacity * sizeof(uint32_t));

    check_memory_allocation(stage, __LINE__, __FILE__, "elf stage");
    check_memory_allocation(stage_triplets, __LINE__, __FILE__, "elf stage_triplets");
    check_memory_allocation(stage_counts, __LINE__, __FILE__, "elf stage_counts");
    check_memory_allocation(stage_block, __LINE__, __FILE__, "elf stage_block");
    check_memory_allocation(stage_data, __LINE__, __FILE__, "elf stage_data");
    check_memory_allocation(stage_length, __LINE__, __FILE__, "elf stage_length");
    check_memory_allocation(stage_chunk0, __LINE__, __FILE__, "elf stage_chunk0");

    uint32_t staged_chunks = 0;
    uint32_t staged_blocks = 0;
    bool interrupted = false;

    while (! interrupted
           && atomic_load_explicit(w->shared_failure,
                                   memory_order_acquire) == ELF_ONNX_OK) {
        uint64_t claim_start = atomic_fetch_add_explicit(w->next_apparent,
                                                         claim_blocks,
                                                         memory_order_acq_rel);
        if (claim_start >= num_blocks) {
            break;
        }

        uint64_t claim_end = claim_start + claim_blocks;
        if (claim_end > num_blocks) {
            claim_end = num_blocks;
        }

        for (uint64_t block = claim_start; block <= claim_end; block++) {
            bool flush_now = (block == claim_end);
            int64_t actual = 0;
            char *data = NULL;
            uint64_t length = 0;
            uint64_t safe_span = 0;
            uint64_t nchunks = 0;

            // stop at a flush boundary when a checkpoint-and-exit has been requested;
            // the remaining blocks are abandoned (see the consistency note below). The
            // message is printed by whichever worker notices first, once per pass.
            if (atomic_load_explicit(&TAKE_CHECKPOINT_AND_EXIT, memory_order_acquire)) {
                if (! atomic_exchange_explicit(w->interrupt_reported, true,
                                               memory_order_acq_rel)) {
                    scalpel_log("ELF block validation interrupted by "
                                "checkpoint-and-exit.\n");
                }
                interrupted = true;
                break;
            }
            if (atomic_load_explicit(w->shared_failure,
                                     memory_order_acquire) != ELF_ONNX_OK) {
                break;
            }

            if (! flush_now) {
                actual = filemirror_actual_blocknumber(fm, (int64_t)block);
                if (filemirror_get_exemplar(fm, actual) != actual) {
                    continue;
                }

                data = filemirror_actual_block_data_pointer(fm, actual, &length);
                if (! data) {
                    continue;
                }

                safe_span = (length < (uint64_t)blocksize) ? length : (uint64_t)blocksize;
                nchunks = (safe_span == 0) ? 0 : ((safe_span + 4095ULL) / 4096ULL);
                if (nchunks == 0) {
                    continue;
                }

                // flush first when this block's chunks would overflow the staging buffer
                if (staged_chunks + (uint32_t)nchunks > flush_capacity) {
                    flush_now = true;
                }
            }

            if (flush_now && staged_chunks > 0) {
                int infer_result =
                    elf_onnx_infer_batch(w->h, stage, staged_chunks,
                                         stage_triplets, stage_counts);
                if (infer_result != ELF_ONNX_OK) {
                    // a Run the exit watcher terminated surfaces as an inference failure;
                    // that is an interruption, not an error
                    if (atomic_load_explicit(&TAKE_CHECKPOINT_AND_EXIT,
                                             memory_order_acquire)) {
                        if (! atomic_exchange_explicit(w->interrupt_reported, true,
                                                       memory_order_acq_rel)) {
                            scalpel_log("ELF block validation interrupted by "
                                        "checkpoint-and-exit.\n");
                        }
                        interrupted = true;
                        break;
                    }
                    int expected = ELF_ONNX_OK;

                    atomic_compare_exchange_strong_explicit(w->shared_failure,
                                                             &expected,
                                                             infer_result,
                                                             memory_order_acq_rel,
                                                             memory_order_acquire);
                    break;
                }

                for (uint32_t sb = 0; sb < staged_blocks; sb++) {
                    char blockhashkey[BLOCK_HASH_KEY_SIZE];
                    gen_block_hash_key(blockhashkey, needleidx, stage_block[sb]);

                    // seed from the stored confidence (a MoDiCo prior, when present),
                    // mirroring the single-block contract; the classifier decides VALID
                    // unconditionally and the component map it attaches is what matters
                    BlockValidationDecision decision =
                        filemirror_get_blocktype(fm, stage_block[sb], needleidx);
                    uint64_t validates_to = 0;

                    elf_classify_block(stage_data[sb], stage_length[sb], &decision,
                                       &validates_to, needleidx, blocksize, blockhashkey,
                                       &stage_triplets[stage_chunk0[sb]],
                                       &stage_counts[stage_chunk0[sb]]);

                    filemirror_set_blocktype(fm, stage_block[sb], needleidx, decision);
                }

                for (uint32_t c = 0; c < staged_chunks; c++) {
                    free(stage_triplets[c]);
                    stage_triplets[c] = NULL;
                }
                staged_chunks = 0;
                staged_blocks = 0;

                long now = time(NULL);
                MUTEX_ERROR_CHECK(pthread_mutex_lock(w->report_lock), __LINE__, __FILE__);
                if (now - *(w->last_report) >= 2) {
                    struct timespec endtime;
                    double elapsed;
                    uint64_t pos = atomic_load_explicit(w->next_apparent,
                                                        memory_order_acquire);

                    *(w->last_report) = now;
                    if (pos > num_blocks) {
                        pos = num_blocks;
                    }
                    clock_gettime(CLOCK_MONOTONIC, &endtime);
                    elapsed = (double)(endtime.tv_sec - w->phase_start->tv_sec)
                            + (double)(endtime.tv_nsec - w->phase_start->tv_nsec) / 1e9;
                    lock_fprintf(stdout,
                                 "Status: ELF block validation (%3.1lf%%), total elapsed time = %.2lf secs.\n",
                                 num_blocks ? (double)pos / (double)num_blocks * 100.0
                                            : 100.0,
                                 elapsed);
                }
                MUTEX_ERROR_CHECK(pthread_mutex_unlock(w->report_lock), __LINE__, __FILE__);
            }

            if (block == claim_end) {
                break;
            }

            // stage this block: record it, then copy its chunks (short final chunk zero
            // padded)
            stage_block[staged_blocks] = actual;
            stage_data[staged_blocks] = data;
            stage_length[staged_blocks] = length;
            stage_chunk0[staged_blocks] = staged_chunks;
            staged_blocks++;

            for (uint64_t ci = 0; ci < nchunks; ci++) {
                const uint64_t chunk_base = ci * 4096ULL;
                uint64_t chunk_len = safe_span - chunk_base;
                uint8_t *dst = stage + (size_t)staged_chunks * 4096u;

                if (chunk_len > 4096ULL) {
                    chunk_len = 4096ULL;
                }
                memcpy(dst, data + chunk_base, (size_t)chunk_len);
                if (chunk_len < 4096ULL) {
                    memset(dst + chunk_len, 0, (size_t)(4096ULL - chunk_len));
                }
                staged_chunks++;
            }
        }
    }

    free(stage);
    free(stage_triplets);
    free(stage_counts);
    free(stage_block);
    free(stage_data);
    free(stage_length);
    free(stage_chunk0);

    return NULL;
}


// the ELF BATCHEDBLOCKVALIDATOR. Invoked once per run on the main thread by the block
// validation phase; iterates the apparent blocks itself and records a decision and component
// map for every exemplar. The ONNX lifecycle is fully self-managed here: the model loads at
// the top of this body, so runs that never reach ELF block validation (-U elf or checkpoint
// restore) never pay for the 190MB load; inference runs through the process
// global session; and the bottom of the body writes the timing report and shuts the session
// down. The execution provider comes from the run-wide resolution in onnx_providers.h: a
// provider requested explicitly with -Y that fails late is fatal, the auto path falls back
// to cpu. A checkpoint-and-exit request interrupts the loop promptly: the exit watcher
// terminates any in-flight Run and the loop stops at the next flush boundary. Stopping early
// is checkpoint-consistent because an exit requested during block validation leaves the run
// without restartable recovery state (main stops before any recovery checkpoint exists), so
// the next run redoes block validation from scratch, exactly as it does when MoDiCo is
// interrupted.
static inline void elf_batched_block_validate(uint32_t needleidx, uint32_t blocksize) {

    // Contiguous-only ELF validation is self-contained and does not use ONYX
    // placement metadata. Preserve prior classifier decisions and initialize
    // remaining decisions to the Scalpel3 default.
    if (scalpel_state.no_defrag) {
        const uint32_t filetype = needleidx;

        (void)filemirror_default_unclassified_blocktypes(
            scalpel_state.filemirror, &filetype, 1,
            BLOCK_CONFIDENCE_VALID);
        return;
    }

    // ONYX classifies 4096 byte windows. At smaller carve block sizes, retain
    // MoDiCo priors and leave unclassified blocks available rather than infer
    // from inputs dominated by synthetic padding.
    if (blocksize < 4096) {
        const uint32_t filetype = needleidx;
        uint64_t initialized = filemirror_default_unclassified_blocktypes(
            scalpel_state.filemirror, &filetype, 1,
            BLOCK_CONFIDENCE_VALID);

        lock_fprintf(stdout,
                     "Skipping ONYX ELF block validation for %u byte blocks; "
                     "preserved classifier decisions and initialized %" PRIu64
                     " unclassified blocks.\n",
                     blocksize, initialized);
        scalpel_log(
            "Skipped ONYX ELF block validation for %u byte blocks; preserved "
            "classifier decisions and initialized %" PRIu64
            " unclassified blocks.\n",
            blocksize, initialized);
        return;
    }

    // initialize the ONNX model
    const char *scalpel3_home = getenv("SCALPEL3_HOME");  // main() verified it is set
    char model_path[PATH_MAX];
    char decode_name[32];
    char accel[32];
    int decode_mode;

    snprintf(model_path, sizeof(model_path), "%s/src/exe_vision/unix/elf_unet.onnx",
             scalpel3_home ? scalpel3_home : ".");

    // a missing model file is a setup problem, not a provider failure: reconstruct it
    // from its split pieces when possible, and name the real cause plainly when not
    {
        char model_errmsg[PATH_MAX + 512];

        if (! elf_onnx_ensure_model(model_path, model_errmsg, sizeof(model_errmsg))) {
            scalpel_log_err("\nERROR: %s\n", model_errmsg);
            exit(-1);
        }
    }

    decode_mode = elf_onnx_decode_config(decode_name, sizeof(decode_name));

    strncpy(accel, onnx_resolved_accelerator(), sizeof(accel) - 1);
    accel[sizeof(accel) - 1] = '\0';

    // plan the per-Run chunk batch from the device budget BEFORE creating the session (a
    // static-shape provider pins its batch dimension to it at session creation)
    gpu_batch_spec_t plan = {0};
    if (! strcasecmp(accel, "cpu")) {
        plan.device_id = -1;
    }
    else {
        plan.device_id = onnx_cuda_physical_device(
            onnx_resolved_num_devices() > 0 ? onnx_resolved_device_list()[0] : 0);
    }
    plan.bytes_per_sample = ELF_ONNX_BYTES_PER_CHUNK;
    plan.min_batch = 1;
    plan.max_batch = ELF_ONNX_MAX_BATCH;
    plan.label = "elf";
    {
        const char *e = getenv("SCALPEL3_ELF_BATCH");
        if (e && *e) {
            int forced = atoi(e);
            if (forced > 0) {
                plan.force_batch = forced;
            }
        }
    }
    int batch = gpu_plan_batch(&plan);

    // the global session runs on the first resolved device (only meaningful for cuda)
    int device0 = onnx_resolved_num_devices() > 0 ? onnx_resolved_device_list()[0] : 0;
    int physical_cores = num_detected_physical_cores();
    int planned_inference_workers =
        ! strcasecmp(accel, "cuda") ? onnx_resolved_num_devices() : 1;
    int requested_decode_threads;
    int requested_cpu_threads;
    int cpu_threads;
    int onnx_threads = 1;
    int decode_threads;

    if (physical_cores < 1) {
        physical_cores = 1;
    }
    if (planned_inference_workers < 1) {
        planned_inference_workers = 1;
    }

    requested_decode_threads = (batch + 3) / 4;
    {
        int physical_decode_limit = (physical_cores + 3) / 4;

        if (requested_decode_threads > physical_decode_limit) {
            requested_decode_threads = physical_decode_limit;
        }
    }
    if (requested_decode_threads > ELF_ONNX_MAX_DECODE_THREADS) {
        requested_decode_threads = ELF_ONNX_MAX_DECODE_THREADS;
    }
    if (requested_decode_threads > batch) {
        requested_decode_threads = batch;
    }
    {
        const char *e = getenv("SCALPEL3_ELF_DECODE_THREADS");

        if (e && *e) {
            int forced = atoi(e);

            if (forced > 0) {
                requested_decode_threads = forced;
            }
        }
    }
    if (requested_decode_threads > batch) {
        requested_decode_threads = batch;
    }

    if (! strcasecmp(accel, "cpu")) {
        requested_cpu_threads = (physical_cores * 3 + 3) / 4;
    }
    else {
        requested_cpu_threads =
            requested_decode_threads + planned_inference_workers;
    }
    {
        const char *e = getenv("SCALPEL3_ELF_CPU_THREADS");

        if (e && *e) {
            int forced = atoi(e);

            if (forced > 0) {
                requested_cpu_threads = forced;
            }
        }
    }

    cpu_threads = (int)block_validation_reserve_cpu_threads(
        (uint32_t)requested_cpu_threads);
    if (! strcasecmp(accel, "cpu")) {
        decode_threads = requested_decode_threads;
        if (decode_threads >= cpu_threads && cpu_threads > 1) {
            decode_threads = cpu_threads - 1;
        }
        onnx_threads = cpu_threads - decode_threads;
        if (onnx_threads < 1) {
            onnx_threads = 1;
        }
    }
    else {
        decode_threads = cpu_threads - planned_inference_workers;
        if (decode_threads < 1) {
            decode_threads = 1;
        }
    }
    {
        const char *e = getenv("SCALPEL3_ELF_DECODE_THREADS");

        if (e && *e) {
            int forced = atoi(e);
            int decode_limit =
                ! strcasecmp(accel, "cpu")
                    ? (cpu_threads > 1 ? cpu_threads - 1 : 1)
                    : cpu_threads;

            if (forced > 0) {
                decode_threads = forced < decode_limit ? forced : decode_limit;
            }
        }
    }
    if (decode_threads > ELF_ONNX_MAX_DECODE_THREADS) {
        decode_threads = ELF_ONNX_MAX_DECODE_THREADS;
    }
    if (decode_threads > batch) {
        decode_threads = batch;
    }
    if (! strcasecmp(accel, "cpu")) {
        onnx_threads = cpu_threads - decode_threads;
        if (onnx_threads < 1) {
            onnx_threads = 1;
        }
    }

    // create the session, then prove the planned batch with one dummy Run on GPU
    // providers, halving and recreating on failure down to the floor. A batch forced
    // via SCALPEL3_ELF_BATCH is never adjusted, so a forced experiment fails loudly
    // instead of silently measuring a different batch.
    bool session_ok = false;

    while (! session_ok) {
        int probe_result = ELF_ONNX_OK;

        if (! elf_onnx_global_init_batch_device_threads(
                model_path, accel, decode_mode, batch, device0, onnx_threads)) {
            break;
        }
        if (strcasecmp(accel, "cpu") != 0) {
            probe_result = elf_onnx_probe_batch(elf_onnx_global_get(),
                                                (size_t)batch);
        }
        if (! strcasecmp(accel, "cpu") || probe_result == ELF_ONNX_OK) {
            session_ok = true;
            break;
        }
        elf_onnx_global_shutdown();
        if (probe_result != ELF_ONNX_RETRYABLE
            || plan.force_batch > 0 || batch <= ELF_ONNX_MIN_BATCH) {
            scalpel_log("ELF ONNX trial run failed at batch %d on '%s'.\n", batch, accel);
            break;
        }

        int halved = batch / 2;

        if (halved < ELF_ONNX_MIN_BATCH) {
            halved = ELF_ONNX_MIN_BATCH;
        }
        scalpel_log("ELF ONNX trial run failed at batch %d on '%s'; retrying with "
                    "batch %d.\n", batch, accel, halved);
        batch = halved;
    }

    if (! session_ok) {
        // the provider passed the startup capability check, but session creation can still
        // fail late (e.g. a CoreML model compile failure or a device that cannot hold even
        // the floor batch). An explicitly requested provider must not be silently
        // downgraded, so that is fatal; on auto, fall back to cpu so the run stays usable.
        // A cpu init failure is fatal.
        if (onnx_resolved_was_explicit() && strcasecmp(accel, "cpu") != 0) {
            char errmsg[256];

            snprintf(errmsg, sizeof(errmsg),
                     "ELF ONNX initialization failed on the requested execution provider "
                     "'%s'. Rerun with a provider this machine supports, e.g. -Y cpu.",
                     accel);
            handle_error(SCALPEL_GENERAL_ABORT, errmsg, __LINE__, __FILE__);
        }
        if (strcasecmp(accel, "cpu") != 0) {
            if (! onnx_runtime_fallback_to_cpu(
                    "ELF ONNX could not execute its accelerator trial batch")) {
                handle_error(SCALPEL_GENERAL_ABORT,
                             "ELF ONNX could not fall back to CPU after its "
                             "accelerator trial batch failed.",
                             __LINE__, __FILE__);
            }
            scalpel_log("ELF ONNX init failed on accelerator '%s'; falling back to CPU.\n",
                        accel);
            strncpy(accel, "cpu", sizeof(accel) - 1);
            accel[sizeof(accel) - 1] = '\0';
        }
        if (! elf_onnx_global_init_batch_device_threads(
                model_path, accel, decode_mode, batch, device0, onnx_threads)) {
            char errmsg[PATH_MAX + 256];

            snprintf(errmsg, sizeof(errmsg),
                     "Failed to initialize ELF ONNX model (elf_unet.onnx) on CPU with "
                     "decode mode '%s'.", decode_name);
            handle_error(SCALPEL_GENERAL_ABORT, errmsg, __LINE__, __FILE__);
        }
    }

    elf_onnx_global_reset_timing();
    scalpel_log("ELF ONNX model initialized: %s (provider %s, decode mode %s, batch %d).\n",
                model_path, accel, decode_name, batch);

    elf_onnx_handle_t h = elf_onnx_global_get();

    // one session per resolved device for cuda, mirroring MoDiCo's fan-out; every other
    // provider runs the single global session
    elf_onnx_handle_t handles[ONNX_MAX_GPU_DEVICES];
    int device_batches[ONNX_MAX_GPU_DEVICES];
    int num_workers = 1;
    int setup_failure_device = -1;

    memset(handles, 0, sizeof(handles));
    memset(device_batches, 0, sizeof(device_batches));
    handles[0] = h;
    device_batches[0] = batch;
    if (! strcasecmp(accel, "cuda")) {
        const int *devices = onnx_resolved_device_list();
        int ndev = onnx_resolved_num_devices();

        if (ndev > ONNX_MAX_GPU_DEVICES) {
            ndev = ONNX_MAX_GPU_DEVICES;
        }
        for (int d = 1; d < ndev; d++) {
            gpu_batch_spec_t device_plan = plan;
            char device_label[64];
            int device_batch;
            elf_onnx_handle_t extra = NULL;

            snprintf(device_label, sizeof(device_label), "elf-gpu%d", devices[d]);
            device_plan.device_id = onnx_cuda_physical_device(devices[d]);
            device_plan.label = device_label;
            device_batch = gpu_plan_batch(&device_plan);

            while (! extra) {
                int probe_result;

                extra = elf_onnx_create_batch_device_threads(
                    model_path, accel, device_batch, devices[d], onnx_threads);
                if (! extra) {
                    setup_failure_device = devices[d];
                    break;
                }
                elf_onnx_set_decode_mode(extra, decode_mode);
                probe_result = elf_onnx_probe_batch(extra, (size_t)device_batch);
                if (probe_result == ELF_ONNX_OK) {
                    break;
                }

                elf_onnx_destroy(extra);
                extra = NULL;
                if (probe_result != ELF_ONNX_RETRYABLE
                    || device_plan.force_batch > 0
                    || device_batch <= ELF_ONNX_MIN_BATCH) {
                    setup_failure_device = devices[d];
                    break;
                }

                int halved = device_batch / 2;

                if (halved < ELF_ONNX_MIN_BATCH) {
                    halved = ELF_ONNX_MIN_BATCH;
                }
                scalpel_log("ELF ONNX trial run failed at batch %d on CUDA "
                            "device %d; retrying with batch %d.\n",
                            device_batch, devices[d], halved);
                device_batch = halved;
            }
            if (setup_failure_device >= 0) {
                break;
            }
            elf_onnx_reset_timing(extra);
            handles[num_workers] = extra;
            device_batches[num_workers] = device_batch;
            num_workers++;
        }
    }

    if (setup_failure_device >= 0) {
        for (int i = 1; i < num_workers; i++) {
            elf_onnx_destroy(handles[i]);
        }
        elf_onnx_global_shutdown();
        block_validation_release_cpu_threads();

        if (! onnx_runtime_fallback_to_cpu(
                "ELF ONNX could not initialize every selected CUDA device")) {
            handle_error(SCALPEL_GENERAL_ABORT,
                         "ELF ONNX could not initialize every CUDA device "
                         "requested with -Y.", __LINE__, __FILE__);
        }

        scalpel_log("ELF ONNX CUDA setup failed on device %d; retrying the "
                    "complete block-validation pass on CPU.\n",
                    setup_failure_device);
        elf_batched_block_validate(needleidx, blocksize);
        return;
    }

    for (int i = 0; i < num_workers; i++) {
        if (elf_onnx_set_decode_threads(handles[i], decode_threads)
            != ELF_ONNX_OK) {
            handle_error(SCALPEL_GENERAL_ABORT,
                         "ELF ONNX could not configure its CPU postprocessing "
                         "worker budget.", __LINE__, __FILE__);
        }
    }
    scalpel_log("ELF ONNX CPU budget: %d physical cores "
                "(ONNX intra-op %d, postprocessing %d).\n",
                cpu_threads, onnx_threads, decode_threads);

    // watch for a checkpoint-and-exit request for the duration of the pass
    ElfExitWatcher watcher;
    pthread_t watcher_thread;
    bool watcher_started = false;
    atomic_int shared_failure;

    atomic_init(&shared_failure, ELF_ONNX_OK);
    atomic_init(&watcher.stop, false);
    atomic_init(&watcher.terminated, false);
    watcher.failure = &shared_failure;
    watcher.handles = handles;
    watcher.num_handles = num_workers;
    if (pthread_create(&watcher_thread, NULL, elf_exit_watcher, &watcher) != 0) {
        handle_error(SCALPEL_ERROR_PTHREAD_FAILURE,
                     "ELF exit watcher thread creation", __LINE__, __FILE__);
    }
    watcher_started = true;

    // shared pass state. Each device retains its independently proven batch size.
    const uint64_t num_blocks = filemirror_apparent_blocks(scalpel_state.filemirror);
    const uint32_t chunks_per_block = (blocksize + 4095u) / 4096u;
    atomic_ullong next_apparent;
    pthread_mutex_t report_lock;
    long last_report = time(NULL);
    struct timespec elf_start_time;
    ElfValidateWorker workers[ONNX_MAX_GPU_DEVICES];
    pthread_t worker_threads[ONNX_MAX_GPU_DEVICES];

    uint64_t fair_share = num_blocks / ((uint64_t)num_workers * 4u);

    atomic_bool interrupt_reported;

    atomic_init(&next_apparent, 0);
    atomic_init(&interrupt_reported, false);
    MUTEX_ERROR_CHECK(pthread_mutex_init(&report_lock, NULL), __LINE__, __FILE__);
    clock_gettime(CLOCK_MONOTONIC, &elf_start_time);

    for (int i = 0; i < num_workers; i++) {
        uint32_t flush_capacity = (uint32_t)device_batches[i];
        uint64_t claim_blocks = ELF_WORK_CHUNK_BLOCKS;
        uint64_t claim_floor;

        if (flush_capacity < chunks_per_block) {
            flush_capacity =
                ((chunks_per_block + (uint32_t)device_batches[i] - 1u)
                 / (uint32_t)device_batches[i])
                * (uint32_t)device_batches[i];
        }
        claim_floor = flush_capacity / chunks_per_block;
        if (claim_floor == 0) {
            claim_floor = 1;
        }
        if (claim_blocks > fair_share) {
            claim_blocks = fair_share;
        }
        if (claim_blocks < claim_floor) {
            claim_blocks = claim_floor;
        }

        workers[i].h = handles[i];
        workers[i].fm = scalpel_state.filemirror;
        workers[i].needleidx = needleidx;
        workers[i].blocksize = blocksize;
        workers[i].num_blocks = num_blocks;
        workers[i].claim_blocks = claim_blocks;
        workers[i].flush_capacity = flush_capacity;
        workers[i].next_apparent = &next_apparent;
        workers[i].shared_failure = &shared_failure;
        workers[i].interrupt_reported = &interrupt_reported;
        workers[i].report_lock = &report_lock;
        workers[i].last_report = &last_report;
        workers[i].phase_start = &elf_start_time;
        workers[i].worker_id = i;
    }

    for (int i = 1; i < num_workers; i++) {
        if (pthread_create(&worker_threads[i], NULL, elf_validate_worker,
                           &workers[i]) != 0) {
            handle_error(SCALPEL_GENERAL_ABORT, "ELF validation worker thread creation",
                         __LINE__, __FILE__);
        }
    }

    // this thread services the cursor too, as worker 0
    elf_validate_worker(&workers[0]);

    for (int i = 1; i < num_workers; i++) {
        pthread_join(worker_threads[i], NULL);
    }

    int inference_failure =
        atomic_load_explicit(&shared_failure, memory_order_acquire);

    if (watcher_started) {
        atomic_store_explicit(&watcher.stop, true, memory_order_release);
        pthread_join(watcher_thread, NULL);
    }
    block_validation_release_cpu_threads();

    MUTEX_ERROR_CHECK(pthread_mutex_destroy(&report_lock), __LINE__, __FILE__);

    for (int i = 1; i < num_workers; i++) {
        elf_onnx_destroy(handles[i]);
    }

    if (inference_failure != ELF_ONNX_OK) {
        elf_onnx_global_shutdown();

        if (! strcasecmp(accel, "cpu")) {
            handle_error(SCALPEL_GENERAL_ABORT,
                         "ELF ONNX inference failed on the CPU execution provider; "
                         "partial block decisions were rejected.",
                         __LINE__, __FILE__);
        }
        if (! onnx_runtime_fallback_to_cpu(
                "The accelerated ELF inference pass failed at runtime")) {
            handle_error(SCALPEL_GENERAL_ABORT,
                         "ELF ONNX inference failed on the execution provider "
                         "requested with -Y; partial block decisions were rejected.",
                         __LINE__, __FILE__);
        }

        scalpel_log("ELF ONNX is retrying the complete block-validation pass on CPU.\n");
        elf_batched_block_validate(needleidx, blocksize);
        return;
    }

    // teardown: write the timing report, then shut the session down
    {
        char timing_path[PATH_MAX];

        snprintf(timing_path, sizeof(timing_path), "%s/elf_onnx_timing.csv",
                 scalpel_state.base_output_directory);
        if (elf_onnx_global_write_timing_report(timing_path) != ELF_ONNX_OK) {
            scalpel_log("WARNING: Failed to write ELF ONNX timing report to %s.\n",
                        timing_path);
        }
        else {
            scalpel_log("ELF ONNX timing report written to %s.\n", timing_path);
        }
    }

    elf_onnx_global_shutdown();
}


