/* Dump the blockvector layout as seen by the FULL check:
 *  - apparent blocknumber per slot
 *  - whether it's placed / unfilled
 *  - expected section mask
 *  - whether any choices remain for that slot.
 */
static void elf_debug_dump_bv_layout(const char *cid,
                                     CarveInfo  *candidate,
                                     FileState  *filestate,
                                     const char *tag)
{
    (void)filestate;  /* unused in this lightweight version */

    if (!candidate || !candidate->b) {
        lock_fprintf(stdout,
            "[ELF-reass][%s] [BV-length][%s] candidate or blockvector is NULL\n",
            cid, tag ? tag : "");
        return;
    }

    uint64_t nb  = blockvector_get_num_blocks(candidate->b);
    uint64_t len = blockvector_get_data_length(candidate->b);

    int64_t last_ac = -1;
    if (nb > 0) {
        uint64_t last_slot = nb - 1;
        last_ac = blockvector_get_actual_blocknumber(candidate->b, last_slot);
    }

    lock_fprintf(stdout,
        "[ELF-reass][%s] [BV-length][%s] num_blocks=%" PRIu64
        " data_length=%" PRIu64 " last_bv_ac=%" PRId64 "\n",
        cid, tag ? tag : "", nb, len, last_ac);
}
